window.BANCO = window.BANCO || [];
window.BANCO.push({"id": "tema1", "nombre": "Tema 1 · La Constitución Española de 1978", "bloques": [{"id": "t1-preliminar", "nombre": "Estructura, Preámbulo y Título Preliminar (arts. 1 a 9)"}, {"id": "t1-derechos", "nombre": "Derechos y deberes fundamentales (arts. 10 a 52)"}, {"id": "t1-garantias", "nombre": "Garantías de los derechos (art. 53)"}, {"id": "t1-suspension", "nombre": "Suspensión de derechos y estados excepcionales (arts. 55 y 116)"}, {"id": "t1-defensor", "nombre": "El Defensor del Pueblo (art. 54 y LO 3/1981)"}, {"id": "t1-tc", "nombre": "El Tribunal Constitucional (Título IX y LOTC)"}, {"id": "t1-reforma", "nombre": "La reforma de la Constitución (Título X)"}], "calendarios": {}, "casos": [], "preguntas": [{"id": "ce-001", "origen": "otras", "test": "Test exámenes", "n": 2, "enunciado": "¿En qué parte de la Constitución Española se regula la nacionalidad española?:", "opciones": ["En el Título Preliminar.", "En el Preámbulo.", "En el Título Primero.", "En el Título Segundo."], "bloque": "t1-preliminar", "precepto": "Artículo 11.1 CE", "correcta": 2, "justificaciones": ["No. El Título Preliminar son los artículos 1 a 9 y termina en el principio de legalidad: no llega al 11.", "No. El Preámbulo no tiene artículos, es una declaración de intenciones sin contenido normativo directo.", "Es esta. El artículo 11 abre el Capítulo I del Título I, «De los españoles y los extranjeros». El Título I va del artículo 10 al 55, así que la nacionalidad cae dentro.", "No. El Título II es «De la Corona», artículos 56 a 65."], "arts": [11], "citas": [{"texto": "«La nacionalidad española se adquiere, se conserva y se pierde de acuerdo con lo establecido por la ley.»", "fuente": "Artículo 11.1 CE"}], "truco": "El Título I arranca en el artículo 10 y acaba en el 55. Si el artículo que te preguntan está entre esos dos números, es Título I."}, {"id": "ce-002", "origen": "otras", "test": "Test exámenes", "n": 3, "enunciado": "De acuerdo con su Preámbulo, ¿quién ratifica la Constitución Española de 1978?:", "opciones": ["El Rey.", "El pueblo español.", "Las Cortes Generales.", "El Gobierno."], "bloque": "t1-preliminar", "precepto": "Preámbulo CE · párrafo de cierre", "correcta": 1, "justificaciones": ["No. El Rey sanciona y promulga (art. 62.a); firmó el texto el 27 de diciembre de 1978, pero no lo ratifica.", "Es esta. El propio Preámbulo separa los dos verbos: las Cortes aprueban y el pueblo español ratifica.", "No. Las Cortes aprueban, no ratifican: son los dos sujetos que el Preámbulo contrapone.", "No. El Gobierno no interviene en la aprobación ni en la ratificación de la Constitución."], "arts": [], "citas": [{"texto": "«En consecuencia, las Cortes aprueban y el pueblo español ratifica la siguiente CONSTITUCIÓN.»", "fuente": "Preámbulo CE · párrafo de cierre"}], "truco": "Tres verbos, tres sujetos y tres fechas: las Cortes APRUEBAN (31-X-1978), el pueblo RATIFICA en referéndum (6-XII-1978), el Rey SANCIONA (27-XII-1978). Publicación y entrada en vigor, 29-XII-1978."}, {"id": "ce-003", "origen": "otras", "test": "Test exámenes", "n": 35, "enunciado": "En relación con la estructura de la Constitución Española de 1978, señale la respuesta correcta:", "opciones": ["El Título IV De la Corona, que comprende los artículos 56 a 65, regula además de las funciones del Rey, la Regencia y la tutela del Rey.", "El Capítulo I De las Cámaras del Título III De las Cortes Generales está dividido en dos secciones, dedicadas al Congreso y al Senado, respectivamente.", "El Capítulo IV De las garantías de las libertades y derechos fundamentales del Título I De los derechos y deberes fundamentales incluye la regulación de la institución del Defensor del Pueblo.", "El Título VIII De la organización territorial del Estado comprende 3 Capítulos que llevan por título De la Administración General del Estado, De la Administración Local y De las Comunidades Autónomas."], "bloque": "t1-preliminar", "precepto": "Artículo 54 CE", "correcta": 2, "justificaciones": ["No. La Corona es el Título II, no el IV. Los artículos (56 a 65) y el contenido sí son correctos: el error está solo en el número del título.", "No. El Capítulo I del Título III, «De las Cámaras», no se divide en secciones. La división en secciones existe en el Capítulo II del Título I, no ahí.", "Es esta. El Capítulo IV del Título I, «De las garantías de las libertades y derechos fundamentales», son solo dos artículos, el 53 y el 54, y el 54 es precisamente el que crea el Defensor del Pueblo.", "No. Los tres capítulos del Título VIII son «Principios generales», «De la Administración Local» y «De las Comunidades Autónomas». No hay ninguno dedicado a la Administración General del Estado."], "arts": [54], "citas": [{"texto": "«Una ley orgánica regulará la institución del Defensor del Pueblo, como alto comisionado de las Cortes Generales, designado por éstas para la defensa de los derechos comprendidos en este Título, a cuyo efecto podrá supervisar la actividad de la Administración, dando cuenta a las Cortes Generales.»", "fuente": "Artículo 54 CE"}], "marca": {"nivel": "clave", "nota": "El Defensor del Pueblo en la Constitución: alto comisionado de las Cortes, por ley orgánica."}, "truco": "El Defensor del Pueblo no tiene título propio: aparece como garantía en el artículo 54 (Capítulo IV del Título I) y se desarrolla en la LO 3/1981."}, {"id": "ce-004", "origen": "otras", "test": "Test exámenes", "n": 39, "enunciado": "¿Cuántos artículos tiene la vigente Constitución Española (en adelante CE)?", "opciones": ["169.", "196.", "179.", "197."], "bloque": "t1-preliminar", "precepto": "Artículo 169 CE · el último del texto", "correcta": 0, "justificaciones": ["Es esta. El 169 es el último artículo del texto: la Constitución tiene 169 artículos, más el Preámbulo, 4 disposiciones adicionales, 9 transitorias, 1 derogatoria y 1 final.", "No. 196 es 169 con las cifras cambiadas de orden: es la trampa clásica de esta pregunta.", "No. 179 no corresponde a nada del texto constitucional.", "No. 197 tampoco: ninguna versión de la Constitución ha tenido ese número de artículos."], "arts": [169], "citas": [{"texto": "«No podrá iniciarse la reforma constitucional en tiempo de guerra o de vigencia de alguno de los estados previstos en el artículo 116.»", "fuente": "Artículo 169 CE · el último del texto"}], "truco": "El último artículo de la Constitución es el 169 y prohíbe reformarla en tiempo de guerra. Si recuerdas el final, recuerdas el número."}, {"id": "ce-005", "origen": "otras", "test": "Test exámenes", "n": 40, "enunciado": "Son características de la Constitución Española:", "opciones": ["Su carácter abierto y de fácil modificación.", "Su poca extensión y su falta de definición de un modelo territorial.", "Su carácter escrito, extenso y rígido en su contenido.", "Su falta de definición del modelo de Estado."], "bloque": "t1-preliminar", "precepto": "Artículo 168.1 CE", "correcta": 2, "justificaciones": ["No. Justo lo contrario: es rígida. No hay reforma posible por mayoría simple.", "No. Es extensa (169 artículos) y sí define el modelo territorial, en todo el Título VIII.", "Es esta. Ese artículo es la prueba de la rigidez: reformarla exige mayorías cualificadas y, en las materias más protegidas, disolver las Cortes y referéndum obligatorio. Y es escrita y extensa: 169 artículos.", "No. El modelo de Estado está definido en el artículo 1.1: «Estado social y democrático de Derecho»."], "arts": [168], "citas": [{"texto": "«Cuando se propusiere la revisión total de la Constitución o una parcial que afecte al Título preliminar, al Capítulo segundo, Sección primera del Título I, o al Título II, se procederá a la aprobación del principio por mayoría de dos tercios de cada Cámara, y a la disolución inmediata de las Cortes.»", "fuente": "Artículo 168.1 CE"}], "marca": {"nivel": "estrella", "nota": "Reforma ordinaria y agravada: mayorías, referéndum y qué títulos van por el 168. En todas las listas y en el INAP."}, "truco": "Escrita + extensa + rígida. Las tres opciones falsas niegan justo una de esas tres características."}, {"id": "ce-006", "origen": "otras", "test": "Test exámenes", "n": 42, "enunciado": "Según el artículo 11 de la CE, la nacionalidad española se adquiere, conserva y pierde conforme a lo establecido en:", "opciones": ["La ley.", "Real Decreto del Ministerio de Interior.", "La normativa de la Unión Europea.", "Los tratados internacionales."], "bloque": "t1-preliminar", "precepto": "Artículo 11.1 CE", "correcta": 0, "justificaciones": ["Es esta. El 11.1 remite a «la ley», sin más: es el legislador ordinario quien fija cómo se adquiere, conserva y pierde la nacionalidad.", "No. La Constitución no remite aquí a ningún real decreto ni a un ministerio concreto.", "No. La nacionalidad es competencia exclusiva del Estado: la Unión Europea no la regula.", "No. Los tratados aparecen en el 11.3, pero solo para la doble nacionalidad, no para adquirirla, conservarla o perderla."], "arts": [11], "citas": [{"texto": "«La nacionalidad española se adquiere, se conserva y se pierde de acuerdo con lo establecido por la ley.»", "fuente": "Artículo 11.1 CE"}], "truco": "El 11.1 dice «la ley», a secas. Cuando la Constitución quiere ley orgánica lo dice expresamente (por ejemplo en el 54 o en el 55.2)."}, {"id": "ce-007", "origen": "otras", "test": "Test exámenes", "n": 47, "enunciado": "Según el artículo 1.3 de la Constitución Española, la forma política del Estado español es:", "opciones": ["La Monarquía constitucional.", "La Monarquía democrática.", "La Monarquía parlamentaria.", "La Monarquía de derecho."], "bloque": "t1-preliminar", "precepto": "Artículo 1.3 CE", "correcta": 2, "justificaciones": ["No. «Monarquía constitucional» es el modelo del siglo XIX, en el que el Rey compartía la soberanía. La Constitución no usa esa expresión.", "No. «Monarquía democrática» no aparece en el texto: lo democrático califica al Estado en el 1.1, no a la Monarquía.", "Es esta. Literal del 1.3: Monarquía parlamentaria. El Rey reina pero no gobierna, y sus actos necesitan refrendo.", "No. «Monarquía de derecho» tampoco existe; el «de Derecho» del 1.1 se predica del Estado."], "arts": [1], "citas": [{"texto": "«La forma política del Estado español es la Monarquía parlamentaria.»", "fuente": "Artículo 1.3 CE"}], "marca": {"nivel": "estrella", "nota": "El artículo 1 sale en casi todas las convocatorias: valores superiores, soberanía nacional y monarquía parlamentaria."}, "truco": "El artículo 1 son tres apartados y tres ideas: 1.1 Estado social y democrático de Derecho + los cuatro valores; 1.2 la soberanía reside en el pueblo; 1.3 Monarquía parlamentaria."}, {"id": "ce-008", "origen": "otras", "test": "Test exámenes", "n": 53, "enunciado": "¿Cuáles de los siguientes se propugna como valores superiores del ordenamiento jurídico español de acuerdo con el artículo 1.1 de la Constitución Española?:", "opciones": ["La democracia y el pluralismo político.", "La justicia y la libertad.", "La igualdad y el Estado social.", "La legalidad y la Nación española."], "bloque": "t1-preliminar", "precepto": "Artículo 1.1 CE", "correcta": 1, "justificaciones": ["No. El pluralismo político sí es valor superior, pero la democracia no: lo democrático califica al Estado, no es un valor de la lista.", "Es esta. Los valores superiores son cuatro: libertad, justicia, igualdad y pluralismo político. De los pares que ofrece la pregunta, el único formado por dos de esos cuatro es «la justicia y la libertad».", "No. La igualdad sí está en la lista, pero el «Estado social» es la definición del Estado, no un valor superior.", "No. Ni la legalidad (que es un principio del 9.3) ni la Nación española (artículo 2) son valores superiores."], "arts": [1], "citas": [{"texto": "«España se constituye en un Estado social y democrático de Derecho, que propugna como valores superiores de su ordenamiento jurídico la libertad, la justicia, la igualdad y el pluralismo político.»", "fuente": "Artículo 1.1 CE"}], "marca": {"nivel": "estrella", "nota": "El artículo 1 sale en casi todas las convocatorias: valores superiores, soberanía nacional y monarquía parlamentaria."}, "truco": "Los cuatro valores caben en LIJP: Libertad, Igualdad, Justicia, Pluralismo político. Si en la opción aparece algo que no esté en esas cuatro palabras, está mal."}, {"id": "ce-009", "origen": "otras", "test": "Test exámenes", "n": 64, "enunciado": "De conformidad con la CE, España se constituye en un Estado social y democrático de Derecho, que propugna como valores superiores de su ordenamiento jurídico:", "opciones": ["La libertad, la igualdad y la fraternidad.", "La libertad de expresión, libertad de cátedra y libertad sindical.", "La libertad, la justicia, la igualdad y el pluralismo político.", "La dignidad humana, la libertad, la democracia, la igualdad, Estado de Derecho y respeto a los derechos humanos."], "bloque": "t1-preliminar", "precepto": "Artículo 1.1 CE", "correcta": 2, "justificaciones": ["No. «Libertad, igualdad y fraternidad» es el lema de la Revolución francesa, no del artículo 1.1.", "No. Son tres derechos concretos (libertad de expresión (20.1.a), libertad de cátedra (20.1.c) y libertad sindical (28.1)), no valores superiores.", "Es esta. Reproduce el 1.1 palabra por palabra y en su mismo orden: libertad, justicia, igualdad y pluralismo político.", "No. Es la lista del artículo 2 del Tratado de la Unión Europea, no de la Constitución española."], "arts": [1], "citas": [{"texto": "«España se constituye en un Estado social y democrático de Derecho, que propugna como valores superiores de su ordenamiento jurídico la libertad, la justicia, la igualdad y el pluralismo político.»", "fuente": "Artículo 1.1 CE"}], "marca": {"nivel": "estrella", "nota": "El artículo 1 sale en casi todas las convocatorias: valores superiores, soberanía nacional y monarquía parlamentaria."}}, {"id": "ce-010", "origen": "otras", "test": "Test exámenes", "n": 78, "enunciado": "El Título Preliminar de la Constitución Española de 1978 engloba una serie de preceptos entre los que se encuentra el relativo a:", "opciones": ["La regulación sobre la adquisición de la nacionalidad española.", "La naturaleza, funcionamiento y estructura de los partidos políticos.", "La entrada en vigor de la propia Constitución.", "El reconocimiento de los derechos históricos de los territorios forales."], "bloque": "t1-preliminar", "precepto": "Artículo 6 CE", "correcta": 1, "justificaciones": ["No. La nacionalidad es el artículo 11, ya dentro del Título I.", "Es esta. El artículo 6 está en el Título Preliminar (artículos 1 a 9) y regula exactamente eso: naturaleza, funcionamiento y estructura interna de los partidos.", "No. La entrada en vigor está en la disposición final, no en el Título Preliminar.", "No. Los derechos históricos de los territorios forales están en la disposición adicional primera."], "arts": [6], "citas": [{"texto": "«Los partidos políticos expresan el pluralismo político, concurren a la formación y manifestación de la voluntad popular y son instrumento fundamental para la participación política. Su creación y el ejercicio de su actividad son libres dentro del respeto a la Constitución y a la ley. Su estructura interna y funcionamiento deberán ser democráticos.»", "fuente": "Artículo 6 CE"}], "truco": "El Título Preliminar en nueve artículos: 1 Estado y valores · 2 unidad y autonomía · 3 lenguas · 4 bandera · 5 capital · 6 partidos · 7 sindicatos · 8 Fuerzas Armadas · 9 legalidad."}, {"id": "ce-011", "origen": "otras", "test": "Test exámenes", "n": 109, "enunciado": "El preámbulo de la Constitución Española comienza con: “La Nación española, deseando establecer:", "opciones": ["La igualdad, la libertad y la seguridad.", "La justicia, la libertad y la seguridad.", "La justicia, la libertad y la igualdad.", "La justicia, la libertad y la convivencia democrática."], "bloque": "t1-preliminar", "precepto": "Preámbulo CE · párrafo de apertura", "correcta": 1, "justificaciones": ["No. Cambia «justicia» por «igualdad». Es justo la opción que marca por error la plantilla de la academia.", "Es esta. La terna del arranque del Preámbulo es justicia, libertad y seguridad, en ese orden.", "No. Cambia «seguridad» por «igualdad»: la igualdad no está en el arranque del Preámbulo.", "No. Cambia «seguridad» por «convivencia democrática», que sí aparece en el Preámbulo, pero más abajo, entre los objetivos («garantizar la convivencia democrática»)."], "arts": [], "citas": [{"texto": "«La Nación española, deseando establecer la justicia, la libertad y la seguridad y promover el bien de cuantos la integran, en uso de su soberanía, proclama su voluntad de: […]»", "fuente": "Preámbulo CE · párrafo de apertura"}], "ojo": "La plantilla del documento original marca la opción «la igualdad, la libertad y la seguridad», pero el texto del Preámbulo dice «la justicia». Aquí se ha corregido. Y no confundas esta terna con los cuatro valores superiores del artículo 1.1: libertad, justicia, igualdad y pluralismo político.", "truco": "En el Preámbulo son TRES y no está la igualdad: Justicia, Libertad, Seguridad. En el artículo 1.1 son CUATRO y sí entra la igualdad."}, {"id": "ce-012", "origen": "otras", "test": "Examen", "n": 1, "enunciado": "La Constitución Española de 1978 consta de:", "opciones": ["Un Preámbulo, 269 artículos, 6 disposiciones adicionales, 9 disposiciones transitorias, 1 disposición derogatoria y 1 disposición final.", "Un Título Preliminar, 396 artículos, 4 disposiciones adicionales, 4 disposiciones transitorias, 1 disposición derogatoria y 1 disposición final.", "Un Preámbulo, 169 artículos, 4 disposiciones adicionales, 9 disposiciones transitorias, 1 disposición derogatoria y 1 disposición final.", "Un Preámbulo, 166 artículos, 14 disposiciones adicionales, 10 disposiciones transitorias, 10 disposiciones derogatorias y 1 disposición final."], "bloque": "t1-preliminar", "precepto": "Artículo 169 CE · el último del texto", "correcta": 2, "justificaciones": ["No. Acierta en las 9 transitorias, pero da 269 artículos y 6 disposiciones adicionales.", "No. Empieza por «un Título Preliminar» en vez del Preámbulo, y da 396 artículos y 4 transitorias.", "Es esta. La estructura es Preámbulo, 169 artículos repartidos en un Título Preliminar y diez títulos, 4 disposiciones adicionales, 9 transitorias, 1 derogatoria y 1 final.", "No. Da 166 artículos, 14 adicionales, 10 transitorias y 10 derogatorias: de las cinco cifras solo acierta la disposición final."], "arts": [169], "citas": [{"texto": "«No podrá iniciarse la reforma constitucional en tiempo de guerra o de vigencia de alguno de los estados previstos en el artículo 116.»", "fuente": "Artículo 169 CE · el último del texto"}], "truco": "Cinco cifras en cadena: 169 - 4 - 9 - 1 - 1. Artículos, adicionales, transitorias, derogatoria y final."}, {"id": "ce-013", "origen": "otras", "test": "Test 1", "n": 1, "enunciado": "Cada uno de los tres grandes poderes del Estado está regulado en un título propio en la Constitución. Nos referimos a:", "opciones": ["Título III para el poder ejecutivo, Título IV para el poder legislativo y Título VI para el poder judicial.", "Título III para el poder legislativo, Título IV para el poder judicial y Título VI para el poder ejecutivo.", "Título III para el poder legislativo, Título IV para el poder ejecutivo y Título VI para el poder judicial.", "Título III para el poder judicial, Título IV para el poder ejecutivo y Título VI para el poder legislativo."], "bloque": "t1-preliminar", "precepto": "Constitución Española · rúbricas de los títulos III a VI", "correcta": 2, "justificaciones": ["No. Invierte los dos primeros: coloca el ejecutivo en el III y el legislativo en el IV.", "No. Coloca el judicial en el IV y el ejecutivo en el VI.", "Es esta. Legislativo el III (Cortes Generales), ejecutivo el IV (Gobierno y Administración) y judicial el VI. El Título V, intercalado, no es un poder: regula las relaciones entre el Gobierno y las Cortes.", "No. Coloca el judicial en el III y el legislativo en el VI: los intercambia por completo."], "arts": [], "citas": [{"texto": "«TÍTULO III. De las Cortes Generales» · «TÍTULO IV. Del Gobierno y de la Administración»«TÍTULO V. De las relaciones entre el Gobierno y las Cortes Generales» · «TÍTULO VI. Del Poder Judicial»", "fuente": "Constitución Española · rúbricas de los títulos III a VI"}], "truco": "Van en orden lógico: primero quien hace las leyes (III), luego quien las ejecuta (IV) y por último quien juzga (VI). El V se cuela en medio porque conecta a los dos primeros."}, {"id": "ce-014", "origen": "otras", "test": "Test 1", "n": 4, "enunciado": "El artículo 1.3 de la Constitución establece con toda claridad que la forma política del Estado español es:", "opciones": ["La Monarquía parlamentaria.", "La Monarquía bicameral.", "La Monarquía con separación de poderes.", "La Monarquía democrática."], "bloque": "t1-preliminar", "precepto": "Artículo 1.3 CE", "correcta": 0, "justificaciones": ["Es esta. Literal del 1.3.", "No. El bicameralismo es de las Cortes Generales (artículo 66.1), no una característica de la forma política.", "No. La separación de poderes no aparece con ese nombre en el artículo 1.3.", "No. «Monarquía democrática» no existe en el texto constitucional."], "arts": [1], "citas": [{"texto": "«La forma política del Estado español es la Monarquía parlamentaria.»", "fuente": "Artículo 1.3 CE"}], "marca": {"nivel": "estrella", "nota": "El artículo 1 sale en casi todas las convocatorias: valores superiores, soberanía nacional y monarquía parlamentaria."}, "truco": "La palabra clave es PARLAMENTARIA. Las alternativas («constitucional», «democrática», «bicameral», «de derecho») suenan bien y son todas falsas."}, {"id": "ce-015", "origen": "otras", "test": "Test 1", "n": 16, "enunciado": "El artículo 8 de la Constitución Española establece que las fuerzas armadas tienen como misión:", "opciones": ["Garantizar la unidad e independencia de España", "Garantizar la estabilidad e independencia de la Nación", "Garantizar la soberanía e independencia de la Nación", "Garantizar la soberanía e independencia de España"], "bloque": "t1-preliminar", "precepto": "Artículo 8.1 CE", "correcta": 3, "justificaciones": ["No. Cambia «soberanía» por «unidad».", "No. Cambia dos palabras a la vez: «soberanía» por «estabilidad» y «España» por «la Nación».", "No. Mantiene «soberanía», pero cambia «España» por «la Nación».", "Es esta. Literal: soberanía e independencia de España."], "arts": [8], "citas": [{"texto": "«Las Fuerzas Armadas, constituidas por el Ejército de Tierra, la Armada y el Ejército del Aire, tienen como misión garantizar la soberanía e independencia de España, defender su integridad territorial y el ordenamiento constitucional.»", "fuente": "Artículo 8.1 CE"}], "ojo": "«Soberanía» y «España». Las opciones cambian una por «estabilidad» o «unidad» y la otra por «la Nación».", "truco": "Dos palabras que hay que fijar: SOBERANÍA (no unidad ni estabilidad) y ESPAÑA (no la Nación). Y tres misiones: garantizar soberanía e independencia, defender la integridad territorial, y el ordenamiento constitucional."}, {"id": "ce-169", "origen": "oficiales", "test": "INAP sept 2025", "n": 2, "enunciado": "¿En cuántos títulos se encuentra estructurada la Constitución Española de 1978?", "opciones": ["Un título preliminar y 10 títulos.", "Cinco títulos divididos en 10 subtítulos.", "No se estructura en títulos, sino en apartados.", "Dos títulos divididos en 10 artículos."], "bloque": "t1-preliminar", "precepto": "Estructura de la Constitución · índice del texto consolidado", "correcta": 0, "justificaciones": ["Es esta. Un Título preliminar más diez títulos numerados, del I al X.", "No. La Constitución no tiene «subtítulos»: tiene títulos, capítulos y secciones.", "No. Sí se estructura en títulos; es su división principal.", "No. Ni dos títulos ni diez artículos: son 169 artículos."], "arts": [], "citas": [{"texto": "«Preámbulo · Título preliminar · Títulos I a X · 169 artículos · 4 disposiciones adicionales, 9 transitorias, 1 derogatoria y 1 final.»", "fuente": "Estructura de la Constitución · índice del texto consolidado"}], "truco": "El Título preliminar no cuenta como uno de los diez, y por eso la respuesta suele decir «un preliminar y diez». Los tres poderes tienen título propio: III Cortes, IV Gobierno, VI Poder Judicial."}, {"id": "ce-016", "origen": "otras", "test": "Test exámenes", "n": 1, "enunciado": "La Constitución establece en su artículo 23.2 que los ciudadanos tienen derecho a acceder a las funciones y cargos públicos:", "opciones": ["En condiciones de igualdad, mérito y capacidad.", "En condiciones de mérito y capacidad.", "En condiciones de igualdad.", "En condiciones de igualad, mérito, capacidad y publicidad."], "bloque": "t1-derechos", "precepto": "Artículo 23.2 CE", "correcta": 2, "justificaciones": ["No. Añade el mérito y la capacidad, que son del artículo 103.3.", "No. Sustituye la igualdad por el mérito y la capacidad: cambia el artículo entero.", "Es esta. El 23.2 solo dice «en condiciones de igualdad». Nada más.", "No. Añade además la publicidad, que no aparece ni en el 23.2 ni en el 103.3."], "arts": [23], "citas": [{"texto": "«Asimismo, tienen derecho a acceder en condiciones de igualdad a las funciones y cargos públicos, con los requisitos que señalen las leyes.»", "fuente": "Artículo 23.2 CE"}], "marca": {"nivel": "clave", "nota": "De la Sección 1.ª, los artículos que más repiten las listas: libertad religiosa, detención, intimidad, expresión, participación, tutela judicial y educación."}, "ojo": "No confundas el artículo 23.2 (igualdad; derecho fundamental con amparo) con el 103.3 (mérito y capacidad).", "truco": "23.2 = IGUALDAD (derecho fundamental, con amparo). 103.3 = MÉRITO Y CAPACIDAD (acceso a la función pública, sin amparo). Dos artículos, dos listas, y el examen los mezcla."}, {"id": "ce-017", "origen": "otras", "test": "Test exámenes", "n": 9, "enunciado": "De acuerdo con el artículo 53.2 de la CE, ¿cuál de los siguientes derechos y libertades susceptibles de recurso de amparo ante el Tribunal Constitucional?:", "opciones": ["El derecho a la libertad de cátedra.", "El derecho de fundación.", "El derecho de los trabajadores y empresarios a adoptar medidas de conflicto colectivo.", "La libertad de empresa en el marco de la economía de mercado."], "bloque": "t1-garantias", "precepto": "Artículo 53.2 CE", "correcta": 0, "justificaciones": ["Es esta. La libertad de cátedra es el artículo 20.1.c), dentro de la Sección 1.ª del Capítulo II del Título I (artículos 15 a 29): entra de lleno en el 53.2.", "No. El derecho de fundación es el artículo 34, ya en la Sección 2.ª.", "No. Las medidas de conflicto colectivo son el artículo 37.2, Sección 2.ª.", "No. La libertad de empresa es el artículo 38, el último de la Sección 2.ª."], "arts": [53], "citas": [{"texto": "«Cualquier ciudadano podrá recabar la tutela de las libertades y derechos reconocidos en el artículo 14 y la Sección primera del Capítulo segundo ante los Tribunales ordinarios por un procedimiento basado en los principios de preferencia y sumariedad y, en su caso, a través del recurso de amparo ante el Tribunal Constitucional. Este último recurso será aplicable a la objeción de conciencia reconocida en el artículo 30.»", "fuente": "Artículo 53.2 CE"}], "marca": {"nivel": "estrella", "nota": "Las garantías del artículo 53 (quién vincula, reserva de ley, amparo) están en todas las listas de lo más preguntado."}, "truco": "La frontera del amparo es el artículo 29. Del 14 al 29 (más la objeción de conciencia del 30.2), amparo; del 30 en adelante, no."}, {"id": "ce-018", "origen": "otras", "test": "Test exámenes", "n": 10, "enunciado": "Conforma al artículo 53 de la Constitución Española de 1978, pueden ser objeto de tutela antes los Tribunales ordinarios, por un procedimiento basado en los principios de preferencia y sumariedad:", "opciones": ["Las libertades y derechos reconocidos en el Capítulo primero del Título I de la Constitución.", "Las libertades y derechos reconocidos en la Sección segunda del Capítulo primero del Título I de la Constitucional.", "Las libertades y derechos reconocidos en la Sección segunda del Capítulo segundo del Título I de la Constitución.", "Las libertades y derechos reconocidos en la Sección primera del Capítulo segundo del Título I de la Constitución."], "bloque": "t1-garantias", "precepto": "Artículo 53.2 CE", "correcta": 3, "justificaciones": ["No. El Capítulo I del Título I son los artículos 11 a 13 (españoles y extranjeros), que no están en el 53.2.", "No. El Capítulo I no se divide en secciones: las secciones existen en el Capítulo II.", "No. La Sección 2.ª del Capítulo II (artículos 30 a 38) queda fuera del 53.2.", "Es esta. El 53.2 nombra exactamente dos ámbitos: el artículo 14 y la Sección primera del Capítulo segundo del Título I."], "arts": [53], "citas": [{"texto": "«Cualquier ciudadano podrá recabar la tutela de las libertades y derechos reconocidos en el artículo 14 y la Sección primera del Capítulo segundo ante los Tribunales ordinarios por un procedimiento basado en los principios de preferencia y sumariedad y, en su caso, a través del recurso de amparo ante el Tribunal Constitucional. Este último recurso será aplicable a la objeción de conciencia reconocida en el artículo 30.»", "fuente": "Artículo 53.2 CE"}], "marca": {"nivel": "estrella", "nota": "Las garantías del artículo 53 (quién vincula, reserva de ley, amparo) están en todas las listas de lo más preguntado."}, "truco": "Capítulo SEGUNDO, Sección PRIMERA. Las opciones falsas siempre cambian una de esas dos palabras."}, {"id": "ce-019", "origen": "oficiales", "test": "INAP mar 2022", "n": 1, "enunciado": "Señale la respuesta correcta de acuerdo con el artículo 13 de la Constitución Española:", "opciones": ["Solamente los españoles serán titulares de los derechos reconocidos en el artículo 23, salvo lo que, atendiendo a criterios de reciprocidad, pueda establecerse por tratado o ley para el derecho de sufragio activo y pasivo en las elecciones municipales.", "Solamente los españoles serán titulares de los derechos de sufragio activo y pasivo.", "Solamente los españoles son titulares de los derechos reconocidos en el artículo 23, salvo lo que, atendiendo a criterios de reciprocidad, pueda establecerse por tratado o ley para el derecho de sufragio activo y pasivo en las elecciones municipales y nacionales.", "Solamente los españoles son titulares de los derechos reconocidos en el artículo 23, salvo lo que, atendiendo a criterios de reciprocidad, pueda establecerse por tratado o ley para el derecho de sufragio activo y pasivo en las elecciones autonómicas y municipales."], "bloque": "t1-derechos", "precepto": "Artículo 13.2 CE", "correcta": 0, "justificaciones": ["Es esta. Reproduce el 13.2 palabra por palabra, incluida la excepción del sufragio activo y pasivo en las elecciones municipales.", "No. Se queda a medias: el 13.2 no habla del sufragio en general, sino de los derechos del artículo 23, y esta opción se olvida de la excepción municipal.", "No. Añade «y nacionales» a las elecciones: el 13.2 solo dice municipales.", "No. Añade «autonómicas»: tampoco están en el 13.2."], "arts": [13], "citas": [{"texto": "«Solamente los españoles serán titulares de los derechos reconocidos en el artículo 23, salvo lo que, atendiendo a criterios de reciprocidad, pueda establecerse por tratado o ley para el derecho de sufragio activo y pasivo en las elecciones municipales.»", "fuente": "Artículo 13.2 CE"}], "marca": {"nivel": "clave", "nota": "Extranjeros (art. 13): el 13.2 y el voto municipal caen a menudo, también en el INAP."}, "ojo": "Solo municipales. Cualquier opción que añada autonómicas o nacionales es falsa.", "truco": "Solo MUNICIPALES. Viene de la reforma de 1992 (Tratado de Maastricht) y solo abrió el ámbito local."}, {"id": "ce-020", "origen": "otras", "test": "Test exámenes", "n": 17, "enunciado": "De acuerdo con el artículo 53.1 de la Constitución, señale el derecho o libertad pública que podrá regularse sólo por ley:", "opciones": ["El derecho a la protección de la salud.", "Derecho a una vivienda digna adecuada.", "El derecho al acceso a la cultura.", "Derecho a la negociación colectiva laboral."], "bloque": "t1-garantias", "precepto": "Artículo 53.1 CE", "correcta": 3, "justificaciones": ["No. La protección de la salud es el artículo 43, Capítulo III: le corresponde el 53.3.", "No. La vivienda digna es el artículo 47, Capítulo III.", "No. El acceso a la cultura es el artículo 44, Capítulo III.", "Es esta. El 53.1 alcanza a todo el Capítulo II del Título I (artículos 14 a 38) y la negociación colectiva laboral es el artículo 37.1."], "arts": [53], "citas": [{"texto": "«Los derechos y libertades reconocidos en el Capítulo segundo del presente Título vinculan a todos los poderes públicos. Sólo por ley, que en todo caso deberá respetar su contenido esencial, podrá regularse el ejercicio de tales derechos y libertades, que se tutelarán de acuerdo con lo previsto en el artículo 161, 1, a).»", "fuente": "Artículo 53.1 CE"}], "marca": {"nivel": "estrella", "nota": "Las garantías del artículo 53 (quién vincula, reserva de ley, amparo) están en todas las listas de lo más preguntado."}, "truco": "Los tres descartes son principios rectores (Capítulo III, artículos 39 a 52). Salud, vivienda y cultura son el trío de principios rectores que más se repite en los test."}, {"id": "ce-021", "origen": "otras", "test": "Test exámenes", "n": 18, "enunciado": "De acuerdo con la Constitución, señale cuál de los siguientes derechos puede ser objeto de recurso de amparo:", "opciones": ["El derecho de participación política.", "El derecho a la propiedad privada.", "El derecho al trabajo.", "El derecho a la negociación colectiva."], "bloque": "t1-garantias", "precepto": "Artículo 53.2 CE", "correcta": 0, "justificaciones": ["Es esta. El derecho a participar en los asuntos públicos es el artículo 23, dentro de la Sección 1.ª: tiene amparo.", "No. La propiedad privada es el artículo 33, Sección 2.ª.", "No. El derecho al trabajo es el artículo 35, Sección 2.ª.", "No. La negociación colectiva es el artículo 37, Sección 2.ª."], "arts": [53], "citas": [{"texto": "«Cualquier ciudadano podrá recabar la tutela de las libertades y derechos reconocidos en el artículo 14 y la Sección primera del Capítulo segundo ante los Tribunales ordinarios por un procedimiento basado en los principios de preferencia y sumariedad y, en su caso, a través del recurso de amparo ante el Tribunal Constitucional. Este último recurso será aplicable a la objeción de conciencia reconocida en el artículo 30.»", "fuente": "Artículo 53.2 CE"}], "marca": {"nivel": "estrella", "nota": "Las garantías del artículo 53 (quién vincula, reserva de ley, amparo) están en todas las listas de lo más preguntado."}}, {"id": "ce-022", "origen": "otras", "test": "Test exámenes", "n": 23, "enunciado": "Según la Constitución, es un principio rector de la política social y económica:", "opciones": ["La salvaguardia de los derechos económicos y sociales de los trabajadores en el extranjero.", "La libertad de empresa en el marco de la economía de mercado.", "La libertad de enseñanza.", "El pleno desarrollo de la personalidad humana."], "bloque": "t1-derechos", "precepto": "Artículo 42 CE", "correcta": 0, "justificaciones": ["Es esta. El artículo 42 está en el Capítulo III del Título I, «De los principios rectores de la política social y económica».", "No. La libertad de empresa es el artículo 38, el último del Capítulo II.", "No. La libertad de enseñanza es el artículo 27.1, Capítulo II, Sección 1.ª.", "No. El pleno desarrollo de la personalidad humana no es un derecho: es el objeto que el 27.2 asigna a la educación."], "arts": [42], "citas": [{"texto": "«El Estado velará especialmente por la salvaguardia de los derechos económicos y sociales de los trabajadores españoles en el extranjero y orientará su política hacia su retorno.»", "fuente": "Artículo 42 CE"}], "truco": "El Capítulo III va del artículo 39 al 52. Cualquier artículo con número entre esos dos es principio rector."}, {"id": "ce-023", "origen": "otras", "test": "Test exámenes", "n": 29, "enunciado": "Según la CE, es un derecho fundamental:", "opciones": ["Derecho a contraer matrimonio con plena igualdad jurídica.", "Derecho a la libertad de cátedra.", "Derecho a la propiedad privada.", "Derecho a la libre elección de profesión u oficio."], "bloque": "t1-derechos", "precepto": "Artículo 20.1 CE", "correcta": 1, "justificaciones": ["No. El matrimonio es el artículo 32, Sección 2.ª.", "Es esta. La libertad de cátedra es el artículo 20.1.c), en la Sección 1.ª del Capítulo II: derecho fundamental en sentido estricto.", "No. La propiedad privada es el artículo 33, Sección 2.ª.", "No. La libre elección de profesión u oficio es el artículo 35, Sección 2.ª."], "arts": [20], "citas": [{"texto": "«Se reconocen y protegen los derechos: a) A expresar y difundir libremente los pensamientos, ideas y opiniones mediante la palabra, el escrito o cualquier otro medio de reproducción. b) A la producción y creación literaria, artística, científica y técnica. c) A la libertad de cátedra. d) A comunicar o recibir libremente información veraz por cualquier medio de difusión. […]»", "fuente": "Artículo 20.1 CE"}], "marca": {"nivel": "clave", "nota": "De la Sección 1.ª, los artículos que más repiten las listas: libertad religiosa, detención, intimidad, expresión, participación, tutela judicial y educación."}}, {"id": "ce-024", "origen": "otras", "test": "Test exámenes", "n": 36, "enunciado": "Según el artículo 10.1 de la CE, ¿cuál es el fundamento del orden político y la paz social?:", "opciones": ["La libertad y la igualdad del individuo y de los grupos.", "El respeto de los ciudadanos y los poderes públicos a la Constitución y al resto del ordenamiento jurídico.", "La dignidad de la persona, los derechos inviolables que le son inherentes, el libre desarrollo de la personalidad, el respeto a la ley y a los derechos de los demás.", "La participación de todos los ciudadanos en la vida política, económica, cultural y social."], "bloque": "t1-derechos", "precepto": "Artículo 10.1 CE", "correcta": 2, "justificaciones": ["No. Es el artículo 9.2: corresponde a los poderes públicos hacer reales y efectivas la libertad y la igualdad del individuo y de los grupos.", "No. Es el artículo 9.1: la sujeción de los ciudadanos y los poderes públicos a la Constitución y al resto del ordenamiento.", "Es esta. Literal del 10.1, con sus cuatro elementos: dignidad, derechos inviolables, libre desarrollo de la personalidad y respeto a la ley y a los derechos de los demás.", "No. Es también el artículo 9.2: facilitar la participación de todos los ciudadanos en la vida política, económica, cultural y social."], "arts": [10], "citas": [{"texto": "«La dignidad de la persona, los derechos inviolables que le son inherentes, el libre desarrollo de la personalidad, el respeto a la ley y a los derechos de los demás son fundamento del orden político y de la paz social.»", "fuente": "Artículo 10.1 CE"}], "truco": "El artículo 10 abre el Título I y es la bisagra del texto. Aquí las tres opciones falsas salen todas del artículo 9: si dudas, mira si la frase habla de «poderes públicos» (9) o de «la persona» (10)."}, {"id": "ce-025", "origen": "otras", "test": "Test exámenes", "n": 37, "enunciado": "Según la CE, ¿cuál de los siguientes derechos podrá ser objeto de recurso de amparo ante el Tribunal Constitucional?:", "opciones": ["El derecho al trabajo.", "El derecho de reunión.", "El derecho a la protección de la familia.", "El derecho a la protección de la salud."], "bloque": "t1-garantias", "precepto": "Artículo 53.2 CE", "correcta": 1, "justificaciones": ["No. El derecho al trabajo es el artículo 35, Sección 2.ª.", "Es esta. El derecho de reunión es el artículo 21, en la Sección 1.ª: tiene amparo.", "No. La protección de la familia es el artículo 39, Capítulo III.", "No. La protección de la salud es el artículo 43, Capítulo III."], "arts": [53], "citas": [{"texto": "«Cualquier ciudadano podrá recabar la tutela de las libertades y derechos reconocidos en el artículo 14 y la Sección primera del Capítulo segundo ante los Tribunales ordinarios por un procedimiento basado en los principios de preferencia y sumariedad y, en su caso, a través del recurso de amparo ante el Tribunal Constitucional. Este último recurso será aplicable a la objeción de conciencia reconocida en el artículo 30.»", "fuente": "Artículo 53.2 CE"}], "marca": {"nivel": "estrella", "nota": "Las garantías del artículo 53 (quién vincula, reserva de ley, amparo) están en todas las listas de lo más preguntado."}}, {"id": "ce-026", "origen": "otras", "test": "Test exámenes", "n": 50, "enunciado": "De acuerdo a lo establecido en la CE, el derecho de petición individual y colectiva se considera:", "opciones": ["Un derecho y deber de los ciudadanos.", "Un principio rector de la política social y económica.", "Un derecho fundamental.", "Un valor social para los ciudadanos."], "bloque": "t1-derechos", "precepto": "Artículo 29.1 CE", "correcta": 2, "justificaciones": ["No. Los «derechos y deberes de los ciudadanos» son la rúbrica de la Sección 2.ª (artículos 30 a 38), donde el 29 no está.", "No. Los principios rectores son el Capítulo III (artículos 39 a 52).", "Es esta. El artículo 29 es el último de la Sección 1.ª del Capítulo II: derecho fundamental, con amparo y con procedimiento preferente y sumario.", "No. «Valor social» no es ninguna de las categorías que usa la Constitución."], "arts": [29], "citas": [{"texto": "«Todos los españoles tendrán el derecho de petición individual y colectiva, por escrito, en la forma y con los efectos que determine la ley.»", "fuente": "Artículo 29.1 CE"}], "truco": "El 29 es la frontera: último derecho fundamental. El 30 (defender España) ya es Sección 2.ª. Petición SÍ, defensa de España NO."}, {"id": "ce-027", "origen": "otras", "test": "Test exámenes", "n": 52, "enunciado": "Según el artículo 13 de la CE, el derecho de sufragio activo y pasivo en las elecciones municipales reconocido en el artículo 23 a los ciudadanos no españoles se podrá reconocer, por tratado internacional o ley, atendiendo a criterios de:", "opciones": ["Reciprocidad.", "Igualdad.", "Legitimidad.", "Soberanía."], "bloque": "t1-derechos", "precepto": "Artículo 13.2 CE", "correcta": 0, "justificaciones": ["Es esta. Literal del 13.2: «atendiendo a criterios de reciprocidad».", "No. La igualdad es el criterio del artículo 14 y del 23.2, no del 13.2.", "No. «Legitimidad» no aparece en el precepto.", "No. La soberanía es del artículo 1.2 y nada tiene que ver con el sufragio de los extranjeros."], "arts": [13], "citas": [{"texto": "«Solamente los españoles serán titulares de los derechos reconocidos en el artículo 23, salvo lo que, atendiendo a criterios de reciprocidad, pueda establecerse por tratado o ley para el derecho de sufragio activo y pasivo en las elecciones municipales.»", "fuente": "Artículo 13.2 CE"}], "marca": {"nivel": "clave", "nota": "Extranjeros (art. 13): el 13.2 y el voto municipal caen a menudo, también en el INAP."}}, {"id": "ce-028", "origen": "otras", "test": "Test exámenes", "n": 55, "enunciado": "De acuerdo con el artículo 53.2 de la Constitución, cualquier ciudadano puede recabar la tutela de derechos y libertades a través del recurso de amparo ante el Tribunal Constitucional. ¿A cuál de los siguientes derechos le sería de aplicación esta previsión?:", "opciones": ["Al derecho a la propiedad y a la herencia.", "Al derecho al matrimonio.", "Al derecho al trabajo.", "Al derecho a la huelga."], "bloque": "t1-garantias", "precepto": "Artículo 53.2 CE; Artículo 28.2 CE", "correcta": 3, "justificaciones": ["No. Propiedad y herencia son el artículo 33, Sección 2.ª.", "No. El matrimonio es el artículo 32, Sección 2.ª.", "No. El derecho al trabajo es el artículo 35, Sección 2.ª.", "Es esta. La huelga es el artículo 28.2, dentro de la Sección 1.ª del Capítulo II: entra en el 53.2 y por tanto tiene amparo."], "arts": [28, 53], "citas": [{"texto": "«Cualquier ciudadano podrá recabar la tutela de las libertades y derechos reconocidos en el artículo 14 y la Sección primera del Capítulo segundo ante los Tribunales ordinarios por un procedimiento basado en los principios de preferencia y sumariedad y, en su caso, a través del recurso de amparo ante el Tribunal Constitucional. Este último recurso será aplicable a la objeción de conciencia reconocida en el artículo 30.»", "fuente": "Artículo 53.2 CE"}, {"texto": "«Se reconoce el derecho a la huelga de los trabajadores para la defensa de sus intereses. La ley que regule el ejercicio de este derecho establecerá las garantías precisas para asegurar el mantenimiento de los servicios esenciales de la comunidad.»", "fuente": "Artículo 28.2 CE"}], "marca": {"nivel": "estrella", "nota": "Las garantías del artículo 53 (quién vincula, reserva de ley, amparo) están en todas las listas de lo más preguntado."}, "truco": "No confundas la HUELGA (28.2, Sección 1.ª, con amparo) con las MEDIDAS DE CONFLICTO COLECTIVO (37.2, Sección 2.ª, sin amparo). Son casi lo mismo y están en distinta sección: es la trampa favorita del examen."}, {"id": "ce-029", "origen": "otras", "test": "Test exámenes", "n": 61, "enunciado": "El derecho a disfrutar de una vivienda digna y adecuada del artículo 47 de la CE goza de la siguiente garantía constitucional de acuerdo con su artículo 53:", "opciones": ["Ante su vulneración cabe recurso de amparo ante el Tribunal Constitucional.", "Sólo podrá ser alegado ante la Jurisdicción ordinaria de acuerdo con lo que disponga la ley orgánica que lo desarrolle.", "Vincula a todos los poderes públicos.", "Su protección informará la legislación positiva, la práctica judicial y la actuación de los poderes públicos."], "bloque": "t1-garantias", "precepto": "Artículo 53.3 CE", "correcta": 3, "justificaciones": ["No. El amparo es del 53.2 y solo alcanza al artículo 14, la Sección 1.ª y la objeción de conciencia.", "No. Es la trampa fina: sí se alegan ante la jurisdicción ordinaria, pero «de acuerdo con lo que dispongan las leyes que los desarrollen», no una ley orgánica.", "No. «Vinculan a todos los poderes públicos» es el 53.1, reservado al Capítulo II.", "Es esta. El derecho a la vivienda digna es el artículo 47, en el Capítulo III: le corresponde el régimen del 53.3, que es informar la legislación positiva, la práctica judicial y la actuación de los poderes públicos."], "arts": [53], "citas": [{"texto": "«El reconocimiento, el respeto y la protección de los principios reconocidos en el Capítulo tercero informarán la legislación positiva, la práctica judicial y la actuación de los poderes públicos. Sólo podrán ser alegados ante la Jurisdicción ordinaria de acuerdo con lo que dispongan las leyes que los desarrollen.»", "fuente": "Artículo 53.3 CE"}], "marca": {"nivel": "estrella", "nota": "Las garantías del artículo 53 (quién vincula, reserva de ley, amparo) están en todas las listas de lo más preguntado."}, "ojo": "La trampa es la opción que habla de alegarlo ante la jurisdicción ordinaria: eso es cierto, pero de acuerdo con «las leyes que los desarrollen», no con una ley orgánica.", "truco": "Tres apartados, tres niveles de garantía: 53.1 → Capítulo II (reserva de ley y contenido esencial); 53.2 → art. 14 + Sección 1.ª (amparo); 53.3 → Capítulo III (solo informan). Memoriza esta escalera y caen muchas preguntas."}, {"id": "ce-030", "origen": "otras", "test": "Test exámenes", "n": 67, "enunciado": "Señale la afirmación correcta. De acuerdo con el artículo 53 de la Constitución sólo podrá regularse por ley el ejercicio de los derechos y libertades reconocidos en:", "opciones": ["La Sección primera del Capítulo segundo del Título I.", "El Capítulo segundo del Título I.", "El Capítulo III del Título I.", "El Título I."], "bloque": "t1-garantias", "precepto": "Artículo 53.1 CE", "correcta": 1, "justificaciones": ["No. La Sección 1.ª es el ámbito del 53.2, no del 53.1.", "Es esta. El 53.1 se refiere al «Capítulo segundo del presente Título» entero, es decir, los artículos 14 a 38.", "No. El Capítulo III es el ámbito del 53.3.", "No. El Título I completo incluiría el Capítulo I (11 a 13) y el Capítulo V (55), que quedan fuera del 53.1."], "arts": [53], "citas": [{"texto": "«Los derechos y libertades reconocidos en el Capítulo segundo del presente Título vinculan a todos los poderes públicos. Sólo por ley, que en todo caso deberá respetar su contenido esencial, podrá regularse el ejercicio de tales derechos y libertades, que se tutelarán de acuerdo con lo previsto en el artículo 161, 1, a).»", "fuente": "Artículo 53.1 CE"}], "marca": {"nivel": "estrella", "nota": "Las garantías del artículo 53 (quién vincula, reserva de ley, amparo) están en todas las listas de lo más preguntado."}, "ojo": "Dos ámbitos distintos en el mismo artículo: el 53.1 alcanza a todo el Capítulo II; el 53.2 (amparo y procedimiento preferente y sumario) solo a la Sección 1.ª, más el artículo 14 y el 30.2.", "truco": "53.1 = CAPÍTULO entero. 53.2 = SECCIÓN primera. Cuanto más fuerte es la garantía, más pequeño es el grupo protegido."}, {"id": "ce-031", "origen": "otras", "test": "Test exámenes", "n": 69, "enunciado": "Señale la afirmación correcta en relación con el procedimiento de \"habeas corpus\" previsto en el artículo 17.4 de la Constitución:", "opciones": ["Produce la inmediata puesta a disposición judicial de toda persona detenida ilegalmente.", "Impide que la detención de las personas se prolongue más de 72 horas.", "Garantiza al detenido la asistencia de abogado en las diligencias policiales.", "Permite que la persona detenida no sea obligada a declarar."], "bloque": "t1-derechos", "precepto": "Artículo 17.4 CE", "correcta": 0, "justificaciones": ["Es esta. Literal del 17.4: el habeas corpus sirve para poner de inmediato a disposición judicial a quien está detenido ilegalmente.", "No. El plazo máximo de setenta y dos horas es el artículo 17.2, no el 17.4.", "No. La asistencia de abogado en las diligencias policiales y judiciales es el artículo 17.3.", "No. El derecho a no ser obligado a declarar es también el artículo 17.3."], "arts": [17], "citas": [{"texto": "«La ley regulará un procedimiento de «habeas corpus» para producir la inmediata puesta a disposición judicial de toda persona detenida ilegalmente. Asimismo, por ley se determinará el plazo máximo de duración de la prisión provisional.»", "fuente": "Artículo 17.4 CE"}], "marca": {"nivel": "clave", "nota": "De la Sección 1.ª, los artículos que más repiten las listas: libertad religiosa, detención, intimidad, expresión, participación, tutela judicial y educación."}, "truco": "El artículo 17 en cuatro apartados: 17.1 libertad y seguridad · 17.2 las 72 horas · 17.3 derechos del detenido · 17.4 habeas corpus y prisión provisional."}, {"id": "ce-032", "origen": "otras", "test": "Test exámenes", "n": 75, "enunciado": "El procedimiento preferente y sumario ante los Tribunales ordinarios podrá recabarse para la protección del siguiente derecho:", "opciones": ["Derecho a contraer matrimonio.", "Derecho de petición.", "Derecho a la negociación colectiva laboral.", "Derecho a la propiedad privada y a la herencia."], "bloque": "t1-garantias", "precepto": "Artículo 53.2 CE", "correcta": 1, "justificaciones": ["No. El derecho a contraer matrimonio es el artículo 32, Sección 2.ª.", "Es esta. El derecho de petición es el artículo 29, el último de la Sección 1.ª: le alcanza el procedimiento preferente y sumario.", "No. La negociación colectiva laboral es el artículo 37.1, Sección 2.ª.", "No. La propiedad privada y la herencia son el artículo 33, Sección 2.ª."], "arts": [53], "citas": [{"texto": "«Cualquier ciudadano podrá recabar la tutela de las libertades y derechos reconocidos en el artículo 14 y la Sección primera del Capítulo segundo ante los Tribunales ordinarios por un procedimiento basado en los principios de preferencia y sumariedad y, en su caso, a través del recurso de amparo ante el Tribunal Constitucional. Este último recurso será aplicable a la objeción de conciencia reconocida en el artículo 30.»", "fuente": "Artículo 53.2 CE"}], "marca": {"nivel": "estrella", "nota": "Las garantías del artículo 53 (quién vincula, reserva de ley, amparo) están en todas las listas de lo más preguntado."}}, {"id": "ce-033", "origen": "otras", "test": "Test exámenes", "n": 79, "enunciado": "El derecho a la negociación colectiva laboral:", "opciones": ["No aparece recogido entre los derechos y deberes del Título I de la Constitución.", "Viene regulado en la Sección 2ª del Capítulo 2º del Título I de la Constitución, así como la fuerza vinculante de los convenios.", "Aparece regulado en el Título VII de la Constitución, \"Economía y Hacienda\".", "Su tutela es susceptible de recurso de amparo ante el Tribunal Constitucional."], "bloque": "t1-derechos", "precepto": "Artículo 37.1 CE", "correcta": 1, "justificaciones": ["No. Sí aparece en el Título I: es el artículo 37, dentro del Capítulo II.", "Es esta. El artículo 37.1 está en la Sección 2.ª del Capítulo II del Título I y menciona expresamente la fuerza vinculante de los convenios, tal como dice la opción.", "No. El Título VII, «Economía y Hacienda», son los artículos 128 a 136: nada que ver.", "No. Al estar en la Sección 2.ª queda fuera del artículo 53.2: no tiene recurso de amparo."], "arts": [37], "citas": [{"texto": "«La ley garantizará el derecho a la negociación colectiva laboral entre los representantes de los trabajadores y empresarios, así como la fuerza vinculante de los convenios.»", "fuente": "Artículo 37.1 CE"}]}, {"id": "ce-034", "origen": "otras", "test": "Test exámenes", "n": 80, "enunciado": "Según la regulación constitucional del derecho de asociación:", "opciones": ["Las asociaciones que se constituyan deben inscribirse en un registro a los efectos de publicidad.", "Las asociaciones pueden ser suspendidas en virtud de resolución administrativa motivada.", "Este derecho aparece regulado en el Título Preliminar de la Constitución.", "Este derecho aparece regulado en la Sección 2ª del Capítulo 2º del Título I de la Constitución."], "bloque": "t1-derechos", "precepto": "Artículo 22.3 y 22.4 CE", "correcta": 0, "justificaciones": ["Es esta. Literal del 22.3: el registro es «a los solos efectos de publicidad», no de autorización ni de control previo.", "No. El 22.4 exige resolución JUDICIAL motivada. La Administración no puede suspender una asociación.", "No. El derecho de asociación es el artículo 22, en el Título I. El Título Preliminar acaba en el artículo 9.", "No. Está en la Sección 1.ª del Capítulo II, no en la 2.ª: precisamente por eso tiene amparo."], "arts": [22], "citas": [{"texto": "«3. Las asociaciones constituidas al amparo de este artículo deberán inscribirse en un registro a los solos efectos de publicidad.»«4. Las asociaciones sólo podrán ser disueltas o suspendidas en sus actividades en virtud de resolución judicial motivada.»", "fuente": "Artículo 22.3 y 22.4 CE"}], "truco": "En el artículo 22 todo lo que perjudica a una asociación (declararla ilegal, disolverla, suspenderla) es judicial. La Administración solo la inscribe, y «a los solos efectos de publicidad»."}, {"id": "ce-035", "origen": "otras", "test": "Test exámenes", "n": 83, "enunciado": "Señale cuál de las siguientes afirmaciones es correcta:", "opciones": ["El artículo 27 de la Constitución Española reconoce el derecho a la educación, la libertad de creación de centros docentes, la autonomía universitaria, y prevé la creación del Consejo Escolar del Estado.", "El artículo 27 de la Constitución Española reconoce el derecho a la educación, la libertad de creación de centros docentes, la autonomía universitaria, y prevé que los poderes públicos inspeccionarán y homologarán el sistema educativo para garantizar el cumplimiento de las leyes.", "El artículo 27 de la Constitución Española reconoce el derecho a la educación, la libertad de creación de centros docentes y la gratuidad de la enseñanza superior.", "El artículo 27 de la Constitución Española reconoce el derecho a la educación, a la autonomía universitaria y al derecho de petición individual y colectiva."], "bloque": "t1-derechos", "precepto": "Artículo 27.8 CE", "correcta": 1, "justificaciones": ["No. El Consejo Escolar del Estado no está en la Constitución: es creación de la legislación ordinaria.", "Es esta. Las tres primeras piezas de la opción están en el artículo 27 (educación 27.1, creación de centros 27.6, autonomía universitaria 27.10) y la cuarta es literalmente el 27.8.", "No. El 27.4 reserva la gratuidad a la enseñanza básica, no a la superior.", "No. El derecho de petición individual y colectiva es el artículo 29, no el 27."], "arts": [27], "citas": [{"texto": "«Los poderes públicos inspeccionarán y homologarán el sistema educativo para garantizar el cumplimiento de las leyes.»", "fuente": "Artículo 27.8 CE"}], "marca": {"nivel": "clave", "nota": "De la Sección 1.ª, los artículos que más repiten las listas: libertad religiosa, detención, intimidad, expresión, participación, tutela judicial y educación."}, "truco": "El artículo 27 tiene diez apartados, el que más de todo el Título I. Los tres que más caen: 27.4 enseñanza básica obligatoria y gratuita · 27.6 libertad de creación de centros · 27.10 autonomía universitaria."}, {"id": "ce-036", "origen": "otras", "test": "Test exámenes", "n": 103, "enunciado": "El artículo 34 de la CE reconoce el derecho de fundación para fines de:", "opciones": ["Interés público.", "Utilidad pública.", "Interés general, con arreglo a la ley.", "Obligado cumplimiento."], "bloque": "t1-derechos", "precepto": "Artículo 34.1 CE", "correcta": 2, "justificaciones": ["No. «Interés público» no es la expresión que usa el 34.1.", "No. «Utilidad pública» es del artículo 33.3, la causa que permite privar de bienes mediante expropiación.", "Es esta. Literal: «interés general, con arreglo a la ley».", "No. «Obligado cumplimiento» no aparece en el precepto."], "arts": [34], "citas": [{"texto": "«Se reconoce el derecho de fundación para fines de interés general, con arreglo a la ley.»", "fuente": "Artículo 34.1 CE"}], "truco": "Tres expresiones parecidas en artículos vecinos: interés GENERAL (34.1, fundación) · utilidad pública o interés social (33.3, expropiación) · función social (33.2, propiedad)."}, {"id": "ce-037", "origen": "otras", "test": "Test exámenes", "n": 110, "enunciado": "Según el art. 53 de la Constitución Española, con respecto a los derechos reconocidos en el artículo 30 de la misma:", "opciones": ["Cualquier ciudadano podrá recabar la tutela de esos derechos ante los Tribunales ordinarios por un procedimiento basado en los principios de preferencia y sumariedad.", "Informarán la legislación positiva, la práctica judicial y la actuación de los poderes públicos.", "Cualquier ciudadano podrá recabar la tutela de esos derechos, en su caso, a través del recurso de amparo ante el Tribunal Constitucional.", "Vinculan a todos los poderes públicos. Sólo por ley, que en todo caso deberá respetar su contenido esencial, podrá regularse el ejercicio de tales derechos."], "bloque": "t1-garantias", "precepto": "Artículo 53.1 CE; Artículo 53.2 CE", "correcta": 3, "justificaciones": ["No. La tutela preferente y sumaria del 53.2 cubre el artículo 14 y la Sección 1.ª, no el artículo 30 entero.", "No. «Informarán la legislación positiva» es el 53.3, que se aplica al Capítulo III.", "No. El amparo solo alcanza al artículo 30 en su apartado 2 (objeción de conciencia), no al artículo completo.", "Es esta. El artículo 30 abre la Sección 2.ª del Capítulo II, así que como artículo le alcanza el 53.1: vincula a todos los poderes públicos y solo por ley, respetando su contenido esencial, cabe regular su ejercicio."], "arts": [53], "citas": [{"texto": "«Los derechos y libertades reconocidos en el Capítulo segundo del presente Título vinculan a todos los poderes públicos. Sólo por ley, que en todo caso deberá respetar su contenido esencial, podrá regularse el ejercicio de tales derechos y libertades, que se tutelarán de acuerdo con lo previsto en el artículo 161, 1, a).»", "fuente": "Artículo 53.1 CE"}, {"texto": "«Cualquier ciudadano podrá recabar la tutela de las libertades y derechos reconocidos en el artículo 14 y la Sección primera del Capítulo segundo ante los Tribunales ordinarios por un procedimiento basado en los principios de preferencia y sumariedad y, en su caso, a través del recurso de amparo ante el Tribunal Constitucional. Este último recurso será aplicable a la objeción de conciencia reconocida en el artículo 30.»", "fuente": "Artículo 53.2 CE"}], "marca": {"nivel": "estrella", "nota": "Las garantías del artículo 53 (quién vincula, reserva de ley, amparo) están en todas las listas de lo más preguntado."}, "ojo": "Matiz: el 53.2 menciona expresamente la objeción de conciencia del artículo 30, que por eso sí tiene amparo y procedimiento preferente y sumario. Pero eso es solo el apartado 2; la afirmación que vale para todo el artículo 30 es la del 53.1.", "truco": "El artículo 30 es un caso mixto: como artículo va por el 53.1, pero su apartado 2 (objeción de conciencia) está expresamente invitado al amparo por el 53.2. Fíjate si la pregunta habla del artículo o del apartado."}, {"id": "ce-038", "origen": "otras", "test": "Test exámenes", "n": 111, "enunciado": "Según la Constitución Española, ¿tienen los extranjeros derecho a participar en los asuntos públicos, directamente o por medio de representantes?:", "opciones": ["Sí, porque el artículo 23.1 hace referencia a los “ciudadanos”, sin distinguir españoles o extranjeros.", "No, porque el artículo 13.2 enuncia que solamente los españoles serán titulares de los derechos reconocidos en el artículo 23.", "Sí, porque el artículo 13.1 declara que los extranjeros gozarán en España de las libertades públicas que garantiza el Titulo I en los términos que establezcan los tratados y la ley.", "Solo en lo que, atendiendo a criterios de reciprocidad, pueda establecerse por tratado o ley para el derecho de sufragio activo y pasivo en las elecciones municipales."], "bloque": "t1-derechos", "precepto": "Artículo 13.1 CE; Artículo 13.2 CE", "correcta": 3, "justificaciones": ["No. El 23.1 habla de «ciudadanos», pero el 13.2 lo restringe expresamente a los españoles.", "No. Es cierta a medias: acierta la regla y se olvida de la excepción municipal, que es exactamente lo que se pregunta.", "No. El 13.1 remite a «las libertades públicas» del Título I, pero el 13.2 saca al artículo 23 de ese régimen general.", "Es esta. El 13.2 es regla y excepción a la vez: solo los españoles, salvo el sufragio municipal por tratado o ley con reciprocidad. Esta opción enuncia justamente esa única puerta abierta, que es lo que pregunta el enunciado."], "arts": [13], "citas": [{"texto": "«Los extranjeros gozarán en España de las libertades públicas que garantiza el presente Título en los términos que establezcan los tratados y la ley.»", "fuente": "Artículo 13.1 CE"}, {"texto": "«Solamente los españoles serán titulares de los derechos reconocidos en el artículo 23, salvo lo que, atendiendo a criterios de reciprocidad, pueda establecerse por tratado o ley para el derecho de sufragio activo y pasivo en las elecciones municipales.»", "fuente": "Artículo 13.2 CE"}], "marca": {"nivel": "clave", "nota": "Extranjeros (art. 13): el 13.2 y el voto municipal caen a menudo, también en el INAP."}, "ojo": "La opción que dice «no, porque el 13.2…» parece la respuesta hasta que ves que se olvida de la excepción municipal. La correcta es la que enuncia toda la regla.", "truco": "El 13.1 es la regla general para extranjeros; el 13.2 cierra el artículo 23 y luego abre una rendija municipal. Cuando la pregunta menciona el artículo 23, la respuesta vive en el 13.2."}, {"id": "ce-039", "origen": "otras", "test": "Test exámenes", "n": 112, "enunciado": "¿De cuál de las siguientes libertades y derechos reconocidos en la Constitución Española cualquier ciudadano podrá recabar su tutela ante los Tribunales ordinarios por un procedimiento basado en los principios de preferencia y sumariedad?:", "opciones": ["Objeción de conciencia.", "Libertad sindical.", "Derecho a la propiedad privada.", "Todas las respuestas anteriores son correctas."], "bloque": "t1-garantias", "precepto": "Artículo 53.2 CE", "correcta": 1, "justificaciones": ["No. También sería correcta: el 53.2 menciona expresamente la objeción de conciencia del artículo 30. Ahí está el defecto de la pregunta.", "Es esta. La libertad sindical es el artículo 28.1, dentro de la Sección 1.ª: indiscutiblemente cubierta por el 53.2.", "No. La propiedad privada es el artículo 33, Sección 2.ª: queda fuera.", "No. No puede ser «todas» precisamente porque la propiedad privada queda fuera."], "arts": [53], "citas": [{"texto": "«Cualquier ciudadano podrá recabar la tutela de las libertades y derechos reconocidos en el artículo 14 y la Sección primera del Capítulo segundo ante los Tribunales ordinarios por un procedimiento basado en los principios de preferencia y sumariedad y, en su caso, a través del recurso de amparo ante el Tribunal Constitucional. Este último recurso será aplicable a la objeción de conciencia reconocida en el artículo 30.»", "fuente": "Artículo 53.2 CE"}], "marca": {"nivel": "estrella", "nota": "Las garantías del artículo 53 (quién vincula, reserva de ley, amparo) están en todas las listas de lo más preguntado."}, "ojo": "La objeción de conciencia del artículo 30.2 también está mencionada expresamente en el 53.2, así que esa opción sería igualmente defendible. La plantilla da la libertad sindical, que es indiscutible; en un examen oficial la pregunta sería impugnable."}, {"id": "ce-040", "origen": "otras", "test": "Examen", "n": 2, "enunciado": "¿En qué artículo de la Constitución Española de 1978 se recoge el derecho de los españoles a elegir libremente su residencia y a circular libremente por el territorio nacional?", "opciones": ["En el artículo 19.", "En el artículo 20.", "En el artículo 17.", "En el artículo 18."], "bloque": "t1-derechos", "precepto": "Artículo 19 CE", "correcta": 0, "justificaciones": ["Es esta. Es el artículo 19, literal.", "No. El artículo 20 es la libertad de expresión y de información.", "No. El artículo 17 es la libertad y la seguridad personal: detención, 72 horas, habeas corpus.", "No. El artículo 18 es el honor, la intimidad, la propia imagen, el domicilio y el secreto de las comunicaciones."], "arts": [19], "citas": [{"texto": "«Los españoles tienen derecho a elegir libremente su residencia y a circular por el territorio nacional. Asimismo, tienen derecho a entrar y salir libremente de España en los términos que la ley establezca. Este derecho no podrá ser limitado por motivos políticos o ideológicos.»", "fuente": "Artículo 19 CE"}], "truco": "El bloque 17-18-19-20, en orden: 17 tu cuerpo (libertad), 18 tu casa y tu vida privada, 19 tus pies (circular), 20 tu boca (expresión)."}, {"id": "ce-041", "origen": "otras", "test": "Examen", "n": 14, "enunciado": "Según la Constitución Española de 1978, es un derecho fundamental:", "opciones": ["El derecho a la negociación colectiva laboral.", "El derecho a comunicar o recibir libremente información veraz por cualquier medio de difusión.", "El derecho a contraer matrimonio con plena igualdad jurídica.", "El derecho a disfrutar de un medio ambiente adecuado para el desarrollo de la persona."], "bloque": "t1-derechos", "precepto": "Artículo 20.1.d) CE", "correcta": 1, "justificaciones": ["No. La negociación colectiva laboral es el artículo 37.1, Sección 2.ª.", "Es esta. Es el artículo 20.1.d), en la Sección 1.ª del Capítulo II: derecho fundamental.", "No. El matrimonio es el artículo 32, Sección 2.ª.", "No. El medio ambiente adecuado es el artículo 45, Capítulo III."], "arts": [20], "citas": [{"texto": "«Se reconocen y protegen los derechos: […] d) A comunicar o recibir libremente información veraz por cualquier medio de difusión. […]»", "fuente": "Artículo 20.1.d) CE"}], "marca": {"nivel": "clave", "nota": "De la Sección 1.ª, los artículos que más repiten las listas: libertad religiosa, detención, intimidad, expresión, participación, tutela judicial y educación."}}, {"id": "ce-042", "origen": "otras", "test": "Examen", "n": 15, "enunciado": "Según la Constitución Española de 1978, es un derecho fundamental:", "opciones": ["El derecho a la propiedad privada.", "El derecho a disfrutar de una vivienda digna y adecuada.", "El derecho de petición.", "El derecho a la negociación colectiva laboral."], "bloque": "t1-derechos", "precepto": "Artículo 29.1 CE", "correcta": 2, "justificaciones": ["No. La propiedad privada es el artículo 33, Sección 2.ª.", "No. La vivienda digna y adecuada es el artículo 47, Capítulo III.", "Es esta. El derecho de petición es el artículo 29, el último de la Sección 1.ª del Capítulo II.", "No. La negociación colectiva laboral es el artículo 37, Sección 2.ª."], "arts": [29], "citas": [{"texto": "«Todos los españoles tendrán el derecho de petición individual y colectiva, por escrito, en la forma y con los efectos que determine la ley.»", "fuente": "Artículo 29.1 CE"}]}, {"id": "ce-043", "origen": "otras", "test": "Examen", "n": 17, "enunciado": "Según el artículo 53 de la Constitución Española de 1978, el reconocimiento, el respeto y la protección del derecho a disfrutar de una vivienda digna y adecuada:", "opciones": ["Podrá ser objeto de recurso de amparo ante el Tribunal Constitucional.", "Queda fuera del ámbito de protección del Defensor del Pueblo.", "Solo podrán ser alegados ante la Jurisdicción ordinaria.", "Solo puede desarrollarse legalmente mediante ley orgánica."], "bloque": "t1-garantias", "precepto": "Artículo 53.3 CE", "correcta": 2, "justificaciones": ["No. El amparo es del 53.2 y no alcanza al Capítulo III.", "No. Falso: el Defensor del Pueblo defiende los derechos de todo el Título I (artículo 54), Capítulo III incluido.", "Es esta. La vivienda digna es el artículo 47, Capítulo III: sus principios solo pueden alegarse ante la jurisdicción ordinaria de acuerdo con las leyes que los desarrollen.", "No. El 53.3 no exige ley orgánica: habla de «las leyes que los desarrollen», sin más."], "arts": [53], "citas": [{"texto": "«El reconocimiento, el respeto y la protección de los principios reconocidos en el Capítulo tercero informarán la legislación positiva, la práctica judicial y la actuación de los poderes públicos. Sólo podrán ser alegados ante la Jurisdicción ordinaria de acuerdo con lo que dispongan las leyes que los desarrollen.»", "fuente": "Artículo 53.3 CE"}], "marca": {"nivel": "estrella", "nota": "Las garantías del artículo 53 (quién vincula, reserva de ley, amparo) están en todas las listas de lo más preguntado."}, "truco": "El Defensor del Pueblo cubre TODO el Título I, principios rectores incluidos. No confundas su ámbito con el del amparo, que es mucho más estrecho."}, {"id": "ce-167", "origen": "oficiales", "test": "INAP julio 2026 (extraordinario)", "n": 29, "enunciado": "El ejercicio del derecho de reunión segun el artículo 21 de la Constitución Española de 1978:", "opciones": ["Necesita autorización administrativa previa.", "Necesita autorización judicial previa.", "No nesesita autorización.", "Necesita autorización previa de la alcaldia correspondiente."], "bloque": "t1-derechos", "precepto": "Artículo 21.1 CE", "correcta": 2, "justificaciones": ["No. La autorización administrativa previa es justo lo que el 21.1 descarta.", "No. Tampoco hace falta autorización judicial.", "Es esta. Ninguna autorización. El 21.1 lo dice con todas las letras.", "No. En reuniones en lugares de tránsito público y manifestaciones hay **comunicación** previa a la autoridad (21.2), que no es lo mismo que pedirle permiso al alcalde."], "arts": [21], "citas": [{"texto": "«Se reconoce el derecho de reunión pacífica y sin armas. El ejercicio de este derecho no necesitará autorización previa.»", "fuente": "Artículo 21.1 CE"}], "truco": "Comunicar no es pedir permiso. Y la autoridad solo puede prohibir la reunión cuando haya razones fundadas de alteración del orden público con peligro para personas o bienes."}, {"id": "ce-176", "origen": "oficiales", "test": "INAP 2025 (extraordinario)", "n": 1, "enunciado": "De acuerdo con el artículo 17 de la Constitución Española de 1978, ¿cuál sería el plazo máximo de duración de la prisión provisional?", "opciones": ["72 horas.", "1 año.", "Se determinará por Ley.", "Se determinará por Reglamento."], "bloque": "t1-derechos", "precepto": "Artículo 17.4 CE", "correcta": 2, "justificaciones": ["No. Las setenta y dos horas son el máximo de la **detención preventiva** (17.2), no de la prisión provisional.", "No. Un año no aparece en la Constitución.", "Es esta. La Constitución no pone cifra: remite a la ley.", "No. Hay reserva de ley: un reglamento no puede fijar ese plazo."], "arts": [17], "citas": [{"texto": "«La ley regulará un procedimiento de «habeas corpus» para producir la inmediata puesta a disposición judicial de toda persona detenida ilegalmente. Asimismo, por ley se determinará el plazo máximo de duración de la prisión provisional.»", "fuente": "Artículo 17.4 CE"}], "marca": {"nivel": "clave", "nota": "De la Sección 1.ª, los artículos que más repiten las listas: libertad religiosa, detención, intimidad, expresión, participación, tutela judicial y educación."}, "truco": "El artículo 17 tiene dos plazos y solo uno lleva número: detención preventiva, 72 horas; prisión provisional, «por ley». Si la opción da una cifra para la prisión provisional, es falsa."}, {"id": "ce-044", "origen": "otras", "test": "Test exámenes", "n": 4, "enunciado": "La declaración del estado de excepción corresponde:", "opciones": ["Al Congreso de los Diputados, a propuesta exclusiva del Gobierno.", "A las Cortes Generales.", "Al Gobierno, dando cuenta al Congreso de los Diputados.", "Al Gobierno, previa autorización del Congreso de los Diputados."], "bloque": "t1-suspension", "precepto": "Artículo 116.3 CE", "correcta": 3, "justificaciones": ["No. Eso es el estado de sitio: lo declara el propio Congreso por mayoría absoluta, a propuesta exclusiva del Gobierno (116.4).", "No. El Senado no interviene en ninguno de los tres estados: siempre es el Congreso, nunca las Cortes Generales en pleno.", "No. «Dando cuenta al Congreso» es el estado de alarma (116.2), donde la autorización solo hace falta para prorrogar.", "Es esta. El estado de excepción lo declara el Gobierno por decreto acordado en Consejo de Ministros, pero necesita autorización PREVIA del Congreso de los Diputados."], "arts": [116], "citas": [{"texto": "«El estado de excepción será declarado por el Gobierno mediante decreto acordado en Consejo de Ministros, previa autorización del Congreso de los Diputados. La autorización y proclamación del estado de excepción deberá determinar expresamente los efectos del mismo, el ámbito territorial a que se extiende y su duración, que no podrá exceder de treinta días, prorrogables por otro plazo igual, con los mismos requisitos.»", "fuente": "Artículo 116.3 CE"}], "marca": {"nivel": "estrella", "nota": "Estados de alarma, excepción y sitio: quién los declara, cuánto duran y qué derechos se suspenden. Cae en el INAP y en todas las listas."}, "ojo": "«Dando cuenta» es la alarma; «previa autorización» es la excepción; el sitio lo declara el propio Congreso.", "truco": "Los tres verbos, en orden creciente de gravedad: alarma → el Gobierno DA CUENTA · excepción → el Gobierno pide AUTORIZACIÓN PREVIA · sitio → lo DECLARA el Congreso."}, {"id": "ce-045", "origen": "oficiales", "test": "INAP feb 2022", "n": 2, "enunciado": "¿Cuál de los siguientes derechos puede ser suspendido en caso de que se acuerde la declaración del estado de excepción o de sitio?:", "opciones": ["El derecho de huelga.", "El derecho de petición individual y colectiva.", "El derecho a obtener la tutela efectiva de Jueces y Tribunales.", "El derecho de creación de centros docentes."], "bloque": "t1-suspension", "precepto": "Artículo 55.1 CE", "correcta": 0, "justificaciones": ["Es esta. El derecho de huelga es el artículo 28.2 y aparece expresamente en la lista del 55.1.", "No. El derecho de petición es el artículo 29 y no figura en la lista.", "No. La tutela judicial efectiva es el artículo 24: no está en la lista, no se suspende nunca.", "No. La libertad de creación de centros docentes es el artículo 27.6: tampoco está en la lista."], "arts": [55], "citas": [{"texto": "«Los derechos reconocidos en los artículos 17, 18, apartados 2 y 3, artículos 19, 20, apartados 1, a) y d), y 5, artículos 21, 28, apartado 2, y artículo 37, apartado 2, podrán ser suspendidos cuando se acuerde la declaración del estado de excepción o de sitio en los términos previstos en la Constitución. Se exceptúa de lo establecido anteriormente el apartado 3 del artículo 17 para el supuesto de declaración de estado de excepción.»", "fuente": "Artículo 55.1 CE"}], "marca": {"nivel": "estrella", "nota": "Estados de alarma, excepción y sitio: quién los declara, cuánto duran y qué derechos se suspenden. Cae en el INAP y en todas las listas."}, "truco": "La lista del 55.1 son siete referencias y conviene sabérsela de memoria: 17 · 18.2 y 18.3 · 19 · 20.1.a) y d) y 20.5 · 21 · 28.2 · 37.2. Lo que no esté ahí no se suspende jamás."}, {"id": "ce-046", "origen": "otras", "test": "Test exámenes", "n": 28, "enunciado": "Según establece el artículo 116.3 de la Constitución Española, el Gobierno, previa autorización del Congreso de los Diputados, podrá proclamar el estado de excepción por un plazo que no podrá exceder:", "opciones": ["De 15 días.", "De 15 días, prorrogables por otro plazo igual.", "De 30 días, prorrogables por otro plazo igual.", "De 10 días, prorrogables por otro plazo igual."], "bloque": "t1-suspension", "precepto": "Artículo 116.3 CE", "correcta": 2, "justificaciones": ["No. Quince días es el plazo del estado de alarma (116.2).", "No. Mezcla el plazo de la alarma (quince días) con la prórroga de la excepción.", "Es esta. Treinta días, prorrogables por otro plazo igual y con los mismos requisitos.", "No. Diez días no aparece en ningún apartado del artículo 116."], "arts": [116], "citas": [{"texto": "«El estado de excepción será declarado por el Gobierno mediante decreto acordado en Consejo de Ministros, previa autorización del Congreso de los Diputados. La autorización y proclamación del estado de excepción deberá determinar expresamente los efectos del mismo, el ámbito territorial a que se extiende y su duración, que no podrá exceder de treinta días, prorrogables por otro plazo igual, con los mismos requisitos.»", "fuente": "Artículo 116.3 CE"}], "marca": {"nivel": "estrella", "nota": "Estados de alarma, excepción y sitio: quién los declara, cuánto duran y qué derechos se suspenden. Cae en el INAP y en todas las listas."}, "truco": "Alarma 15 + 15. Excepción 30 + 30. Sitio, sin plazo en la Constitución: lo fija el Congreso."}, {"id": "ce-047", "origen": "otras", "test": "Test exámenes", "n": 41, "enunciado": "De conformidad con el artículo 116 de la CE, el estado de sitio será declarado por:", "opciones": ["El Presidente del Gobierno mediante Real Decreto, dando cuenta a las Cortes Generales.", "El Gobierno mediante Real Decreto de Consejo de Ministros, previa autorización de las Cortes Generales.", "El Gobierno mediante Real Decreto de Consejo de Ministros, previa autorización del Congreso de los Diputados.", "La mayoría absoluta del Congreso de los Diputados, a propuesta exclusiva del Gobierno."], "bloque": "t1-suspension", "precepto": "Artículo 116.4 CE", "correcta": 3, "justificaciones": ["No. El Presidente del Gobierno no declara ningún estado excepcional, y aquí ni siquiera interviene el Gobierno como órgano colegiado.", "No. Cambia el Congreso por las Cortes Generales: el Senado no participa.", "No. Describe el estado de excepción del 116.3, no el de sitio.", "Es esta. Literal del 116.4: mayoría absoluta del Congreso, a propuesta exclusiva del Gobierno."], "arts": [116], "citas": [{"texto": "«El estado de sitio será declarado por la mayoría absoluta del Congreso de los Diputados, a propuesta exclusiva del Gobierno. El Congreso determinará su ámbito territorial, duración y condiciones.»", "fuente": "Artículo 116.4 CE"}], "marca": {"nivel": "estrella", "nota": "Estados de alarma, excepción y sitio: quién los declara, cuánto duran y qué derechos se suspenden. Cae en el INAP y en todas las listas."}, "ojo": "Es el único de los tres que declara el Congreso. Alarma: Gobierno dando cuenta. Excepción: Gobierno con autorización previa. Sitio: el Congreso."}, {"id": "ce-048", "origen": "otras", "test": "Test exámenes", "n": 58, "enunciado": "De conformidad con el artículo 116 de la Constitución Española, el estado de alarma será declarado:", "opciones": ["Por mayoría absoluta del Congreso por un plazo máximo de 15 días, sin perjuicio de su posible prórroga.", "Por el Gobierno, mediante decreto acordado en Consejo de Ministros y por un plazo máximo de 15 días, dando cuenta al Congreso de los Diputados y sin cuya autorización no podrá ser prorrogado dicho plazo.", "Por mayoría simple del Congreso por un plazo máximo de 15 días, sin perjuicio de su posible prórroga.", "Por mayoría simple del Congreso y ratificado por el Senado por el periodo que se determine."], "bloque": "t1-suspension", "precepto": "Artículo 116.2 CE", "correcta": 1, "justificaciones": ["No. La mayoría absoluta del Congreso es el estado de sitio (116.4), no la alarma.", "Es esta. Reproduce el 116.2: Gobierno, decreto en Consejo de Ministros, quince días como máximo, dando cuenta al Congreso, sin cuya autorización no puede prorrogarse.", "No. La mayoría simple del Congreso no aparece en el artículo 116.", "No. El Senado no interviene en ninguno de los tres estados, y menos ratificando."], "arts": [116], "citas": [{"texto": "«El estado de alarma será declarado por el Gobierno mediante decreto acordado en Consejo de Ministros por un plazo máximo de quince días, dando cuenta al Congreso de los Diputados, reunido inmediatamente al efecto y sin cuya autorización no podrá ser prorrogado dicho plazo. El decreto determinará el ámbito territorial a que se extienden los efectos de la declaración.»", "fuente": "Artículo 116.2 CE"}], "marca": {"nivel": "estrella", "nota": "Estados de alarma, excepción y sitio: quién los declara, cuánto duran y qué derechos se suspenden. Cae en el INAP y en todas las listas."}, "truco": "En la alarma el Congreso NO autoriza la declaración: solo la PRÓRROGA. Esa es la diferencia exacta con la excepción, donde la autorización es previa."}, {"id": "ce-049", "origen": "otras", "test": "Test exámenes", "n": 73, "enunciado": "De acuerdo con la Constitución se exige que la declaración del estado de sitio se produzca:", "opciones": ["Por mayoría absoluta del Congreso por un plazo máximo de 30 días.", "Por mayoría absoluta del Congreso a propuesta exclusiva del Gobierno.", "Por el Gobierno mediante Decreto aprobado en Consejo de Ministros previa autorización del Congreso de los Diputados.", "Por el Gobierno mediante Decreto aprobado en Consejo de Ministros por un plazo máximo de 15 días."], "bloque": "t1-suspension", "precepto": "Artículo 116.4 CE", "correcta": 1, "justificaciones": ["No. Acierta la mayoría, pero le pone un plazo máximo de treinta días que la Constitución no establece: los treinta días son de la excepción.", "Es esta. Mayoría absoluta del Congreso, a propuesta exclusiva del Gobierno. Y la Constitución no le fija plazo: es el Congreso quien determina ámbito, duración y condiciones.", "No. Describe el estado de excepción (116.3).", "No. Describe el estado de alarma (116.2)."], "arts": [116], "citas": [{"texto": "«El estado de sitio será declarado por la mayoría absoluta del Congreso de los Diputados, a propuesta exclusiva del Gobierno. El Congreso determinará su ámbito territorial, duración y condiciones.»", "fuente": "Artículo 116.4 CE"}], "marca": {"nivel": "estrella", "nota": "Estados de alarma, excepción y sitio: quién los declara, cuánto duran y qué derechos se suspenden. Cae en el INAP y en todas las listas."}, "truco": "El sitio es el único de los tres SIN plazo máximo en la Constitución. Si una opción le pone días al estado de sitio, es falsa."}, {"id": "ce-050", "origen": "otras", "test": "Test exámenes", "n": 74, "enunciado": "De acuerdo con la Constitución, señale cuál de los siguientes derechos podrá ser objeto de suspensión cuando se declaren los estados de excepción o sitio:", "opciones": ["Derecho a la inviolabilidad del domicilio (art 18.2 CE).", "Derecho a la producción y creación literaria (art 20.1.b CE).", "Derecho de asociación (art 22.1 CE).", "Derecho a la educación (art 27.1 CE)."], "bloque": "t1-suspension", "precepto": "Artículo 55.1 CE", "correcta": 0, "justificaciones": ["Es esta. La inviolabilidad del domicilio es el artículo 18.2, y el 55.1 cita expresamente el artículo 18 «apartados 2 y 3».", "No. La producción y creación literaria es el 20.1.b), y del artículo 20 solo se suspenden el 20.1.a), el 20.1.d) y el 20.5.", "No. El derecho de asociación es el artículo 22: no está en la lista del 55.1.", "No. El derecho a la educación es el artículo 27: tampoco está en la lista."], "arts": [55], "citas": [{"texto": "«Los derechos reconocidos en los artículos 17, 18, apartados 2 y 3, artículos 19, 20, apartados 1, a) y d), y 5, artículos 21, 28, apartado 2, y artículo 37, apartado 2, podrán ser suspendidos cuando se acuerde la declaración del estado de excepción o de sitio en los términos previstos en la Constitución. Se exceptúa de lo establecido anteriormente el apartado 3 del artículo 17 para el supuesto de declaración de estado de excepción.»", "fuente": "Artículo 55.1 CE"}], "marca": {"nivel": "estrella", "nota": "Estados de alarma, excepción y sitio: quién los declara, cuánto duran y qué derechos se suspenden. Cae en el INAP y en todas las listas."}, "truco": "Del artículo 18 solo se suspenden los apartados 2 y 3 (domicilio y comunicaciones). El 18.1 (honor, intimidad, propia imagen) y el 18.4 (informática) no se suspenden nunca."}, {"id": "ce-051", "origen": "otras", "test": "Test exámenes", "n": 85, "enunciado": "Señale la afirmación correcta a la luz de lo establecido en el artículo 55.1 de la Constitución Española, que regula la suspensión de los derechos y libertades:", "opciones": ["Los derechos recogidos en el artículo 17, excepto el apartado 3, de la Constitución podrán ser suspendidos cuando se acuerde la declaración del estado de alarma, de excepción o de sitio en los términos previstos en la Constitución.", "Los derechos recogidos en el artículo 19 de la Constitución podrán ser suspendidos cuando se acuerde la declaración del estado de alarma, de excepción o de sitio en los términos previstos en la Constitución.", "Los derechos recogidos en el artículo 17, excepto el apartado 3, de la Constitución podrán ser suspendidos cuando se acuerde la declaración del estado de excepción o de sitio en los términos previstos en la Constitución.", "Los derechos recogidos en el artículo 16 de la Constitución podrán ser suspendidos cuando se acuerde la declaración del estado de excepción o de sitio en los términos previstos en la Constitución."], "bloque": "t1-suspension", "precepto": "Artículo 55.1 CE", "correcta": 2, "justificaciones": ["No. Mete el estado de alarma en el 55.1, donde no aparece.", "No. Mete la alarma y además da por hecho que el artículo 19 tiene excepciones de apartado, cuando se suspende entero.", "Es esta. Los derechos del artículo 17, salvo su apartado 3, pueden suspenderse cuando se declara el estado de excepción o de sitio. Ni una palabra sobre la alarma.", "No. El artículo 16 (libertad ideológica, religiosa y de culto) no está en la lista del 55.1: no se suspende nunca."], "arts": [55], "citas": [{"texto": "«Los derechos reconocidos en los artículos 17, 18, apartados 2 y 3, artículos 19, 20, apartados 1, a) y d), y 5, artículos 21, 28, apartado 2, y artículo 37, apartado 2, podrán ser suspendidos cuando se acuerde la declaración del estado de excepción o de sitio en los términos previstos en la Constitución. Se exceptúa de lo establecido anteriormente el apartado 3 del artículo 17 para el supuesto de declaración de estado de excepción.»", "fuente": "Artículo 55.1 CE"}], "marca": {"nivel": "estrella", "nota": "Estados de alarma, excepción y sitio: quién los declara, cuánto duran y qué derechos se suspenden. Cae en el INAP y en todas las listas."}, "ojo": "En el estado de alarma no se suspende ningún derecho: se limita su ejercicio. Cualquier opción que meta la alarma en el 55.1 es falsa. Y el artículo 16 (libertad ideológica y religiosa) no se suspende nunca."}, {"id": "ce-052", "origen": "otras", "test": "Test exámenes", "n": 91, "enunciado": "De conformidad con el artículo 55.2 de la Constitución Española, los derechos que pueden ser suspendidos individualmente son:", "opciones": ["El plazo máximo de detención, la libertad de expresión y el secreto de las comunicaciones.", "El plazo máximo de detención, el derecho al honor y el secreto de las comunicaciones.", "El plazo máximo de detención, la libertad de residencia y el secreto de las comunicaciones.", "El plazo máximo de detención, la inviolabilidad del domicilio y el secreto de las comunicaciones."], "bloque": "t1-suspension", "precepto": "Artículo 55.2 CE", "correcta": 3, "justificaciones": ["No. La libertad de expresión es el artículo 20 y no cabe en la suspensión individual del 55.2.", "No. El derecho al honor es el 18.1, que queda fuera del 55.2.", "No. La libertad de residencia es el artículo 19, que no está en el 55.2.", "Es esta. La suspensión individual solo alcanza a tres apartados: el 17.2 (plazo máximo de detención), el 18.2 (domicilio) y el 18.3 (comunicaciones)."], "arts": [55], "citas": [{"texto": "«Una ley orgánica podrá determinar la forma y los casos en los que, de forma individual y con la necesaria intervención judicial y el adecuado control parlamentario, los derechos reconocidos en los artículos 17, apartado 2, y 18, apartados 2 y 3, pueden ser suspendidos para personas determinadas, en relación con las investigaciones correspondientes a la actuación de bandas armadas o elementos terroristas.»", "fuente": "Artículo 55.2 CE"}], "marca": {"nivel": "estrella", "nota": "Estados de alarma, excepción y sitio: quién los declara, cuánto duran y qué derechos se suspenden. Cae en el INAP y en todas las listas."}, "truco": "El 55.2 es una lista cortísima: 17.2 + 18.2 + 18.3. Detención, domicilio y comunicaciones. Y solo para bandas armadas o terrorismo, con intervención judicial y control parlamentario."}, {"id": "ce-053", "origen": "otras", "test": "Examen", "n": 5, "enunciado": "Conforme al artículo 55 de la Constitución Española de 1978, ¿qué derecho de los siguientes podrá ser suspendido cuando se declare el estado de excepción?", "opciones": ["La asistencia de abogado al detenido en las diligencias policiales y judiciales.", "El derecho a la intimidad personal.", "El derecho a la huelga de los trabajadores.", "El derecho de asociación."], "bloque": "t1-suspension", "precepto": "Artículo 55.1 CE", "correcta": 2, "justificaciones": ["No. La asistencia de abogado al detenido es el 17.3, que el 55.1 excepciona expresamente para el estado de excepción.", "No. La intimidad personal es el 18.1: fuera de la lista.", "Es esta. La huelga es el artículo 28.2 y está en la lista del 55.1: se suspende tanto en excepción como en sitio.", "No. El derecho de asociación es el artículo 22: fuera de la lista."], "arts": [55], "citas": [{"texto": "«Los derechos reconocidos en los artículos 17, 18, apartados 2 y 3, artículos 19, 20, apartados 1, a) y d), y 5, artículos 21, 28, apartado 2, y artículo 37, apartado 2, podrán ser suspendidos cuando se acuerde la declaración del estado de excepción o de sitio en los términos previstos en la Constitución. Se exceptúa de lo establecido anteriormente el apartado 3 del artículo 17 para el supuesto de declaración de estado de excepción.»", "fuente": "Artículo 55.1 CE"}], "marca": {"nivel": "estrella", "nota": "Estados de alarma, excepción y sitio: quién los declara, cuánto duran y qué derechos se suspenden. Cae en el INAP y en todas las listas."}, "truco": "Ojo con la letra pequeña del 55.1: el 17.3 se excepciona «para el supuesto de declaración de estado de excepción». En estado de SITIO sí puede suspenderse."}, {"id": "ce-054", "origen": "otras", "test": "Examen", "n": 7, "enunciado": "De conformidad con el artículo 116 de la CE, el estado de sitio será declarado por:", "opciones": ["El Presidente del Gobierno mediante Real Decreto, previa autorización de las Cortes Generales.", "El Gobierno mediante decreto acordado en Consejo de Ministros, previa autorización de las Cortes Generales.", "El Gobierno mediante decreto acordado en Consejo de Ministros, previa autorización del Congreso de los Diputados.", "El Congreso de los Diputados por mayoría absoluta, a propuesta exclusiva del Gobierno."], "bloque": "t1-suspension", "precepto": "Artículo 116.4 CE", "correcta": 3, "justificaciones": ["No. El Presidente del Gobierno no declara estados excepcionales, y aquí tampoco hay autorización de las Cortes.", "No. Cambia el Congreso por las Cortes Generales.", "No. Describe el estado de excepción (116.3).", "Es esta. Literal del 116.4: lo declara el Congreso de los Diputados por mayoría absoluta, a propuesta exclusiva del Gobierno."], "arts": [116], "citas": [{"texto": "«El estado de sitio será declarado por la mayoría absoluta del Congreso de los Diputados, a propuesta exclusiva del Gobierno. El Congreso determinará su ámbito territorial, duración y condiciones.»", "fuente": "Artículo 116.4 CE"}], "marca": {"nivel": "estrella", "nota": "Estados de alarma, excepción y sitio: quién los declara, cuánto duran y qué derechos se suspenden. Cae en el INAP y en todas las listas."}, "truco": "Ninguno de los tres estados pasa por el Senado. Si una opción dice «Cortes Generales» en lugar de «Congreso de los Diputados», sospecha."}, {"id": "ce-055", "origen": "otras", "test": "Examen", "n": 10, "enunciado": "La suspensión de los derechos y libertades se encuentran regulada en la CE en:", "opciones": ["En el capítulo III del Título I", "En sus artículo 52 y 53", "En el artículo 58", "En el capítulo V del Título I"], "bloque": "t1-suspension", "precepto": "Constitución Española · Título I, Capítulo V", "correcta": 3, "justificaciones": ["No. El Capítulo III del Título I son los principios rectores de la política social y económica (artículos 39 a 52).", "No. El artículo 52 regula las organizaciones profesionales y el 53 las garantías: ninguno de los dos regula la suspensión.", "No. El artículo 58 es la Reina consorte, y está en el Título II.", "Es esta. El artículo 55 forma por sí solo el Capítulo V del Título I, cuya rúbrica es literalmente «De la suspensión de los derechos y libertades»."], "arts": [], "citas": [{"texto": "«CAPÍTULO QUINTO. De la suspensión de los derechos y libertades»: «Artículo 55. 1. Los derechos reconocidos en los artículos 17, 18, apartados 2 y 3 […] podrán ser suspendidos cuando se acuerde la declaración del estado de excepción o de sitio […]»", "fuente": "Constitución Española · Título I, Capítulo V"}], "truco": "Los cinco capítulos del Título I: I españoles y extranjeros (11-13) · II derechos y libertades (14-38) · III principios rectores (39-52) · IV garantías (53-54) · V suspensión (55)."}, {"id": "ce-056", "origen": "otras", "test": "Examen", "n": 13, "enunciado": "Conforme al artículo 55 de la Constitución Española de 1978, el derecho de los españoles a circular por el territorio nacional:", "opciones": ["Es un derecho fundamental que no puede ser suspendido.", "Podrá ser suspendido para personas determinadas, en relación con las investigaciones correspondientes a la actuación de bandas armadas o elementos terroristas.", "Podrá ser limitado por motivos políticos.", "Podrá ser suspendido cuando se acuerde la declaración del estado de excepción o de sitio."], "bloque": "t1-suspension", "precepto": "Artículo 55.1 CE; Artículo 19 CE", "correcta": 3, "justificaciones": ["No. Sí puede suspenderse: está en la lista del 55.1. Ser derecho fundamental no lo hace insuspendible.", "No. Describe la suspensión individual del 55.2, que solo alcanza al 17.2 y al 18.2 y 3, no al 19.", "No. Lo prohíbe el propio artículo 19: «Este derecho no podrá ser limitado por motivos políticos o ideológicos».", "Es esta. El artículo 19 figura expresamente en la lista del 55.1: se suspende cuando se declara el estado de excepción o de sitio."], "arts": [19, 55], "citas": [{"texto": "«Los derechos reconocidos en los artículos 17, 18, apartados 2 y 3, artículos 19, 20, apartados 1, a) y d), y 5, artículos 21, 28, apartado 2, y artículo 37, apartado 2, podrán ser suspendidos cuando se acuerde la declaración del estado de excepción o de sitio en los términos previstos en la Constitución. Se exceptúa de lo establecido anteriormente el apartado 3 del artículo 17 para el supuesto de declaración de estado de excepción.»", "fuente": "Artículo 55.1 CE"}, {"texto": "«Los españoles tienen derecho a elegir libremente su residencia y a circular por el territorio nacional. Asimismo, tienen derecho a entrar y salir libremente de España en los términos que la ley establezca. Este derecho no podrá ser limitado por motivos políticos o ideológicos.»", "fuente": "Artículo 19 CE"}], "marca": {"nivel": "estrella", "nota": "Estados de alarma, excepción y sitio: quién los declara, cuánto duran y qué derechos se suspenden. Cae en el INAP y en todas las listas."}}, {"id": "ce-057", "origen": "otras", "test": "Examen", "n": 18, "enunciado": "De conformidad con el artículo 55 de la Constitución Española, ¿cuál de los siguientes derechos NO podrán ser suspendidos cuando se acuerde la declaración del estado de excepción?", "opciones": ["El derecho a la inviolabilidad del domicilio.", "El derecho de toda persona detenida a ser informada de forma inmediata, y de modo que le sea comprensible, de sus derechos y de las razones de su detención, no pudiendo ser obligada a declarar.", "El derecho a comunicar o recibir libremente información veraz por cualquier medio de difusión.", "El derecho del detenido a ser puesto en libertad o a disposición de la autoridad judicial, en el plazo máximo de setenta y dos horas."], "bloque": "t1-suspension", "precepto": "Artículo 55.1 CE", "correcta": 1, "justificaciones": ["No. La inviolabilidad del domicilio es el 18.2: sí se suspende.", "Es esta. El 55.1 suspende el artículo 17, pero excepciona su apartado 3 «para el supuesto de declaración de estado de excepción». Y el 17.3 es justamente el derecho a ser informado de forma inmediata y comprensible y a no ser obligado a declarar. La pregunta va del estado de excepción, así que ese es el que no se suspende.", "No. La información veraz es el 20.1.d): sí se suspende.", "No. Las setenta y dos horas son el 17.2: sí se suspenden."], "arts": [55], "citas": [{"texto": "«Los derechos reconocidos en los artículos 17, 18, apartados 2 y 3, artículos 19, 20, apartados 1, a) y d), y 5, artículos 21, 28, apartado 2, y artículo 37, apartado 2, podrán ser suspendidos cuando se acuerde la declaración del estado de excepción o de sitio en los términos previstos en la Constitución. Se exceptúa de lo establecido anteriormente el apartado 3 del artículo 17 para el supuesto de declaración de estado de excepción.»", "fuente": "Artículo 55.1 CE"}], "marca": {"nivel": "estrella", "nota": "Estados de alarma, excepción y sitio: quién los declara, cuánto duran y qué derechos se suspenden. Cae en el INAP y en todas las listas."}, "ojo": "El 17.3 es la excepción dentro de la excepción, pero solo a medias: el 55.1 lo excluye de la suspensión «para el supuesto de declaración de estado de excepción». En estado de SITIO sí puede suspenderse. Si el enunciado dice «sitio» en vez de «excepción», la respuesta cambia.", "truco": "La excepción del 17.3 vale SOLO para el estado de excepción. En estado de sitio también puede suspenderse. Es la letra pequeña del 55.1 que casi nadie lee."}, {"id": "ce-189", "origen": "oficiales", "test": "INAP sept 2023", "n": 33, "enunciado": "De conformidad con el artículo 116 de la CE, el estado de excepción será declarado por:", "opciones": ["El Presidente del Gobierno mediante Real Decreto, previa autorización de las Cortes Generales.", "El Gobierno mediante decreto acordado en Consejo de Ministros, previa autorización de las Cortes Generales.", "El Gobierno mediante decreto acordado en Consejo de Ministros, previa autorización del Congreso de los Diputados.", "El Congreso de los Diputados por mayoría absoluta, a propuesta del Gobierno."], "bloque": "t1-suspension", "precepto": "Artículo 116.3 CE", "correcta": 2, "justificaciones": ["No. No lo declara el Presidente del Gobierno en solitario, sino el Gobierno en Consejo de Ministros; y la autorización es del Congreso, no de las Cortes.", "No. El resto es correcto, pero quien autoriza es el **Congreso de los Diputados**, no las Cortes Generales.", "Es esta. Lo declara el Gobierno, pero necesita permiso previo del Congreso.", "No. Eso es el estado de sitio (116.4): lo declara el Congreso por mayoría absoluta a propuesta exclusiva del Gobierno."], "arts": [116], "citas": [{"texto": "«El estado de excepción será declarado por el Gobierno mediante decreto acordado en Consejo de Ministros, previa autorización del Congreso de los Diputados.»", "fuente": "Artículo 116.3 CE"}], "marca": {"nivel": "estrella", "nota": "Estados de alarma, excepción y sitio: quién los declara, cuánto duran y qué derechos se suspenden. Cae en el INAP y en todas las listas."}, "truco": "Los tres estados, en escalera: alarma, el Gobierno y da cuenta al Congreso (15 días); excepción, el Gobierno con autorización previa (30 días, prorrogables otros 30); sitio, lo declara el Congreso por mayoría absoluta."}, {"id": "ce-106", "origen": "otras", "test": "Test exámenes", "n": 19, "enunciado": "De acuerdo con la Ley Orgánica del Tribunal Constitucional, señale cuáles son los procedimientos de declaración de inconstitucionalidad:", "opciones": ["El recurso de inconstitucionalidad y la cuestión de inconstitucionalidad promovida por jueces y tribunales.", "El recurso de inconstitucionalidad y el recurso de amparo.", "La cuestión de inconstitucionalidad y los conflictos constitucionales de competencia.", "El recurso de inconstitucionalidad, la cuestión de inconstitucionalidad y los conflictos constitucionales de competencia."], "bloque": "t1-tc", "precepto": "Ley Orgánica 2/1979 · rúbricas del Título II", "correcta": 0, "justificaciones": ["Es esta. El Título II de la LOTC lleva exactamente ese nombre y solo contiene dos capítulos: el recurso de inconstitucionalidad y la cuestión que plantean los jueces y tribunales.", "No. El recurso de amparo es el Título III de la LOTC: no declara inconstitucional una ley, protege un derecho concreto.", "No. Los conflictos constitucionales de competencia son el Título IV, y además esta opción se olvida del recurso.", "No. Añade los conflictos de competencia, que están en el Título IV y no son un procedimiento de declaración de inconstitucionalidad."], "arts": [], "citas": [{"texto": "«TÍTULO II. De los procedimientos de declaración de inconstitucionalidad» («CAPÍTULO I. Del recurso de inconstitucionalidad») «CAPÍTULO II. De la cuestión de inconstitucionalidad promovida por Jueces o Tribunales»", "fuente": "Ley Orgánica 2/1979 · rúbricas del Título II"}], "truco": "La diferencia está en el efecto: el recurso y la cuestión pueden DECLARAR inconstitucional una ley. El amparo protege un derecho concreto y los conflictos reparten competencias."}, {"id": "ce-107", "origen": "otras", "test": "Test exámenes", "n": 26, "enunciado": "Señale la afirmación correcta respecto al recurso de inscostitucionalidad, según la Constitución:", "opciones": ["Está legitimado para interponerlo el Ministerio Fiscal.", "Se interpone contra Leyes y disposiciones normativas con rango reglamentario.", "Está legitimado para interponerlo el Defensor del Pueblo.", "Podrá interponerse el recurso en cualquier momento desde la publicación de la disposición normativa."], "bloque": "t1-tc", "precepto": "Artículo 162.1 CE", "correcta": 2, "justificaciones": ["No. El Ministerio Fiscal solo está legitimado para el amparo, en la letra b).", "No. El recurso se dirige contra «leyes y disposiciones normativas con fuerza de ley» (161.1.a): los reglamentos los controla la jurisdicción ordinaria.", "Es esta. El Defensor del Pueblo aparece expresamente en la lista del 162.1.a).", "No. El plazo es de tres meses desde la publicación (artículo 33.1 LOTC), no en cualquier momento."], "arts": [162], "citas": [{"texto": "«Están legitimados: a) Para interponer el recurso de inconstitucionalidad, el Presidente del Gobierno, el Defensor del Pueblo, 50 Diputados, 50 Senadores, los órganos colegiados ejecutivos de las Comunidades Autónomas y, en su caso, las Asambleas de las mismas. b) Para interponer el recurso de amparo, toda persona natural o jurídica que invoque un interés legítimo, así como el Defensor del Pueblo y el Ministerio Fiscal.»", "fuente": "Artículo 162.1 CE"}], "marca": {"nivel": "clave", "nota": "El Tribunal Constitucional: composición, quién propone a sus doce magistrados y quién puede recurrir."}, "truco": "Dos listas dentro del 162.1: la a) es la del recurso de inconstitucionalidad (cargos e instituciones) y la b) la del amparo (cualquiera con interés legítimo, más Defensor y Fiscal)."}, {"id": "ce-108", "origen": "otras", "test": "Test exámenes", "n": 27, "enunciado": "Según la Constitución, la legitimación para interponer tanto el recurso de inconstitucionalidad como el recurso de amparo corresponde a:", "opciones": ["El Presidente del Gobierno.", "50 Diputados y 50 Senadores.", "El Defensor del Pueblo.", "Toda persona natural o jurídica que invoque un interés legítimo."], "bloque": "t1-tc", "precepto": "Artículo 162.1 CE", "correcta": 2, "justificaciones": ["No. El Presidente del Gobierno solo está en la letra a).", "No. Los 50 diputados y 50 senadores solo están en la letra a).", "Es esta. El Defensor del Pueblo es el único sujeto que figura en las dos letras del 162.1: en la a) para el recurso de inconstitucionalidad y en la b) para el amparo.", "No. Los particulares con interés legítimo solo están en la letra b)."], "arts": [162], "citas": [{"texto": "«Están legitimados: a) Para interponer el recurso de inconstitucionalidad, el Presidente del Gobierno, el Defensor del Pueblo, 50 Diputados, 50 Senadores, los órganos colegiados ejecutivos de las Comunidades Autónomas y, en su caso, las Asambleas de las mismas. b) Para interponer el recurso de amparo, toda persona natural o jurídica que invoque un interés legítimo, así como el Defensor del Pueblo y el Ministerio Fiscal.»", "fuente": "Artículo 162.1 CE"}], "marca": {"nivel": "clave", "nota": "El Tribunal Constitucional: composición, quién propone a sus doce magistrados y quién puede recurrir."}, "truco": "El Defensor del Pueblo es la bisagra: inconstitucionalidad Y amparo. El Ministerio Fiscal, solo amparo. El Presidente del Gobierno y los parlamentarios, solo inconstitucionalidad."}, {"id": "ce-109", "origen": "otras", "test": "Test exámenes", "n": 30, "enunciado": "Según establece el artículo 159.1 de la Ce, el Tribunal Constitucional se compone de:", "opciones": ["10 miembros nombrados por el Rey, de ellos, tres a propuesta de Congreso por mayoría de tres quintos de sus miembros, tres a propuesta del Senado, con idéntica mayoría; dos a propuesta del Gobierno, y dos a propuesta del Consejo General del Poder Judicial.", "12 miembros nombrados por el Rey, de ellos, cuatro a propuesta de Congreso por mayoría de dos tercios de sus miembros, cuatro a propuesta del Senado, con idéntica mayoría; dos a propuesta del Gobierno, y dos a propuesta del Consejo General del Poder Judicial.", "12 miembros nombrados por el Rey, de ellos, cuatro a propuesta de Congreso por mayoría de tres cuartos de sus miembros, cuatro a propuesta del Senado, con idéntica mayoría; dos a propuesta del Gobierno, y dos a propuesta del Consejo General del Poder Judicial.", "12 miembros nombrados por el Rey, de ellos, cuatro a propuesta de Congreso por mayoría de tres quintos de sus miembros, cuatro a propuesta del Senado, con idéntica mayoría; dos a propuesta del Gobierno, y dos a propuesta del Consejo General del Poder Judicial."], "bloque": "t1-tc", "precepto": "Artículo 159.1 CE", "correcta": 3, "justificaciones": ["No. Cambia doce por diez y los cuatro de cada Cámara por tres.", "No. Cambia la mayoría de tres quintos por dos tercios.", "No. Cambia la mayoría de tres quintos por tres cuartos.", "Es esta. Reproduce el 159.1 palabra por palabra: doce miembros, cuatro y cuatro por tres quintos, dos y dos."], "arts": [159], "citas": [{"texto": "«El Tribunal Constitucional se compone de 12 miembros nombrados por el Rey; de ellos, cuatro a propuesta del Congreso por mayoría de tres quintos de sus miembros; cuatro a propuesta del Senado, con idéntica mayoría; dos a propuesta del Gobierno, y dos a propuesta del Consejo General del Poder Judicial.»", "fuente": "Artículo 159.1 CE"}], "marca": {"nivel": "clave", "nota": "El Tribunal Constitucional: composición, quién propone a sus doce magistrados y quién puede recurrir."}, "truco": "12 = 4 Congreso + 4 Senado + 2 Gobierno + 2 CGPJ. Y las Cámaras proponen por TRES QUINTOS."}, {"id": "ce-110", "origen": "otras", "test": "Test exámenes", "n": 33, "enunciado": "Conforme al artículo 164 de la CE, las sentencia del Tribunal Constitucional:", "opciones": ["Las que estimen subjetivamente un derecho tiene plenos efectos frente a todos.", "Pueden ser objeto de recurso de casación para la unificación de la doctrina.", "Se publicarán en el Boletín Oficial de Estado con los votos particulares, si los hubiere.", "Tienen el valor de cosa juzgada desde el día siguiente de su publicación."], "bloque": "t1-tc", "precepto": "Artículo 164.1 CE", "correcta": 2, "justificaciones": ["No. Invierte el precepto: tienen plenos efectos frente a todos las que declaran la inconstitucionalidad y todas las que NO se limitan a la estimación subjetiva de un derecho.", "No. El 164.1 dice que «no cabe recurso alguno contra ellas»: menos aún una casación.", "Es esta. Es el arranque literal del 164.1: se publican en el BOE con los votos particulares, si los hubiere.", "No. También reproduce el 164.1 («tienen el valor de cosa juzgada a partir del día siguiente de su publicación»), así que es igualmente cierta. Ahí está el defecto de la pregunta."], "arts": [164], "citas": [{"texto": "«Las sentencias del Tribunal Constitucional se publicarán en el boletín oficial del Estado con los votos particulares, si los hubiere. Tienen el valor de cosa juzgada a partir del día siguiente de su publicación y no cabe recurso alguno contra ellas. Las que declaren la inconstitucionalidad de una ley o de una norma con fuerza de ley y todas las que no se limiten a la estimación subjetiva de un derecho, tienen plenos efectos frente a todos.»", "fuente": "Artículo 164.1 CE"}], "ojo": "La opción del «valor de cosa juzgada desde el día siguiente de su publicación» también reproduce el artículo 164.1. La plantilla del documento da la de la publicación en el BOE con los votos particulares; en un examen oficial esta pregunta sería impugnable por tener dos respuestas ciertas."}, {"id": "ce-111", "origen": "otras", "test": "Test exámenes", "n": 43, "enunciado": "Según el artículo 159 de la CE, los miembros del Tribunal Constitucional, aparte de sus incompatibilidades específicas, tendrán las incompatibilidades propias de:", "opciones": ["Los miembros de las Cortes Generales.", "Los miembros del Gobierno de España.", "Los miembros del Tribunal de Cuentas.", "Los miembros del Poder Judicial."], "bloque": "t1-tc", "precepto": "Artículo 159.4 CE", "correcta": 3, "justificaciones": ["No. Los miembros de las Cortes Generales tienen su propio régimen y el 159.4 no remite a él.", "No. Tampoco remite al régimen de los miembros del Gobierno.", "No. Ni al del Tribunal de Cuentas.", "Es esta. La cláusula de cierre del 159.4: «En lo demás […] tendrán las incompatibilidades propias de los miembros del poder judicial»."], "arts": [159], "citas": [{"texto": "«La condición de miembro del Tribunal Constitucional es incompatible: con todo mandato representativo; con los cargos políticos o administrativos; con el desempeño de funciones directivas en un partido político o en un sindicato y con el empleo al servicio de los mismos; con el ejercicio de las carreras judicial y fiscal, y con cualquier actividad profesional o mercantil. En lo demás los miembros del Tribunal Constitucional tendrán las incompatibilidades propias de los miembros del poder judicial.»", "fuente": "Artículo 159.4 CE"}], "marca": {"nivel": "clave", "nota": "El Tribunal Constitucional: composición, quién propone a sus doce magistrados y quién puede recurrir."}, "truco": "El 159.4 hace dos cosas: primero enumera las incompatibilidades propias y luego cierra remitiendo a las del poder judicial. La remisión final es la que se pregunta."}, {"id": "ce-112", "origen": "otras", "test": "Test exámenes", "n": 54, "enunciado": "Según la Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional, sus magistrados:", "opciones": ["Serán nombrados por el Rey, a propuesta de las Cámaras, del Gobierno y del Consejo General del Poder Judicial.", "Serán nombrados por el Presidente del Congreso por mayoría de tres quintas partes de sus diputados.", "Serán nombrados por la Comisión Mixta Congreso-Senado, a propuesta del Presidente del Tribunal Supremo.", "Serán nombrados por el Rey, a propuesta conjunta del Presidente del Gobierno y del Tribunal Supremo."], "bloque": "t1-tc", "precepto": "Artículo 159.1 CE", "correcta": 0, "justificaciones": ["Es esta. Doce magistrados nombrados por el Rey a propuesta de las Cámaras (cuatro y cuatro), del Gobierno (dos) y del Consejo General del Poder Judicial (dos). El artículo 16.1 de la LOTC reproduce ese esquema y añade que se hace por real decreto refrendado por el Presidente del Gobierno.", "No. El Presidente del Congreso no nombra magistrados: el Congreso propone y el Rey nombra.", "No. La Comisión Mixta Congreso-Senado es del Defensor del Pueblo (artículo 2 de la LO 3/1981), no del Tribunal Constitucional.", "No. El Tribunal Supremo no propone magistrados del Tribunal Constitucional."], "arts": [159], "citas": [{"texto": "«El Tribunal Constitucional se compone de 12 miembros nombrados por el Rey; de ellos, cuatro a propuesta del Congreso por mayoría de tres quintos de sus miembros; cuatro a propuesta del Senado, con idéntica mayoría; dos a propuesta del Gobierno, y dos a propuesta del Consejo General del Poder Judicial.»", "fuente": "Artículo 159.1 CE"}], "marca": {"nivel": "clave", "nota": "El Tribunal Constitucional: composición, quién propone a sus doce magistrados y quién puede recurrir."}}, {"id": "ce-113", "origen": "otras", "test": "Test exámenes", "n": 57, "enunciado": "De acuerdo con el artículo 161.1 de la Constitución, el Tribunal Constitucional tiene jurisdicción en todo el territorio español y es competente para conocer:", "opciones": ["De los conflictos de competencia entre Comunidades Autónomas.", "Del recurso de inconstitucionalidad contra leyes y reglamentos.", "Del recurso de casación.", "De las demás materias que le atribuyan las leyes estatales y las leyes de las Comunidades Autónomas."], "bloque": "t1-tc", "precepto": "Artículo 161.1 CE", "correcta": 0, "justificaciones": ["Es esta. La letra c) del 161.1 incluye los conflictos «de éstas entre sí», es decir, entre Comunidades Autónomas.", "No. El 161.1.a) habla de «leyes y disposiciones normativas con fuerza de ley». Los reglamentos los controla la jurisdicción ordinaria.", "No. El recurso de casación es competencia del Tribunal Supremo, no del Constitucional.", "No. El 161.1.d) dice «la Constitución o las leyes orgánicas», no «las leyes estatales y las leyes de las Comunidades Autónomas»."], "arts": [161], "citas": [{"texto": "«El Tribunal Constitucional tiene jurisdicción en todo el territorio español y es competente para conocer: a) Del recurso de inconstitucionalidad contra leyes y disposiciones normativas con fuerza de ley. […] b) Del recurso de amparo por violación de los derechos y libertades referidos en el artículo 53, 2, de esta Constitución, en los casos y formas que la ley establezca. c) De los conflictos de competencia entre el Estado y las Comunidades Autónomas o de los de éstas entre sí. d) De las demás materias que le atribuyan la Constitución o las leyes orgánicas.»", "fuente": "Artículo 161.1 CE"}], "marca": {"nivel": "clave", "nota": "El Tribunal Constitucional: composición, quién propone a sus doce magistrados y quién puede recurrir."}, "truco": "El 161.1 tiene cuatro letras: a) recurso de inconstitucionalidad · b) amparo · c) conflictos de competencia · d) las demás materias que le atribuyan la Constitución o las leyes orgánicas. La cuestión de inconstitucionalidad NO está aquí: es el artículo 163."}, {"id": "ce-114", "origen": "otras", "test": "Test exámenes", "n": 60, "enunciado": "Los miembros del Tribunal Constitucional son designados por un periodo de:", "opciones": ["Cuatro años y se renovarán por mitades cada tres.", "Tres años y se renovarán por mitades cada dos.", "Seis años y se renovarán por mitades cada dos.", "Nueve años y se renovarán por terceras partes cada tres."], "bloque": "t1-tc", "precepto": "Artículo 159.3 CE", "correcta": 3, "justificaciones": ["No. Ni la duración (cuatro años) ni la forma de renovación (por mitades) son las del 159.3.", "No. Tres años y mitades cada dos: tampoco.", "No. Seis años y mitades cada dos: tampoco.", "Es esta. Literal del 159.3: nueve años y renovación por terceras partes cada tres."], "arts": [159], "citas": [{"texto": "«Los miembros del Tribunal Constitucional serán designados por un período de nueve años y se renovarán por terceras partes cada tres.»", "fuente": "Artículo 159.3 CE"}], "marca": {"nivel": "clave", "nota": "El Tribunal Constitucional: composición, quién propone a sus doce magistrados y quién puede recurrir."}, "truco": "Nueve años y renovación por TERCERAS partes cada TRES: nueve dividido entre tres, tres. Las opciones falsas casi siempre dicen «por mitades»."}, {"id": "ce-115", "origen": "otras", "test": "Test exámenes", "n": 70, "enunciado": "Señale la afirmación correcta. La responsabilidad criminal de los Magistrados del Tribunal Constitucional sólo será exigible ante:", "opciones": ["El propio Tribunal Constitucional.", "La Sala de lo Penal del Tribunal Supremo.", "Las Cortes Generales.", "La Sala de lo Militar del Tribunal Supremo."], "bloque": "t1-tc", "precepto": "Artículo 26 LOTC", "correcta": 1, "justificaciones": ["No. El propio Tribunal decide sobre el cese de sus magistrados (artículo 23.2 LOTC), no sobre su responsabilidad criminal.", "Es esta. Literal del artículo 26 de la LOTC: solo ante la Sala de lo Penal del Tribunal Supremo.", "No. Las Cortes Generales no tienen función jurisdiccional.", "No. El artículo 26 dice Sala de lo Penal; la Sala de lo Militar es la Quinta y no es competente."], "arts": [], "citas": [{"texto": "«La responsabilidad criminal de los Magistrados del Tribunal Constitucional sólo será exigible ante la Sala de lo Penal del Tribunal Supremo.»", "fuente": "Artículo 26 LOTC"}], "marca": {"nivel": "poco", "nota": "El detalle de la Ley Orgánica del Tribunal Constitucional no aparece en las listas ni en las preguntas oficiales del banco."}, "truco": "Mismo aforamiento que el Defensor del Pueblo y sus Adjuntos: Sala de lo Penal del Tribunal Supremo. Un solo dato para dos instituciones."}, {"id": "ce-116", "origen": "otras", "test": "Test exámenes", "n": 76, "enunciado": "Está legitimado para interponer recurso de inconstitucionalidad:", "opciones": ["El Presidente del Congreso de los Diputados.", "La Federación Española de Municipios y Provincias.", "Los órganos colegiados ejecutivos de las Comunidades Autónomas.", "30 Senadores."], "bloque": "t1-tc", "precepto": "Artículo 162.1 CE", "correcta": 2, "justificaciones": ["No. El Presidente del Congreso no está legitimado; sí lo están 50 diputados.", "No. La Federación Española de Municipios y Provincias no aparece. Los entes locales tienen el conflicto en defensa de la autonomía local (artículo 75 bis LOTC), que es otro proceso.", "Es esta. Los órganos colegiados ejecutivos de las Comunidades Autónomas están expresamente en la lista del 162.1.a).", "No. Son 50 senadores, no 30."], "arts": [162], "citas": [{"texto": "«Están legitimados: a) Para interponer el recurso de inconstitucionalidad, el Presidente del Gobierno, el Defensor del Pueblo, 50 Diputados, 50 Senadores, los órganos colegiados ejecutivos de las Comunidades Autónomas y, en su caso, las Asambleas de las mismas. b) Para interponer el recurso de amparo, toda persona natural o jurídica que invoque un interés legítimo, así como el Defensor del Pueblo y el Ministerio Fiscal.»", "fuente": "Artículo 162.1 CE"}], "marca": {"nivel": "clave", "nota": "El Tribunal Constitucional: composición, quién propone a sus doce magistrados y quién puede recurrir."}, "truco": "Los números del 162.1.a) son 50 y 50. Cualquier otra cifra (30, 25, 60) es falsa."}, {"id": "ce-117", "origen": "otras", "test": "Test exámenes", "n": 87, "enunciado": "Según la LOTC, los magistrados del Tribunal Constitucional:", "opciones": ["Podrán compatibilizar su cargo con el de senador.", "Ejercerán su función conforme a los principios de imparcialidad y dignidad inherentes a la misma.", "Podrán ser perseguidos por las opiniones expresadas en el ejercicio de sus funciones.", "Podrán ser cesados por incompatibilidad sobrevenida decretada por el presidente del Tribunal Constitucional."], "bloque": "t1-tc", "precepto": "Artículo 22 LOTC; Artículo 23.2 LOTC", "correcta": 1, "justificaciones": ["No. El 159.4 CE declara la condición de magistrado incompatible «con todo mandato representativo»: no puede ser senador.", "Es esta. Literal del artículo 22 de la LOTC: ejercen su función de acuerdo con los principios de imparcialidad y dignidad inherentes a la misma.", "No. El artículo 22 dice exactamente lo contrario: no pueden ser perseguidos por las opiniones expresadas en el ejercicio de sus funciones.", "No. El cese por incompatibilidad sobrevenida lo decide el Tribunal en Pleno por mayoría simple (artículo 23.2 LOTC), no el Presidente."], "arts": [], "citas": [{"texto": "«Los Magistrados del Tribunal Constitucional ejercerán su función de acuerdo con los principios de imparcialidad y dignidad inherentes a la misma; no podrán ser perseguidos por las opiniones expresadas en el ejercicio de sus funciones; serán inamovibles y no podrán ser destituidos ni suspendidos sino por alguna de las causas que esta Ley establece.»", "fuente": "Artículo 22 LOTC"}, {"texto": "«El cese o la vacante en el cargo de Magistrado del Tribunal Constitucional, en los casos 1.º y 2.º, así como en el de fallecimiento, se decretará por el Presidente. En los restantes supuestos decidirá el Tribunal en Pleno, por mayoría simple en los casos 3.º y 4.º y por mayoría de las tres cuartas partes de sus miembros en los demás casos.»", "fuente": "Artículo 23.2 LOTC"}], "marca": {"nivel": "poco", "nota": "El detalle de la Ley Orgánica del Tribunal Constitucional no aparece en las listas ni en las preguntas oficiales del banco."}, "truco": "El Presidente solo decreta el cese en tres casos: renuncia, expiración del plazo y fallecimiento. Todo lo demás lo decide el Pleno."}, {"id": "ce-118", "origen": "otras", "test": "Test exámenes", "n": 93, "enunciado": "De acuerdo con lo dispuesto en el artículo 78 de la Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional, ¿quién puede requerir al Tribunal para que se pronuncie sobre la posible contradicción entre la Constitución y las estipulaciones de un tratado internacional?:", "opciones": ["El Presidente del Gobierno, el Defensor del Pueblo, 50 Diputados ó 50 Senadores.", "El Gobierno o cualquiera de las Cámaras.", "El Presidente del Gobierno y el Presidente del Congreso de los Diputados.", "El Presidente del Gobierno y el Presidente del Senado."], "bloque": "t1-tc", "precepto": "Artículo 78.1 LOTC", "correcta": 1, "justificaciones": ["No. Esa es la lista de legitimados del recurso de inconstitucionalidad (162.1.a CE), no la del requerimiento previo.", "Es esta. Literal del 78.1: el Gobierno o cualquiera de ambas Cámaras.", "No. El Presidente del Congreso por sí solo no: el precepto habla de la Cámara como órgano.", "No. El Presidente del Senado por sí solo, tampoco."], "arts": [], "citas": [{"texto": "«El Gobierno o cualquiera de ambas Cámaras podrán requerir al Tribunal Constitucional para que se pronuncie sobre la existencia o inexistencia de contradicción entre la Constitución y las estipulaciones de un tratado internacional cuyo texto estuviera ya definitivamente fijado, pero al que no se hubiere prestado aún el consentimiento del Estado.»", "fuente": "Artículo 78.1 LOTC"}], "marca": {"nivel": "poco", "nota": "El detalle de la Ley Orgánica del Tribunal Constitucional no aparece en las listas ni en las preguntas oficiales del banco."}, "truco": "Es el único control PREVIO de constitucionalidad que queda en nuestro ordenamiento: solo para tratados, y solo lo piden el Gobierno o una Cámara."}, {"id": "ce-119", "origen": "otras", "test": "Test exámenes", "n": 94, "enunciado": "De acuerdo a lo establecido en el artículo 27.2 de la LOTC, NO serán susceptibles de declaración de inconstitucionalidad:", "opciones": ["Los Reglamentos estatales y autonómicos.", "Los Reglamentos de las Asambleas legislativas de las Comunidades Autónomas.", "Los Reglamentos de las Cámaras y de las Cortes Generales.", "Los Estatutos de Autonomía y las demás Leyes orgánicas."], "bloque": "t1-tc", "precepto": "Artículo 27.2 LOTC", "correcta": 0, "justificaciones": ["Es esta. La lista del 27.2 no incluye los reglamentos administrativos, ni estatales ni autonómicos: su control es de la jurisdicción contencioso-administrativa.", "No. Los Reglamentos de las Asambleas legislativas de las Comunidades Autónomas sí están: letra f).", "No. Los Reglamentos de las Cámaras y de las Cortes Generales sí están: letra d).", "No. Los Estatutos de Autonomía y las demás leyes orgánicas sí están: letra a)."], "arts": [], "citas": [{"texto": "Son susceptibles de declaración de inconstitucionalidad: «a) Los Estatutos de Autonomía y las demás leyes orgánicas. b) Las demás leyes, disposiciones normativas y actos del Estado con fuerza de ley […]. c) Los tratados internacionales. d) Los Reglamentos de las Cámaras y de las Cortes Generales. e) Las leyes, actos y disposiciones normativas con fuerza de ley de las Comunidades Autónomas. f) Los Reglamentos de las Asambleas legislativas de las Comunidades Autónomas.»", "fuente": "Artículo 27.2 LOTC"}], "marca": {"nivel": "poco", "nota": "El detalle de la Ley Orgánica del Tribunal Constitucional no aparece en las listas ni en las preguntas oficiales del banco."}, "ojo": "«Reglamento de una Cámara» (norma con valor de ley que regula su funcionamiento) no es lo mismo que «reglamento administrativo». La pregunta juega justo con esa palabra."}, {"id": "ce-120", "origen": "otras", "test": "Test exámenes", "n": 99, "enunciado": "Según el artículo 162.1.a) de la CE, NO está legitimado para interponer un recurso de inconstitucionalidad:", "opciones": ["La Asamblea de una Comunidad Autónoma.", "El Presidente del Gobierno.", "El Defensor del Pueblo.", "El Ministerio Fiscal."], "bloque": "t1-tc", "precepto": "Artículo 162.1 CE", "correcta": 3, "justificaciones": ["No. La Asamblea de una Comunidad Autónoma sí está en la letra a).", "No. El Presidente del Gobierno sí está en la letra a).", "No. El Defensor del Pueblo sí está en la letra a).", "Es esta. El Ministerio Fiscal no aparece en la letra a) del 162.1: solo en la b), la del amparo."], "arts": [162], "citas": [{"texto": "«Están legitimados: a) Para interponer el recurso de inconstitucionalidad, el Presidente del Gobierno, el Defensor del Pueblo, 50 Diputados, 50 Senadores, los órganos colegiados ejecutivos de las Comunidades Autónomas y, en su caso, las Asambleas de las mismas. b) Para interponer el recurso de amparo, toda persona natural o jurídica que invoque un interés legítimo, así como el Defensor del Pueblo y el Ministerio Fiscal.»", "fuente": "Artículo 162.1 CE"}], "marca": {"nivel": "clave", "nota": "El Tribunal Constitucional: composición, quién propone a sus doce magistrados y quién puede recurrir."}}, {"id": "ce-121", "origen": "otras", "test": "Test exámenes", "n": 100, "enunciado": "De acuerdo con la Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional, podrán dar lugar al planteamiento de los conflictos en defensa de la autonomía local:", "opciones": ["Las leyes y reglamentos del Estado que lesionen la autonomía local constitucionalmente garantizada.", "Las normas del Estado con rango de ley o las disposiciones con rango de ley de las Comunidades Autónomas que lesionen la autonomía local constitucionalmente garantizada.", "Las leyes y reglamentos de las Comunidades Autónomas que lesionen la autonomía local constitucionalmente garantizada.", "Las leyes y reglamentos del Estado o de las Comunidades Autónomas que lesionen la autonomía local constitucionalmente garantizada."], "bloque": "t1-tc", "precepto": "Artículo 75 bis.1 LOTC", "correcta": 1, "justificaciones": ["No. Añade los reglamentos del Estado, que no caben en este conflicto.", "Es esta. Literal del 75 bis.1: normas del Estado con rango de ley o disposiciones con rango de ley de las Comunidades Autónomas.", "No. Habla de leyes y reglamentos autonómicos y se olvida de las normas estatales.", "No. Mete reglamentos de los dos niveles, estatal y autonómico."], "arts": [], "citas": [{"texto": "«Podrán dar lugar al planteamiento de los conflictos en defensa de la autonomía local las normas del Estado con rango de ley o las disposiciones con rango de ley de las Comunidades Autónomas que lesionen la autonomía local constitucionalmente garantizada.»", "fuente": "Artículo 75 bis.1 LOTC"}], "marca": {"nivel": "poco", "nota": "El detalle de la Ley Orgánica del Tribunal Constitucional no aparece en las listas ni en las preguntas oficiales del banco."}, "truco": "Solo normas con RANGO DE LEY. Frente a un reglamento el ente local va a la jurisdicción contencioso-administrativa, no al Tribunal Constitucional."}, {"id": "ce-122", "origen": "otras", "test": "Test exámenes", "n": 105, "enunciado": "Según el artículo 78 de la Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional, ¿quién puede dirigirse al Tribunal Constitucional para que se pronuncie sobre la existencia o no de contradicción entre la CE y las estipulaciones de un tratado internacional cuyo texto estuviera ya definitivamente fijado, pero al que no se hubiere prestado aún el consentimiento del Estado?:", "opciones": ["El Presidente del Gobierno.", "El Gobierno o cualquiera de ambas Cámaras.", "El Gobierno, cualquiera de las Cámaras o cualquier juez o tribunal.", "Quienes se hayan legitimados para el recurso de inconstitucionalidad."], "bloque": "t1-tc", "precepto": "Artículo 78.1 LOTC", "correcta": 1, "justificaciones": ["No. El Presidente del Gobierno por sí solo no: el precepto habla del Gobierno como órgano.", "Es esta. Literal del 78.1, que describe exactamente ese supuesto: texto ya fijado pero consentimiento aún no prestado.", "No. Los jueces y tribunales plantean la cuestión de inconstitucionalidad (artículo 163 CE), no este requerimiento.", "No. Los legitimados del 162.1.a) lo están para el recurso de inconstitucionalidad, no para el requerimiento previo."], "arts": [], "citas": [{"texto": "«El Gobierno o cualquiera de ambas Cámaras podrán requerir al Tribunal Constitucional para que se pronuncie sobre la existencia o inexistencia de contradicción entre la Constitución y las estipulaciones de un tratado internacional cuyo texto estuviera ya definitivamente fijado, pero al que no se hubiere prestado aún el consentimiento del Estado.»", "fuente": "Artículo 78.1 LOTC"}], "marca": {"nivel": "poco", "nota": "El detalle de la Ley Orgánica del Tribunal Constitucional no aparece en las listas ni en las preguntas oficiales del banco."}}, {"id": "ce-123", "origen": "otras", "test": "Examen", "n": 3, "enunciado": "De acuerdo con lo establecido en la Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional, el Tribunal en Pleno puede adoptar acuerdos cuando estén presentes:", "opciones": ["Al menos, tres quintos de los miembros que en cada momento lo compongan.", "La mitad más uno de los miembros que en cada momento lo compongan.", "Al menos, dos tercios de los miembros que en cada momento lo compongan.", "Al menos, un tercio de los miembros que en cada momento lo compongan."], "bloque": "t1-tc", "precepto": "Artículo 14 LOTC", "correcta": 2, "justificaciones": ["No. Los tres quintos no son quórum del Pleno: son la mayoría con la que las Cámaras proponen magistrados (159.1 CE).", "No. La mitad más uno es la mayoría absoluta, que no es el quórum del artículo 14.", "Es esta. Literal del artículo 14 de la LOTC: al menos dos tercios de los miembros que en cada momento lo compongan.", "No. Un tercio no basta: se exigen dos tercios."], "arts": [], "citas": [{"texto": "«El Tribunal en Pleno puede adoptar acuerdos cuando estén presentes, al menos, dos tercios de los miembros que en cada momento lo compongan. Los acuerdos de las Salas requerirán asimismo la presencia de dos tercios de los miembros que en cada momento las compongan. En las Secciones se requerirá la presencia de dos miembros, salvo que haya discrepancia, requiriéndose entonces la de sus tres miembros.»", "fuente": "Artículo 14 LOTC"}], "marca": {"nivel": "poco", "nota": "El detalle de la Ley Orgánica del Tribunal Constitucional no aparece en las listas ni en las preguntas oficiales del banco."}, "truco": "Dos tercios para el Pleno y dos tercios para las Salas. En las Secciones, dos miembros, salvo que haya discrepancia: entonces los tres."}, {"id": "ce-124", "origen": "otras", "test": "Examen", "n": 12, "enunciado": "Según el artículo 161 de la Constitución Española de 1978, el Tribunal Constitucional:", "opciones": ["Dicta sentencias que pueden ser objeto de recurso por los órganos colegiados ejecutivos de las Comunidades Autónomas.", "Es competente para conocer de los conflictos de competencia entre el Estado y las Comunidades Autónomas o de los de éstas entre sí.", "Es el órgano jurisdiccional superior en todos los órdenes.", "Tiene jurisdicción en aquellas Comunidades Autónomas que explícitamente lo reconozcan en sus Estatutos de Autonomía, sin perjuicio de la jurisdicción que corresponde al Tribunal Supremo."], "bloque": "t1-tc", "precepto": "Artículo 161.1 CE; Artículo 164.1 CE", "correcta": 1, "justificaciones": ["No. Contra las sentencias del Tribunal Constitucional no cabe recurso alguno (164.1).", "Es esta. Es la letra c) del 161.1, literal: conflictos de competencia entre el Estado y las Comunidades Autónomas o de éstas entre sí.", "No. El órgano jurisdiccional superior en todos los órdenes es el Tribunal Supremo (artículo 123.1), salvo lo dispuesto en materia de garantías constitucionales.", "No. El propio 161.1 dice que tiene jurisdicción «en todo el territorio español»: no depende de los Estatutos de Autonomía."], "arts": [161, 164], "citas": [{"texto": "«El Tribunal Constitucional tiene jurisdicción en todo el territorio español y es competente para conocer: a) Del recurso de inconstitucionalidad contra leyes y disposiciones normativas con fuerza de ley. […] b) Del recurso de amparo por violación de los derechos y libertades referidos en el artículo 53, 2, de esta Constitución, en los casos y formas que la ley establezca. c) De los conflictos de competencia entre el Estado y las Comunidades Autónomas o de los de éstas entre sí. d) De las demás materias que le atribuyan la Constitución o las leyes orgánicas.»", "fuente": "Artículo 161.1 CE"}, {"texto": "«Las sentencias del Tribunal Constitucional se publicarán en el boletín oficial del Estado con los votos particulares, si los hubiere. Tienen el valor de cosa juzgada a partir del día siguiente de su publicación y no cabe recurso alguno contra ellas. Las que declaren la inconstitucionalidad de una ley o de una norma con fuerza de ley y todas las que no se limiten a la estimación subjetiva de un derecho, tienen plenos efectos frente a todos.»", "fuente": "Artículo 164.1 CE"}], "marca": {"nivel": "clave", "nota": "El Tribunal Constitucional: composición, quién propone a sus doce magistrados y quién puede recurrir."}}, {"id": "ce-125", "origen": "otras", "test": "Test 1", "n": 9, "enunciado": "Los 12 miembros del Tribunal Constitucional tienen el título de:", "opciones": ["Jueces del Tribunal Constitucional.", "Magistrados del Tribunal Constitucional.", "Jueces Constituyentes.", "Consejeros Constitucionales."], "bloque": "t1-tc", "precepto": "Artículo 5 LOTC; Artículo 159.1 CE", "correcta": 1, "justificaciones": ["No. «Juez» es una categoría de la carrera judicial; en el Tribunal Constitucional no se emplea.", "Es esta. Literal del artículo 5 de la LOTC: doce miembros con el título de Magistrados del Tribunal Constitucional.", "No. «Jueces Constituyentes» no existe en nuestro ordenamiento.", "No. «Consejeros Constitucionales» es la denominación del Consejo Constitucional francés, no del Tribunal español."], "arts": [159], "citas": [{"texto": "«El Tribunal Constitucional está integrado por doce miembros, con el título de Magistrados del Tribunal Constitucional.»", "fuente": "Artículo 5 LOTC"}, {"texto": "«El Tribunal Constitucional se compone de 12 miembros nombrados por el Rey; de ellos, cuatro a propuesta del Congreso por mayoría de tres quintos de sus miembros; cuatro a propuesta del Senado, con idéntica mayoría; dos a propuesta del Gobierno, y dos a propuesta del Consejo General del Poder Judicial.»", "fuente": "Artículo 159.1 CE"}], "marca": {"nivel": "clave", "nota": "El Tribunal Constitucional: composición, quién propone a sus doce magistrados y quién puede recurrir."}, "truco": "Doce miembros con el título de MAGISTRADOS. Y el Presidente se elige entre ellos, por tres años, reelegible una sola vez."}, {"id": "ce-126", "origen": "otras", "test": "Test 1", "n": 10, "enunciado": "El mandato de los miembros del Tribunal Constitucional es de:", "opciones": ["6 años, con renovación por terceras partes cada 2.", "6 años, con renovación por mitades cada 3.", "9 años, con renovación por terceras partes cada 3.", "9 años, con renovación por mitades a mitad de mandato."], "bloque": "t1-tc", "precepto": "Artículo 159.3 CE", "correcta": 2, "justificaciones": ["No. La duración es de nueve años, no de seis, aunque acierte las terceras partes.", "No. Ni seis años ni renovación por mitades.", "Es esta. Literal del 159.3: nueve años, con renovación por terceras partes cada tres.", "No. Acierta los nueve años, pero la renovación es por terceras partes cada tres, no por mitades a mitad de mandato."], "arts": [159], "citas": [{"texto": "«Los miembros del Tribunal Constitucional serán designados por un período de nueve años y se renovarán por terceras partes cada tres.»", "fuente": "Artículo 159.3 CE"}], "marca": {"nivel": "clave", "nota": "El Tribunal Constitucional: composición, quién propone a sus doce magistrados y quién puede recurrir."}}, {"id": "ce-127", "origen": "otras", "test": "Test 1", "n": 11, "enunciado": "Están legitimados para interponer un recurso de inconstitucionalidad contra cualquier norma con rango de Ley:", "opciones": ["El Presidente del Gobierno.", "El Defensor del Pueblo.", "50 Diputados o 50 Senadores.", "Todas las respuestas son correctas."], "bloque": "t1-tc", "precepto": "Artículo 162.1 CE", "correcta": 3, "justificaciones": ["No. Es cierta, pero incompleta: no es la única legitimada.", "No. Es cierta, pero incompleta.", "No. Es cierta, pero incompleta.", "Es esta. El Presidente del Gobierno, el Defensor del Pueblo y los 50 diputados o 50 senadores están los tres en la lista del 162.1.a), así que ninguna de esas opciones sobra: la respuesta es «todas»."], "arts": [162], "citas": [{"texto": "«Están legitimados: a) Para interponer el recurso de inconstitucionalidad, el Presidente del Gobierno, el Defensor del Pueblo, 50 Diputados, 50 Senadores, los órganos colegiados ejecutivos de las Comunidades Autónomas y, en su caso, las Asambleas de las mismas. b) Para interponer el recurso de amparo, toda persona natural o jurídica que invoque un interés legítimo, así como el Defensor del Pueblo y el Ministerio Fiscal.»", "fuente": "Artículo 162.1 CE"}], "marca": {"nivel": "clave", "nota": "El Tribunal Constitucional: composición, quién propone a sus doce magistrados y quién puede recurrir."}, "truco": "La lista del 162.1.a) tiene cinco sujetos: Presidente del Gobierno · Defensor del Pueblo · 50 diputados · 50 senadores · órganos colegiados ejecutivos y, en su caso, Asambleas de las Comunidades Autónomas."}, {"id": "ce-128", "origen": "otras", "test": "Test 1", "n": 12, "enunciado": "Están legitimados para interponer el recurso de amparo:", "opciones": ["Cualquier persona física o jurídica que acredite un interés legítimo.", "El Defensor del Pueblo.", "El Ministerio Fiscal.", "Todas las respuestas son correctas."], "bloque": "t1-tc", "precepto": "Artículo 162.1 CE", "correcta": 3, "justificaciones": ["No. Es cierta, pero incompleta.", "No. Es cierta, pero incompleta.", "No. Es cierta, pero incompleta.", "Es esta. La letra b) del 162.1 enumera precisamente esos tres: toda persona natural o jurídica que invoque un interés legítimo, el Defensor del Pueblo y el Ministerio Fiscal."], "arts": [162], "citas": [{"texto": "«Están legitimados: a) Para interponer el recurso de inconstitucionalidad, el Presidente del Gobierno, el Defensor del Pueblo, 50 Diputados, 50 Senadores, los órganos colegiados ejecutivos de las Comunidades Autónomas y, en su caso, las Asambleas de las mismas. b) Para interponer el recurso de amparo, toda persona natural o jurídica que invoque un interés legítimo, así como el Defensor del Pueblo y el Ministerio Fiscal.»", "fuente": "Artículo 162.1 CE"}], "marca": {"nivel": "clave", "nota": "El Tribunal Constitucional: composición, quién propone a sus doce magistrados y quién puede recurrir."}, "ojo": "El Ministerio Fiscal está en el amparo y NO en el recurso de inconstitucionalidad. Es la diferencia que más se pregunta entre las dos listas del artículo 162."}, {"id": "ce-159", "origen": "oficiales", "test": "INAP julio 2026 (extraordinario)", "n": 1, "enunciado": "Señala la Constitución Española de 1978, en su artículo 159 que los miembros del Tribunal Constitucional:", "opciones": ["Serán designados por un periodo de seis años y se renovarán por terceras partes cada tres.", "Serán designados por un periodo de nueve años y se renovarán por terceras partes cada tres.", "Serán designados por un periodo de cuatro años y se renovarán por mitades cada dos.", "Serán designados por un periodo de cinco años."], "bloque": "t1-tc", "precepto": "Artículo 159.3 CE", "correcta": 1, "justificaciones": ["No. La renovación por tercios cada tres años es correcta, pero el mandato es de nueve años, no de seis.", "Es esta. Nueve años y renovación por tercios cada tres. Son doce miembros: los tercios salen a cuatro.", "No. Ni cuatro años ni renovación por mitades: eso no está en la Constitución.", "No. Cinco años es el mandato de los vocales del Consejo General del Poder Judicial (122.3)."], "arts": [159], "citas": [{"texto": "«Los miembros del Tribunal Constitucional serán designados por un período de nueve años y se renovarán por terceras partes cada tres.»", "fuente": "Artículo 159.3 CE"}], "marca": {"nivel": "clave", "nota": "El Tribunal Constitucional: composición, quién propone a sus doce magistrados y quién puede recurrir."}, "truco": "12 miembros · 9 años · por tercios cada 3. El 5 es del CGPJ y el 15 es el de los años de ejercicio profesional, que piden los dos."}, {"id": "ce-058", "origen": "otras", "test": "Test exámenes", "n": 12, "enunciado": "Conforme al artículo 168 de la Constitución Española, no sería necesario someter a referéndum una reforma de la Constitución que afectase al:", "opciones": ["Artículo 5: La capital del Estado es la Villa de Madrid.", "Artículo 11.2: Ningún español de origen podrá ser privado de su nacionalidad.", "Artículo 27.4: La enseñanza básica es obligatoria y gratuita.", "Artículo 57: Orden de sucesión a la Corona."], "bloque": "t1-reforma", "precepto": "Artículo 168.1 CE", "correcta": 1, "justificaciones": ["No. El artículo 5 está en el Título Preliminar: entra en el 168 y el referéndum es obligatorio.", "Es esta. El artículo 11.2 está en el Capítulo I del Título I («De los españoles y los extranjeros»), que no aparece en la lista del 168. Su reforma va por el 167, donde el referéndum es solo facultativo.", "No. El artículo 27 está en la Sección 1.ª del Capítulo II del Título I: entra en el 168.", "No. El artículo 57 está en el Título II: entra en el 168."], "arts": [168], "citas": [{"texto": "«Cuando se propusiere la revisión total de la Constitución o una parcial que afecte al Título preliminar, al Capítulo segundo, Sección primera del Título I, o al Título II, se procederá a la aprobación del principio por mayoría de dos tercios de cada Cámara, y a la disolución inmediata de las Cortes.»", "fuente": "Artículo 168.1 CE"}], "marca": {"nivel": "estrella", "nota": "Reforma ordinaria y agravada: mayorías, referéndum y qué títulos van por el 168. En todas las listas y en el INAP."}, "truco": "Las tres materias blindadas del 168: Título Preliminar + Sección 1.ª del Capítulo II del Título I + Título II. El Capítulo I del Título I (artículos 11 a 13) NO está blindado, aunque esté dentro del Título I."}, {"id": "ce-059", "origen": "oficiales", "test": "INAP feb 2022", "n": 1, "enunciado": "¿La Constitución Española de 1978 (en adelante CE) ha sido reformada?:", "opciones": ["No.", "Sí, en cuatro ocasiones y las cuatro por el procedimiento ordinario.", "Sí, una sola vez y por el procedimiento ordinario.", "Sí, una sola vez y por el procedimiento agravado."], "bloque": "t1-reforma", "precepto": "Artículo 167.1 y 167.2 CE", "correcta": 1, "justificaciones": ["No. Sí ha sido reformada: cuatro veces.", "Es esta. La Constitución se ha reformado cuatro veces: el artículo 13.2 en 1992, el artículo 135 en 2011, el artículo 49 en 2024 y el artículo 69.3 en 2026. Las cuatro, por el procedimiento ordinario del artículo 167.", "No. Ha sido reformada más de una vez.", "No. Ni una sola vez ni por el agravado: el procedimiento del artículo 168 no se ha usado nunca."], "arts": [167], "citas": [{"texto": "«1. Los proyectos de reforma constitucional deberán ser aprobados por una mayoría de tres quintos de cada una de las Cámaras. Si no hubiera acuerdo entre ambas, se intentará obtenerlo mediante la creación de una Comisión de composición paritaria de Diputados y Senadores, que presentará un texto que será votado por el Congreso y el Senado.»«2. De no lograrse la aprobación mediante el procedimiento del apartado anterior, y siempre que el texto hubiere obtenido el voto favorable de la mayoría absoluta del Senado, el Congreso, por mayoría de dos tercios, podrá aprobar la reforma.»", "fuente": "Artículo 167.1 y 167.2 CE"}], "marca": {"nivel": "estrella", "nota": "Reforma ordinaria y agravada: mayorías, referéndum y qué títulos van por el 168. En todas las listas y en el INAP."}, "ojo": "**Opción actualizada.** La plantilla del material decía «dos ocasiones» porque es anterior a la reforma del artículo 49 (BOE de 17 de febrero de 2024). Y luego llegó la del artículo 69.3 (BOE de 20 de mayo de 2026). Aquí la opción correcta se ha puesto al día: hoy son **cuatro** reformas. Si en un test antiguo ves marcada «dos ocasiones», o «tres» en material de 2024 o 2025, ya sabes por qué.", "truco": "Cuatro reformas, cuatro artículos, cuatro años: art. 13.2 en 1992 (Maastricht) · art. 135 en 2011 (estabilidad presupuestaria) · art. 49 en 2024 (personas con discapacidad) · art. 69.3 en 2026 (el senador de Formentera). Las cuatro por el 167."}, {"id": "ce-060", "origen": "otras", "test": "Test exámenes", "n": 22, "enunciado": "La iniciativa de reforma constitucional corresponde, según nuestra normativa constitucional:", "opciones": ["Al Gobierno.", "Al Defensor del Pueblo.", "Al Tribunal Constitucional.", "A los órganos colegiados ejecutivos de las Comunidades Autónomas."], "bloque": "t1-reforma", "precepto": "Artículo 166 CE", "correcta": 0, "justificaciones": ["Es esta. El 166 remite al artículo 87.1 y 2, cuya lista es Gobierno, Congreso, Senado y Asambleas de las Comunidades Autónomas. El Gobierno es el único de las cuatro opciones que está ahí.", "No. El Defensor del Pueblo no tiene iniciativa de reforma; está legitimado para el recurso de inconstitucionalidad y el de amparo (162.1).", "No. El Tribunal Constitucional no tiene iniciativa legislativa de ninguna clase: solo resuelve.", "No. Los «órganos colegiados ejecutivos» de las Comunidades Autónomas aparecen en el 162.1.a) para el recurso de inconstitucionalidad; en la reforma la iniciativa autonómica es de las Asambleas."], "arts": [166], "citas": [{"texto": "«La iniciativa de reforma constitucional se ejercerá en los términos previstos en los apartados 1 y 2 del artículo 87.»", "fuente": "Artículo 166 CE"}], "ojo": "Queda excluida la iniciativa legislativa popular: el 166 remite al 87.1 y 2, nunca al 87.3.", "truco": "En reforma constitucional la iniciativa autonómica la tienen las ASAMBLEAS. En el recurso de inconstitucionalidad la tienen, además, los ÓRGANOS COLEGIADOS EJECUTIVOS. No es lo mismo y el examen lo cruza."}, {"id": "ce-061", "origen": "otras", "test": "Test exámenes", "n": 32, "enunciado": "De acuerdo con el artículo 167.3 de la CE, los proyectos de reforma constitucional aprobados por ambas Cámaras serán sometidos a referéndum para su ratificación:", "opciones": ["En todos los casos.", "Cuando así lo soliciten, dentro de los veinte días siguientes a su aprobación, cincuenta diputados o cincuenta senadores.", "Cuando así lo soliciten, dentro de los quince días siguientes a su aprobación, dos quintos de los miembros de cualquiera de las Cámaras.", "Cuando así lo soliciten, dentro de los quince días siguientes a su aprobación, una décima parte de los miembros de cualquiera de las Cámaras."], "bloque": "t1-reforma", "precepto": "Artículo 167.3 CE", "correcta": 3, "justificaciones": ["No. En el 167 el referéndum es facultativo. Obligatorio solo en el 168.3.", "No. Cambia el plazo a veinte días y el sujeto a cincuenta diputados o senadores, que es la legitimación del recurso de inconstitucionalidad, no esto.", "No. Acierta los quince días, pero cambia la décima parte por dos quintos.", "Es esta. Quince días desde la aprobación y una décima parte de los miembros de cualquiera de las Cámaras."], "arts": [167], "citas": [{"texto": "«Aprobada la reforma por las Cortes Generales, será sometida a referéndum para su ratificación cuando así lo soliciten, dentro de los quince días siguientes a su aprobación, una décima parte de los miembros de cualquiera de las Cámaras.»", "fuente": "Artículo 167.3 CE"}], "marca": {"nivel": "estrella", "nota": "Reforma ordinaria y agravada: mayorías, referéndum y qué títulos van por el 168. En todas las listas y en el INAP."}, "truco": "167 → referéndum FACULTATIVO: lo piden 1/10 de una Cámara en 15 días. 168 → referéndum OBLIGATORIO: siempre, sin que nadie lo pida."}, {"id": "ce-062", "origen": "otras", "test": "Test exámenes", "n": 63, "enunciado": "De conformidad con el artículo 167.1 de la CE, los proyectos de reforma constitucional deberán ser aprobados:", "opciones": ["Por una mayoría de tres quintos de cada una de las Cámaras.", "Por una mayoría de dos tercios de cada una de las Cámaras.", "Por una mayoría simple de cada una de las Cámaras.", "Por una mayoría absoluta de cada una de las Cámaras."], "bloque": "t1-reforma", "precepto": "Artículo 167.1 y 167.2 CE", "correcta": 0, "justificaciones": ["Es esta. Por el procedimiento ordinario, tres quintos de cada una de las Cámaras.", "No. Dos tercios de cada Cámara es la mayoría del 168.1, el procedimiento agravado.", "No. La mayoría simple no interviene en ningún procedimiento de reforma constitucional.", "No. La mayoría absoluta aparece en el 167.2, pero solo referida al Senado y como paso previo a los dos tercios del Congreso."], "arts": [167], "citas": [{"texto": "«1. Los proyectos de reforma constitucional deberán ser aprobados por una mayoría de tres quintos de cada una de las Cámaras. Si no hubiera acuerdo entre ambas, se intentará obtenerlo mediante la creación de una Comisión de composición paritaria de Diputados y Senadores, que presentará un texto que será votado por el Congreso y el Senado.»«2. De no lograrse la aprobación mediante el procedimiento del apartado anterior, y siempre que el texto hubiere obtenido el voto favorable de la mayoría absoluta del Senado, el Congreso, por mayoría de dos tercios, podrá aprobar la reforma.»", "fuente": "Artículo 167.1 y 167.2 CE"}], "marca": {"nivel": "estrella", "nota": "Reforma ordinaria y agravada: mayorías, referéndum y qué títulos van por el 168. En todas las listas y en el INAP."}, "truco": "Las mayorías de la reforma: 167 → 3/5 y 3/5; si falla, comisión paritaria y, con mayoría absoluta del Senado, 2/3 del Congreso. 168 → 2/3 y 2/3, y otra vez 2/3 y 2/3 con las Cámaras nuevas."}, {"id": "ce-063", "origen": "otras", "test": "Test exámenes", "n": 65, "enunciado": "Según el artículo 168.1 de la CE, cuando se propusiere la revisión total de la Constitución, se procederá:", "opciones": ["A la aprobación del principio por mayoría absoluta de cada Cámara, y a la disolución inmediata de las Cortes.", "A la aprobación del principio por mayoría simple de cada Cámara, y a la disolución inmediata de las Cortes.", "A la aprobación del principio por mayoría de dos tercios de cada Cámara, y a la disolución inmediata de las Cortes.", "A la aprobación del principio por mayoría de tres quintos de cada Cámara, y a la disolución inmediata de las Cortes."], "bloque": "t1-reforma", "precepto": "Artículo 168.1 CE", "correcta": 2, "justificaciones": ["No. La mayoría absoluta no interviene en el artículo 168.", "No. La mayoría simple tampoco.", "Es esta. Aprobación del principio por mayoría de dos tercios de cada Cámara y disolución inmediata de las Cortes.", "No. Los tres quintos son la mayoría del 167.1, el procedimiento ordinario."], "arts": [168], "citas": [{"texto": "«Cuando se propusiere la revisión total de la Constitución o una parcial que afecte al Título preliminar, al Capítulo segundo, Sección primera del Título I, o al Título II, se procederá a la aprobación del principio por mayoría de dos tercios de cada Cámara, y a la disolución inmediata de las Cortes.»", "fuente": "Artículo 168.1 CE"}], "marca": {"nivel": "estrella", "nota": "Reforma ordinaria y agravada: mayorías, referéndum y qué títulos van por el 168. En todas las listas y en el INAP."}}, {"id": "ce-064", "origen": "otras", "test": "Test exámenes", "n": 68, "enunciado": "Señale a quién corresponde la iniciativa de la reforma constitucional:", "opciones": ["Al Gobierno y al Congreso.", "Al Congreso y al Senado.", "Al Gobierno, al Congreso y al Senado.", "Al Gobierno, al Congreso, al Senado y a las Asambleas de las Comunidades Autónomas."], "bloque": "t1-reforma", "precepto": "Artículo 166 CE", "correcta": 3, "justificaciones": ["No. Se olvida del Senado y de las Asambleas autonómicas.", "No. Se olvida del Gobierno y de las Asambleas autonómicas.", "No. Se olvida de las Asambleas de las Comunidades Autónomas.", "Es esta. El 166 remite al 87.1 y 2: Gobierno, Congreso, Senado y Asambleas de las Comunidades Autónomas. Los cuatro."], "arts": [166], "citas": [{"texto": "«La iniciativa de reforma constitucional se ejercerá en los términos previstos en los apartados 1 y 2 del artículo 87.»", "fuente": "Artículo 166 CE"}], "truco": "Cuatro sujetos y ni uno más: Gobierno, Congreso, Senado, Asambleas autonómicas. La iniciativa popular queda fuera porque el 166 remite al 87.1 y 87.2, nunca al 87.3."}, {"id": "ce-065", "origen": "otras", "test": "Test exámenes", "n": 72, "enunciado": "Será necesaria la disolución de las Cortes Generales cuando se proponga una reforma de la Constitución que afecte a:", "opciones": ["La propia regulación de las Cortes Generales.", "La distribución competencial recogida en los artículos 148 y 149 de la Constitución.", "La regulación del refrendo de los actos del Rey.", "La regulación de los deberes de los ciudadanos."], "bloque": "t1-reforma", "precepto": "Artículo 168.1 CE", "correcta": 2, "justificaciones": ["No. Las Cortes Generales son el Título III: su reforma va por el 167, sin disolución.", "No. Los artículos 148 y 149 están en el Título VIII: por el 167.", "Es esta. El refrendo de los actos del Rey es el artículo 64, dentro del Título II, y toda reforma que toque el Título II va por el 168, que obliga a la disolución inmediata de las Cortes.", "No. Los deberes de los ciudadanos están en la Sección 2.ª del Capítulo II del Título I: fuera del 168."], "arts": [168], "citas": [{"texto": "«Cuando se propusiere la revisión total de la Constitución o una parcial que afecte al Título preliminar, al Capítulo segundo, Sección primera del Título I, o al Título II, se procederá a la aprobación del principio por mayoría de dos tercios de cada Cámara, y a la disolución inmediata de las Cortes.»", "fuente": "Artículo 168.1 CE"}], "marca": {"nivel": "estrella", "nota": "Reforma ordinaria y agravada: mayorías, referéndum y qué títulos van por el 168. En todas las listas y en el INAP."}, "truco": "Hazte solo esta pregunta: ¿el artículo está en el Título Preliminar, en la Sección 1.ª del Capítulo II del Título I o en el Título II? Si sí → 168 (dos tercios, disolución y referéndum obligatorio). Si no → 167."}, {"id": "ce-066", "origen": "otras", "test": "Test exámenes", "n": 84, "enunciado": "Señale la respuesta correcta en relación con la regulación que recoge el artículo 167 de la Constitución Española sobre reforma constitucional:", "opciones": ["La reforma constitucional, una vez aprobada por las Cortes Generales, será sometida a referéndum para su ratificación cuando así lo soliciten, dentro de los quince días siguientes a su aprobación, una décima parte de los miembros de cualquiera de las Cámaras.", "La reforma constitucional, una vez aprobada por las Cortes Generales, será sometida a referéndum para su ratificación cuando así lo solicite, dentro de los quince días siguientes a su aprobación, una décima parte de los miembros del Congreso de los Diputados.", "La reforma constitucional, una vez aprobada por las Cortes Generales, será sometida a referéndum para su ratificación cuando así lo soliciten, dentro de los veinte días siguientes a su aprobación, una décima parte de los miembros de cualquiera de las Cámaras.", "La reforma constitucional, una vez aprobada por las Cortes Generales, será sometida a referéndum para su ratificación cuando así lo soliciten, dentro de los veinte días siguientes a su aprobación, una décima parte de los miembros del Congreso de los Diputados."], "bloque": "t1-reforma", "precepto": "Artículo 167.3 CE", "correcta": 0, "justificaciones": ["Es esta. Quince días y una décima parte de los miembros de cualquiera de las Cámaras.", "No. Restringe la petición al Congreso; el 167.3 dice «cualquiera de las Cámaras».", "No. Cambia los quince días por veinte.", "No. Falla en las dos cosas a la vez: veinte días y solo el Congreso."], "arts": [167], "citas": [{"texto": "«Aprobada la reforma por las Cortes Generales, será sometida a referéndum para su ratificación cuando así lo soliciten, dentro de los quince días siguientes a su aprobación, una décima parte de los miembros de cualquiera de las Cámaras.»", "fuente": "Artículo 167.3 CE"}], "marca": {"nivel": "estrella", "nota": "Reforma ordinaria y agravada: mayorías, referéndum y qué títulos van por el 168. En todas las listas y en el INAP."}}, {"id": "ce-067", "origen": "otras", "test": "Test exámenes", "n": 90, "enunciado": "Señale la respuesta correcta según lo dispuesto en el artículo 167 de la Constitución Española:", "opciones": ["Los proyectos de reforma constitucional deberán ser aprobados por una mayoría de tres quintos de cada una de las Cámaras.", "Aprobada la reforma por las Cortes Generales será sometida a referéndum para su ratificación cuando así lo soliciten una mayoría de dos tercios de cualquiera de las Cámaras.", "De no lograrse la aprobación por los tres quintos de cada una de las Cámaras, y siempre que el texto hubiere obtenido el voto favorable de los dos tercios de los miembros del Senado, el Congreso podrá aprobar la reforma por mayoría absoluta.", "Los proyectos de reforma constitucional deberán ser aprobados por una mayoría de dos tercios de cada una de las Cámaras."], "bloque": "t1-reforma", "precepto": "Artículo 167.1 y 167.2 CE", "correcta": 0, "justificaciones": ["Es esta. El 167.1 exige mayoría de tres quintos de cada una de las Cámaras.", "No. El referéndum del 167.3 lo pide una décima parte de los miembros de una Cámara, no dos tercios.", "No. Invierte el 167.2: hace falta mayoría absoluta del SENADO y dos tercios del CONGRESO, no lo contrario.", "No. Los dos tercios de cada Cámara son la mayoría del 168.1."], "arts": [167], "citas": [{"texto": "«1. Los proyectos de reforma constitucional deberán ser aprobados por una mayoría de tres quintos de cada una de las Cámaras. Si no hubiera acuerdo entre ambas, se intentará obtenerlo mediante la creación de una Comisión de composición paritaria de Diputados y Senadores, que presentará un texto que será votado por el Congreso y el Senado.»«2. De no lograrse la aprobación mediante el procedimiento del apartado anterior, y siempre que el texto hubiere obtenido el voto favorable de la mayoría absoluta del Senado, el Congreso, por mayoría de dos tercios, podrá aprobar la reforma.»", "fuente": "Artículo 167.1 y 167.2 CE"}], "marca": {"nivel": "estrella", "nota": "Reforma ordinaria y agravada: mayorías, referéndum y qué títulos van por el 168. En todas las listas y en el INAP."}, "truco": "En el 167.2 el Senado va con mayoría ABSOLUTA y el Congreso con DOS TERCIOS. Si la opción los intercambia, es falsa."}, {"id": "ce-068", "origen": "otras", "test": "Test exámenes", "n": 102, "enunciado": "El procedimiento de reforma constitucional previsto en el artículo 168 de la Constitución Española, NO es de aplicación para la reforma del siguiente artículo:", "opciones": ["El artículo 7 relativo a la libertad sindical.", "El artículo 21 relativo al derecho de reunión.", "El artículo 62 relativo a las atribuciones del Rey.", "El artículo 98 relativo al Gobierno."], "bloque": "t1-reforma", "precepto": "Artículo 168.1 CE", "correcta": 3, "justificaciones": ["No. El enunciado lo llama «libertad sindical», pero el artículo 7 trata de los sindicatos y las asociaciones empresariales (la libertad sindical es el 28.1). En todo caso está en el Título Preliminar, así que sí entra en el 168.", "No. El derecho de reunión es el artículo 21, en la Sección 1.ª del Capítulo II del Título I: entra en el 168.", "No. El artículo 62 está en el Título II: entra en el 168.", "Es esta. El artículo 98 está en el Título IV, «Del Gobierno y de la Administración», fuera del ámbito del 168: su reforma va por el 167."], "arts": [168], "citas": [{"texto": "«Cuando se propusiere la revisión total de la Constitución o una parcial que afecte al Título preliminar, al Capítulo segundo, Sección primera del Título I, o al Título II, se procederá a la aprobación del principio por mayoría de dos tercios de cada Cámara, y a la disolución inmediata de las Cortes.»", "fuente": "Artículo 168.1 CE"}], "marca": {"nivel": "estrella", "nota": "Reforma ordinaria y agravada: mayorías, referéndum y qué títulos van por el 168. En todas las listas y en el INAP."}}, {"id": "ce-069", "origen": "otras", "test": "Examen", "n": 6, "enunciado": "¿Cuántas veces se ha reformado la CE desde su aprobación en 1978?", "opciones": ["Una vez, por el procedimiento establecido en el artículo 167.", "Dos veces, una por el procedimiento establecido en el artículo 167 y la otra por el del 168.", "Dos veces, en ambos casos por el procedimiento establecido en el artículo 167.", "Cuatro veces, en los cuatro casos por el procedimiento establecido en el artículo 167."], "bloque": "t1-reforma", "precepto": "Artículo 167.1 y 167.2 CE", "correcta": 3, "justificaciones": ["No. Una sola vez se queda corta, y además solo menciona el 167 para una de las cuatro.", "No. Falla dos veces: son cuatro, no dos, y ninguna ha ido por el 168.", "No. Era la respuesta del material y fue cierta hasta febrero de 2024; con la reforma del artículo 49 pasaron a tres y, desde mayo de 2026, son cuatro.", "Es esta. Cuatro reformas y las cuatro por el artículo 167: el artículo 13.2 en 1992 (sufragio pasivo de los extranjeros en las municipales, por el Tratado de Maastricht), el artículo 135 en 2011 (estabilidad presupuestaria), el artículo 49 en 2024 (personas con discapacidad) y el artículo 69.3 en 2026 (circunscripción propia al Senado para Formentera)."], "arts": [167], "citas": [{"texto": "«1. Los proyectos de reforma constitucional deberán ser aprobados por una mayoría de tres quintos de cada una de las Cámaras. Si no hubiera acuerdo entre ambas, se intentará obtenerlo mediante la creación de una Comisión de composición paritaria de Diputados y Senadores, que presentará un texto que será votado por el Congreso y el Senado.»«2. De no lograrse la aprobación mediante el procedimiento del apartado anterior, y siempre que el texto hubiere obtenido el voto favorable de la mayoría absoluta del Senado, el Congreso, por mayoría de dos tercios, podrá aprobar la reforma.»", "fuente": "Artículo 167.1 y 167.2 CE"}], "marca": {"nivel": "estrella", "nota": "Reforma ordinaria y agravada: mayorías, referéndum y qué títulos van por el 168. En todas las listas y en el INAP."}, "ojo": "**Opción actualizada.** El material marcaba la de «dos veces» porque es anterior a la reforma del artículo 49 (BOE de 17 de febrero de 2024). Aquí se ha reescrito la opción d), que atribuía una reforma al 168, y ahora dice «cuatro veces»: esa es hoy la correcta, tras la reforma del artículo 69.3 (BOE de 20 de mayo de 2026). La de «dos veces, ambas por el 167» se queda como distractor: fue verdad hasta 2024.", "truco": "El 168 NUNCA se ha usado. Cualquier opción que atribuya una reforma al 168 es falsa, diga el número que diga."}, {"id": "ce-070", "origen": "otras", "test": "Test 2", "n": 19, "enunciado": "Se pretende reformar el artículo de la Constitución Española (en adelante CE) referido al derecho a la propiedad privada y a la herencia. Señale la respuesta correcta en relación con el procedimiento de reforma del citado artículo:", "opciones": ["La reforma por iniciativa legislativa popular requerirá al menos 500.000 firmas acreditadas.", "Se procederá a la aprobación del principio de reforma por mayoría de dos tercios de cada Cámara y a la disolución inmediata de las Cortes.", "Una vez disueltas las Cortes, las Cámaras deberán ratificar la decisión y proceder al estudio del nuevo Texto Constitucional, que deberá ser aprobado por mayoría de tres quintos de ambas Cámaras.", "Aprobada la reforma por las Cortes Generales, será sometida a referéndum para su ratificación cuando así lo soliciten, dentro de los quince días siguientes a su aprobación, una décima parte de los miembros de cualquiera de las Cámaras."], "bloque": "t1-reforma", "precepto": "Artículo 167.3 CE", "correcta": 3, "justificaciones": ["No. La iniciativa legislativa popular está excluida de la reforma constitucional: el 166 remite al 87.1 y 2, dejando fuera el 87.3.", "No. Describe el 168.1, que no se aplica al artículo 33.", "No. Describe el 168.2 y además cambia los dos tercios por tres quintos.", "Es esta. La propiedad privada y la herencia son el artículo 33, en la Sección 2.ª del Capítulo II: fuera del 168, así que la reforma va por el 167 y el referéndum es facultativo, a petición de una décima parte de una Cámara en quince días."], "arts": [167], "citas": [{"texto": "«Aprobada la reforma por las Cortes Generales, será sometida a referéndum para su ratificación cuando así lo soliciten, dentro de los quince días siguientes a su aprobación, una décima parte de los miembros de cualquiera de las Cámaras.»", "fuente": "Artículo 167.3 CE"}], "marca": {"nivel": "estrella", "nota": "Reforma ordinaria y agravada: mayorías, referéndum y qué títulos van por el 168. En todas las listas y en el INAP."}, "truco": "El artículo 33 está en la Sección 2.ª, no en la 1.ª. Propiedad y herencia no están blindadas: se reforman por el procedimiento ordinario."}, {"id": "ce-153", "origen": "oficiales", "test": "INAP mayo 2026", "n": 1, "enunciado": "De acuerdo con el artículo 167 de la Constitución Española de 1978, los proyectos de reforma constitucional deberán ser aprobados:", "opciones": ["Por mayoría de tres quintos del Congreso.", "Por mayoría absoluta del Congreso.", "Por mayoría absoluta de cada una de las Cámaras.", "Por mayoría de tres quintos de cada una de las Cámaras."], "bloque": "t1-reforma", "precepto": "Artículo 167.1 CE", "correcta": 3, "justificaciones": ["No. Se queda a medias: los tres quintos son correctos, pero se exigen en cada Cámara, no solo en el Congreso.", "No. La mayoría absoluta que aparece en el 167.2 es la del **Senado**, y va acompañada de dos tercios del Congreso. Sola nunca basta.", "No. Cambia el quórum: el procedimiento ordinario pide tres quintos, no mayoría absoluta.", "Es esta. Tres quintos, y en las dos Cámaras. La mayoría no se mide en el Congreso y luego «se ve» en el Senado: el 167.1 la exige en cada una por separado."], "arts": [167], "citas": [{"texto": "«Los proyectos de reforma constitucional deberán ser aprobados por una mayoría de tres quintos de cada una de las Cámaras.»", "fuente": "Artículo 167.1 CE"}], "marca": {"nivel": "estrella", "nota": "Reforma ordinaria y agravada: mayorías, referéndum y qué títulos van por el 168. En todas las listas y en el INAP."}, "truco": "167 (ordinaria): 3/5 y 3/5; si no hay acuerdo, comisión paritaria y, en última instancia, 2/3 del Congreso con mayoría absoluta del Senado. 168 (agravada): 2/3, disolución, elecciones, 2/3 otra vez y referéndum obligatorio."}, {"id": "ce-258", "origen": "otras", "test": "Test exámenes", "n": 165, "enunciado": "Se pretende reformar el artículo de la Constitución Española (en adelante CE) referido al derecho a la propiedad privada y a la herencia. Señale la respuesta correcta en relación con el procedimiento de reforma del citado artículo:", "opciones": ["La reforma por iniciativa legislativa popular requerirá al menos 500.000 firmas acreditadas.", "Se procederá a la aprobación del principio de reforma por mayoría de dos tercios de cada Cámara y a la disolución inmediata de las Cortes.", "Una vez disueltas las Cortes, las Cámaras deberán ratificar la decisión y proceder al estudio del nuevo Texto Constitucional, que deberá ser aprobado por mayoría de tres quintos de ambas Cámaras.", "Aprobada la reforma por las Cortes Generales, será sometida a referéndum para su ratificación cuando así lo soliciten, dentro de los quince días siguientes a su aprobación, una décima parte de los miembros de cualquiera de las Cámaras."], "bloque": "t1-reforma", "precepto": "Artículo 167.3 CE", "correcta": 3, "justificaciones": ["No. Las 500.000 firmas son de la iniciativa legislativa popular de leyes ordinarias (87.3); además, la iniciativa de reforma constitucional (166) remite solo al artículo 87.1 y 2, sin incluir la vía popular.", "No. La aprobación por dos tercios y la disolución inmediata de las Cortes son del procedimiento AGRAVADO del artículo 168, reservado a materias que aquí no están en juego.", "No. Ese estudio posterior a la disolución, con mayoría de tres quintos de ambas Cámaras, también es del procedimiento agravado del 168, no del ordinario que corresponde al artículo 33.", "Es esta. El derecho a la propiedad privada y a la herencia es el artículo 33, situado en la Sección 2.ª del Capítulo II del Título I: no está entre las materias blindadas del artículo 168 (Título Preliminar, Sección 1.ª del Capítulo II del Título I y Título II), así que su reforma sigue el procedimiento ORDINARIO del artículo 167, con referéndum solo facultativo."], "arts": [167], "citas": [{"texto": "«Aprobada la reforma por las Cortes Generales, será sometida a referéndum para su ratificación cuando así lo soliciten, dentro de los quince días siguientes a su aprobación, una décima parte de los miembros de cualquiera de las Cámaras.»", "fuente": "Artículo 167.3 CE"}], "marca": {"nivel": "estrella", "nota": "Reforma ordinaria y agravada: mayorías, referéndum y qué títulos van por el 168. En todas las listas y en el INAP."}}, {"id": "ce-129", "origen": "otras", "test": "Test exámenes", "n": 5, "enunciado": "Respecto del Defensor del Pueblo, responda la alternativa correcta:", "opciones": ["Será elegido por el Congreso de los Diputados para un periodo de 4 años.", "Será elegido por las Cortes Generales para un período de 4 años.", "Será elegido por las Cortes Generales para un período de 5 años.", "Será elegido por el Congreso de los Diputados para un período de 5 años."], "bloque": "t1-defensor", "precepto": "Artículo segundo, apartado Uno · LO 3/1981", "correcta": 2, "justificaciones": ["No. Cambia las dos cosas: el órgano (el Congreso en lugar de las Cortes) y el plazo (cuatro años).", "No. Acierta el órgano, pero da cuatro años en lugar de cinco.", "Es esta. El artículo segundo, apartado Uno, es tajante: lo eligen las Cortes Generales (Congreso y Senado) y por un periodo de cinco años.", "No. Acierta el plazo, pero atribuye la elección solo al Congreso: hace falta también la ratificación del Senado (art. 2, Cuatro)."], "arts": [], "citas": [{"texto": "«El Defensor del Pueblo será elegido por las Cortes Generales para un periodo de cinco años, y se dirigirá a las mismas a través de los Presidentes del Congreso y del Senado, respectivamente.»", "fuente": "Artículo segundo, apartado Uno · LO 3/1981"}], "truco": "Cinco años, y no coinciden con la legislatura, que son cuatro. Ese desajuste es deliberado: busca que el Defensor no dependa de la mayoría que lo eligió."}, {"id": "ce-130", "origen": "otras", "test": "Test exámenes", "n": 8, "enunciado": "El Defensor del Pueblo, en sus funciones, está auxiliado:", "opciones": ["Por 3 Adjuntos, a los cuales nombrará y separará previa conformidad de las Cámaras, en la forma que determinen sus Reglamentos.", "Por 3 Adjuntos, a los cuales nombrará y separará previa conformidad del Gobierno, en la forma que determine su Reglamento.", "Por 2 Adjuntos, a los cuales nombrará y separará previa conformidad de las Cámaras, en la forma que determinen sus Reglamentos.", "Por 2 Adjuntos, a los cuales nombrará y separará previa conformidad del Gobierno, en la forma que determine su Reglamento."], "bloque": "t1-defensor", "precepto": "Artículo octavo · LO 3/1981", "correcta": 2, "justificaciones": ["No. Son dos Adjuntos, no tres.", "No. Falla dos veces: son dos y la conformidad es de las Cámaras, no del Gobierno.", "Es esta. El artículo octavo habla de un Adjunto Primero y un Adjunto Segundo (dos) y de que los nombra y separa el propio Defensor previa conformidad de las Cámaras.", "No. Acierta el número, pero la conformidad es de las Cámaras, no del Gobierno."], "arts": [], "citas": [{"texto": "«Uno. El Defensor del Pueblo estará auxiliado por un Adjunto Primero y un Adjunto Segundo, en los que podrá delegar sus funciones y que le sustituirán por su orden, en el ejercicio de las mismas, en los supuestos de imposibilidad temporal y en los de cese.»«Dos. El Defensor del Pueblo nombrará y separará a sus Adjuntos previa conformidad de las Cámaras en la forma que determinen sus Reglamentos.» · «Tres. El nombramiento de los Adjuntos será publicado en el «Boletín Oficial del Estado».»", "fuente": "Artículo octavo · LO 3/1981"}], "truco": "Dos Adjuntos, y la conformidad siempre de las CÁMARAS. El Gobierno no interviene nunca en el Defensor del Pueblo: es un comisionado de las Cortes, no del ejecutivo."}, {"id": "ce-131", "origen": "otras", "test": "Test exámenes", "n": 21, "enunciado": "Señale la afirmación correcta en relación con el Defensor del Pueblo:", "opciones": ["Estará sujeto a condición resolutoria.", "No estará sujeto a mandato imperativo alguno.", "Desempeñará sus funciones siguiendo el criterio que le marquen las Cámaras.", "Tiene poder para anular resoluciones y actos."], "bloque": "t1-defensor", "precepto": "Artículo sexto, apartado Uno · LO 3/1981; Artículos veintiocho y treinta · LO 3/1981", "correcta": 1, "justificaciones": ["No. La «condición resolutoria» no existe en esta ley: el cese tiene cinco causas tasadas (art. 5, Uno).", "Es esta. Literal del artículo sexto, apartado Uno: no está sujeto a mandato imperativo alguno.", "No. Es justo lo contrario de lo que dice el precepto: no recibe instrucciones de ninguna autoridad y actúa según su criterio.", "No. No puede anular ni modificar actos (art. 28, Uno): solo sugerir, advertir, recomendar y recordar deberes legales."], "arts": [], "citas": [{"texto": "«El Defensor del Pueblo no estará sujeto a mandato imperativo alguno. No recibirá instrucciones de ninguna Autoridad. Desempeñará sus funciones con autonomía y según su criterio.»", "fuente": "Artículo sexto, apartado Uno · LO 3/1981"}, {"texto": "«Veintiocho. Uno. El Defensor del Pueblo, aun no siendo competente para modificar o anular los actos y resoluciones de la Administración Pública, podrá, sin embargo, sugerir la modificación de los criterios utilizados para la producción de aquéllos.»«Treinta. Uno. El Defensor del Pueblo, con ocasión de sus investigaciones, podrá formular a las autoridades y funcionarios de las Administraciones Públicas advertencias, recomendaciones, recordatorios de sus deberes legales y sugerencias para la adopción de nuevas medidas. En todos los casos, las autoridades y los funcionarios vendrán obligados a responder por escrito en término no superior al de un mes.»", "fuente": "Artículos veintiocho y treinta · LO 3/1981"}], "truco": "Tres frases seguidas en el artículo sexto: sin mandato imperativo · sin instrucciones de ninguna autoridad · con autonomía y según su criterio. Independencia en estado puro."}, {"id": "ce-132", "origen": "otras", "test": "Test exámenes", "n": 34, "enunciado": "De acuerdo con la Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo, las quejas ante esta institución deberán presentarse en el plazo de:", "opciones": ["Seis meses contados a partir del momento en que el interesado tuviera conocimiento de los hechos objeto de la queja.", "Un año contado a partir del momento en que el interesado tuviera conocimiento de los hechos objeto de la queja.", "Un año contado a partir del momento en que se produzcan los hechos objeto de la queja.", "Seis meses contados a partir del momento en que se produzcan los hechos objeto de la queja."], "bloque": "t1-defensor", "precepto": "Artículo quince, apartado Uno · LO 3/1981", "correcta": 1, "justificaciones": ["No. Los seis meses no aparecen en la ley.", "Es esta. Un año, contado desde el momento en que el interesado tuvo conocimiento de los hechos.", "No. Acierta el plazo, pero cambia el punto de partida: cuenta desde el conocimiento, no desde que los hechos se produjeron.", "No. Falla en las dos cosas a la vez: el plazo y el punto de partida."], "arts": [], "citas": [{"texto": "«Toda queja se presentará firmada por el interesado, con indicación de su nombre, apellidos y domicilio, en escrito razonado en papel común y en el plazo máximo de un año, contado a partir del momento en que tuviera conocimiento de los hechos objeto de la misma.»", "fuente": "Artículo quince, apartado Uno · LO 3/1981"}], "ojo": "Cuenta desde el conocimiento, no desde que los hechos ocurrieron. Las opciones que cambian ese punto de partida son falsas.", "truco": "Los requisitos de la queja, en una línea: firmada, con nombre, apellidos y domicilio, razonada, en papel común y dentro de un año desde el conocimiento. Y todo gratis, sin abogado ni procurador (art. 15, Dos)."}, {"id": "ce-133", "origen": "otras", "test": "Test exámenes", "n": 38, "enunciado": "Según el artículo 54 de la CE, el Defensor del Pueblo desempeña la defensa de los derechos del Título I como alto comisionado de:", "opciones": ["El Gobierno.", "El Tribunal Constitucional.", "La Corona.", "Las Cortes Generales."], "bloque": "t1-defensor", "precepto": "Artículo 54 CE", "correcta": 3, "justificaciones": ["No. El Gobierno no es su comisionante: forma parte de lo que el Defensor supervisa.", "No. El Tribunal Constitucional no lo designa ni recibe sus informes.", "No. La Corona no interviene: al Defensor del Pueblo no lo nombra el Rey.", "Es esta. El artículo 54 lo define literalmente como «alto comisionado de las Cortes Generales»."], "arts": [54], "citas": [{"texto": "«Una ley orgánica regulará la institución del Defensor del Pueblo, como alto comisionado de las Cortes Generales, designado por éstas para la defensa de los derechos comprendidos en este Título, a cuyo efecto podrá supervisar la actividad de la Administración, dando cuenta a las Cortes Generales.»", "fuente": "Artículo 54 CE"}], "marca": {"nivel": "clave", "nota": "El Defensor del Pueblo en la Constitución: alto comisionado de las Cortes, por ley orgánica."}, "truco": "«Alto comisionado de las Cortes Generales». La palabra es COMISIONADO y el titular son las CORTES (las dos Cámaras), no el Congreso a solas."}, {"id": "ce-134", "origen": "otras", "test": "Test exámenes", "n": 45, "enunciado": "Según la Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo, es requisito necesario para ser nombrado Defensor del Pueblo:", "opciones": ["Ser español, mayor de edad, con residencia en España en los 2 años inmediatamente anteriores al nombramiento.", "Ser español, mayor de edad, con derechos de sufragio activo y pasivo y no haber sido inhabilitado para el ejercicio del cargo por las Cortes Generales.", "Ser español, mayor de edad, en pleno disfrute de los derechos civiles y políticos.", "Ser nacional de un Estado Miembro de la Unión Europea, con residencia en España en los 2 años inmediatamente anteriores al nombramiento."], "bloque": "t1-defensor", "precepto": "Artículo tercero · LO 3/1981", "correcta": 2, "justificaciones": ["No. La ley no exige ningún periodo de residencia previa en España.", "No. No habla de sufragio activo y pasivo ni de inhabilitación por las Cortes, sino de «pleno disfrute de sus derechos civiles y políticos».", "Es esta. Literal del artículo tercero: cualquier español mayor de edad en el pleno disfrute de sus derechos civiles y políticos.", "No. Hay que ser español; no basta con ser nacional de otro Estado miembro de la Unión Europea."], "arts": [], "citas": [{"texto": "«Podrá ser elegido Defensor del Pueblo cualquier español mayor de edad que se encuentre en el pleno disfrute de sus derechos civiles y políticos.»", "fuente": "Artículo tercero · LO 3/1981"}], "truco": "Dos requisitos y solo dos: español y mayor de edad, en pleno disfrute de sus derechos civiles y políticos. Ni titulación, ni experiencia, ni residencia, ni edad mínima superior."}, {"id": "ce-135", "origen": "otras", "test": "Test exámenes", "n": 46, "enunciado": "De acuerdo con la Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo, es elegido por las Cortes Generales para un periodo máximo de:", "opciones": ["5 años.", "4 años.", "24 meses.", "10 años."], "bloque": "t1-defensor", "precepto": "Artículo segundo, apartado Uno · LO 3/1981", "correcta": 0, "justificaciones": ["Es esta. Cinco años, según el artículo segundo, apartado Uno.", "No. Cuatro años es la duración de la legislatura, no del mandato del Defensor del Pueblo.", "No. Veinticuatro meses son dos años: no aparece en la ley.", "No. Diez años tampoco aparece en ningún precepto."], "arts": [], "citas": [{"texto": "«El Defensor del Pueblo será elegido por las Cortes Generales para un periodo de cinco años, y se dirigirá a las mismas a través de los Presidentes del Congreso y del Senado, respectivamente.»", "fuente": "Artículo segundo, apartado Uno · LO 3/1981"}], "truco": "Tres cifras que conviene no cruzar: cinco años el Defensor del Pueblo · nueve el magistrado del Tribunal Constitucional · tres el Presidente del Tribunal Constitucional."}, {"id": "ce-136", "origen": "otras", "test": "Test exámenes", "n": 56, "enunciado": "Las resoluciones del Defensor del Pueblo, según la Ley Orgánica 3/1981, de 6 de abril:", "opciones": ["Pueden modificar o anular los actos y resoluciones de la Administración Pública.", "Pueden declarar la nulidad o inaplicabilidad de una disposición legal.", "Pueden declarar la caducidad de un procedimiento administrativo.", "Pueden formular advertencias, recomendaciones o recordatorios a la Administración Pública."], "bloque": "t1-defensor", "precepto": "Artículos veintiocho y treinta · LO 3/1981", "correcta": 3, "justificaciones": ["No. El artículo veintiocho, Uno, lo dice expresamente: no es competente para modificar ni anular actos y resoluciones de la Administración.", "No. No puede declarar la nulidad ni la inaplicabilidad de una norma. Para eso está legitimado para recurrir ante el Tribunal Constitucional (art. 29).", "No. La caducidad de un procedimiento administrativo la declara la propia Administración, no el Defensor del Pueblo.", "Es esta. Literal del artículo treinta, apartado Uno: advertencias, recomendaciones, recordatorios de deberes legales y sugerencias."], "arts": [], "citas": [{"texto": "«Veintiocho. Uno. El Defensor del Pueblo, aun no siendo competente para modificar o anular los actos y resoluciones de la Administración Pública, podrá, sin embargo, sugerir la modificación de los criterios utilizados para la producción de aquéllos.»«Treinta. Uno. El Defensor del Pueblo, con ocasión de sus investigaciones, podrá formular a las autoridades y funcionarios de las Administraciones Públicas advertencias, recomendaciones, recordatorios de sus deberes legales y sugerencias para la adopción de nuevas medidas. En todos los casos, las autoridades y los funcionarios vendrán obligados a responder por escrito en término no superior al de un mes.»", "fuente": "Artículos veintiocho y treinta · LO 3/1981"}], "truco": "La fuerza del Defensor del Pueblo es PERSUASIVA, no ejecutiva. Sus armas reales son la obligación de responderle por escrito en un mes, el informe anual a las Cortes y la publicidad; y, en su caso, el recurso de inconstitucionalidad o de amparo."}, {"id": "ce-137", "origen": "otras", "test": "Test exámenes", "n": 62, "enunciado": "Según el artículo 54 de la CE, el Defensor del Pueblo podrá supervisar la actividad de la Administración dando cuenta:", "opciones": ["A las Cortes Generales.", "Al Congreso de los diputados.", "Al Gobierno.", "Al Tribunal Constitucional."], "bloque": "t1-defensor", "precepto": "Artículo 54 CE", "correcta": 0, "justificaciones": ["Es esta. El artículo 54 cierra diciendo «dando cuenta a las Cortes Generales».", "No. No solo al Congreso: son las Cortes Generales, es decir, las dos Cámaras.", "No. El Gobierno es a quien supervisa, no a quien da cuenta.", "No. El Tribunal Constitucional no recibe sus informes."], "arts": [54], "citas": [{"texto": "«Una ley orgánica regulará la institución del Defensor del Pueblo, como alto comisionado de las Cortes Generales, designado por éstas para la defensa de los derechos comprendidos en este Título, a cuyo efecto podrá supervisar la actividad de la Administración, dando cuenta a las Cortes Generales.»", "fuente": "Artículo 54 CE"}], "marca": {"nivel": "clave", "nota": "El Defensor del Pueblo en la Constitución: alto comisionado de las Cortes, por ley orgánica."}}, {"id": "ce-138", "origen": "otras", "test": "Test exámenes", "n": 81, "enunciado": "Según la Ley Orgánica 3/81, de 6 de abril, del Defensor del Pueblo:", "opciones": ["Podrán ser hasta tres los Adjuntos que auxilien al Defensor del Pueblo en el ejercicio de sus funciones.", "El nombramiento de los Adjuntos será publicado en el Diario Oficial del Defensor del Pueblo.", "El Defensor del Pueblo podrá delegar sus funciones en los Adjuntos.", "No cabe la delegación de funciones en los Adjuntos sino tan solo la sustitución en los supuestos de imposibilidad temporal y de cese."], "bloque": "t1-defensor", "precepto": "Artículo octavo · LO 3/1981", "correcta": 2, "justificaciones": ["No. Son dos Adjuntos, el Primero y el Segundo, no hasta tres.", "No. Su nombramiento se publica en el «Boletín Oficial del Estado» (art. 8, Tres). No existe ningún «Diario Oficial del Defensor del Pueblo».", "Es esta. El artículo octavo, apartado Uno, dice literalmente «en los que podrá delegar sus funciones»: la delegación está expresamente prevista.", "No. Es falsa: el precepto prevé la delegación además de la sustitución. No son alternativas."], "arts": [], "citas": [{"texto": "«Uno. El Defensor del Pueblo estará auxiliado por un Adjunto Primero y un Adjunto Segundo, en los que podrá delegar sus funciones y que le sustituirán por su orden, en el ejercicio de las mismas, en los supuestos de imposibilidad temporal y en los de cese.»«Dos. El Defensor del Pueblo nombrará y separará a sus Adjuntos previa conformidad de las Cámaras en la forma que determinen sus Reglamentos.» · «Tres. El nombramiento de los Adjuntos será publicado en el «Boletín Oficial del Estado».»", "fuente": "Artículo octavo · LO 3/1981"}], "truco": "El artículo octavo en cuatro datos: dos Adjuntos · puede delegar en ellos · le sustituyen por su orden · el nombramiento va al BOE. Y les alcanza el régimen de los artículos tercero, sexto y séptimo."}, {"id": "ce-139", "origen": "otras", "test": "Test exámenes", "n": 86, "enunciado": "Según Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo:", "opciones": ["El Defensor del Pueblo cesa exclusivamente por renuncia, expiración de su mandato y fallecimiento.", "El Defensor del Pueblo puede concluir su acción investigadora con la emisión de una advertencia.", "El Defensor del Pueblo puede recibir quejas que las autoridades administrativas presenten en asuntos de su competencia.", "Los poderes públicos pueden negarse a auxiliar con carácter preferente y urgente al Defensor del Pueblo en sus investigaciones."], "bloque": "t1-defensor", "precepto": "Artículos veintiocho y treinta · LO 3/1981", "correcta": 1, "justificaciones": ["No. Las causas de cese son cinco, no tres: renuncia, expiración del plazo, muerte o incapacidad sobrevenida, notoria negligencia y condena firme por delito doloso (art. 5, Uno).", "Es esta. El artículo treinta, apartado Uno, incluye la advertencia entre las resoluciones con las que puede concluir su actuación.", "No. El artículo diez, Tres, lo prohíbe: ninguna autoridad administrativa puede presentar quejas en asuntos de su competencia.", "No. El artículo diecinueve, Uno, obliga a todos los poderes públicos a auxiliarle «con carácter preferente y urgente»."], "arts": [], "citas": [{"texto": "«Veintiocho. Uno. El Defensor del Pueblo, aun no siendo competente para modificar o anular los actos y resoluciones de la Administración Pública, podrá, sin embargo, sugerir la modificación de los criterios utilizados para la producción de aquéllos.»«Treinta. Uno. El Defensor del Pueblo, con ocasión de sus investigaciones, podrá formular a las autoridades y funcionarios de las Administraciones Públicas advertencias, recomendaciones, recordatorios de sus deberes legales y sugerencias para la adopción de nuevas medidas. En todos los casos, las autoridades y los funcionarios vendrán obligados a responder por escrito en término no superior al de un mes.»", "fuente": "Artículos veintiocho y treinta · LO 3/1981"}], "truco": "Las cinco causas de cese, en el orden del artículo quinto: renuncia · expiración del plazo · muerte o incapacidad sobrevenida · notoria negligencia · condena firme por delito doloso."}, {"id": "ce-140", "origen": "otras", "test": "Test exámenes", "n": 92, "enunciado": "Señale la respuesta correcta en relación con el procedimiento de nombramiento del Defensor del Pueblo regulado en la Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo:", "opciones": ["Propuesto el candidato o candidatos por la Comisión Mixta Congreso-Senado, se convocará en término no inferior a veinte días al Pleno del Congreso para que proceda a su elección.", "Resultará designado Defensor del Pueblo quien obtuviese una votación favorable de las tres quintas partes de los miembros del Congreso e idéntica mayoría de los miembros del Senado.", "Resultará designado Defensor del Pueblo quien obtuviese una votación favorable de las tres cuartas partes de los miembros del Congreso y, posteriormente, en el plazo máximo de veinte días, fuese ratificado por la mayoría absoluta de los miembros del Senado.", "En el caso de no alcanzar en una primera instancia las mayorías exigidas por la Ley Orgánica, se procederá a formular sucesivas propuestas en el plazo máximo de quince días. En este caso, quedará designado el candidato que alcance la votación favorable de los dos tercios del Congreso y la mayoría absoluta del Senado."], "bloque": "t1-defensor", "precepto": "Artículo segundo, apartados Cuatro y Cinco · LO 3/1981", "correcta": 1, "justificaciones": ["No. El plazo de convocatoria del Pleno del Congreso es «en término no inferior a diez días», no a veinte.", "Es esta. El apartado Cuatro es exactamente eso: tres quintas partes de los miembros del Congreso y ratificación del Senado por esa misma mayoría.", "No. Cambia los tres quintos del Congreso por tres cuartos, y adelanta al primer intento la mayoría absoluta del Senado, que solo cabe en el segundo (apartado Cinco).", "No. En el segundo intento el plazo es de un mes, no de quince días, y basta con tres quintos en el Congreso y mayoría absoluta en el Senado, no dos tercios."], "arts": [], "citas": [{"texto": "«Cuatro. Propuesto el candidato o candidatos, se convocará en término no inferior a diez días al Pleno del Congreso para que proceda a su elección. Será designado quien obtuviese una votación favorable de las tres quintas partes de los miembros del Congreso y posteriormente, en un plazo máximo de veinte días, fuese ratificado por esta misma mayoría del Senado.»«Cinco. Caso de no alcanzarse las mencionadas mayorías, se procederá en nueva sesión de la Comisión, y en el plazo máximo de un mes, a formular sucesivas propuestas. En tales casos, una vez conseguida la mayoría de los tres quintos en el Congreso, la designación quedará realizada al alcanzarse la mayoría absoluta del Senado.»", "fuente": "Artículo segundo, apartados Cuatro y Cinco · LO 3/1981"}], "truco": "Dos rondas. Primera: 3/5 y 3/5. Segunda: 3/5 en el Congreso y basta MAYORÍA ABSOLUTA en el Senado. El que se relaja es siempre el Senado, nunca el Congreso."}, {"id": "ce-141", "origen": "otras", "test": "Test exámenes", "n": 97, "enunciado": "De conformidad con el artículo 2.4 de la Ley Orgánica 3/1981 de 6 de abril, del Defensor del Pueblo, para su designación se precisa una votación favorable de:", "opciones": ["Tres quintos en el Congreso y ratificación posterior en el Senado por la misma mayoría.", "Mayoría simple en el Congreso y mayoría simple en el Senado.", "Dos quintos en el Congreso y dos quintos en el Senado.", "Mayoría simple en el Congreso y ratificación posterior en el Senado por mayoría absoluta."], "bloque": "t1-defensor", "precepto": "Artículo segundo, apartados Cuatro y Cinco · LO 3/1981", "correcta": 0, "justificaciones": ["Es esta. Tres quintos del Congreso y, en un plazo máximo de veinte días, ratificación del Senado por esa misma mayoría.", "No. La mayoría simple no basta en ninguna de las dos Cámaras.", "No. «Dos quintos» no aparece en la ley.", "No. La mayoría absoluta del Senado solo entra en juego en el segundo intento (apartado Cinco), y siempre acompañada de tres quintos en el Congreso."], "arts": [], "citas": [{"texto": "«Cuatro. Propuesto el candidato o candidatos, se convocará en término no inferior a diez días al Pleno del Congreso para que proceda a su elección. Será designado quien obtuviese una votación favorable de las tres quintas partes de los miembros del Congreso y posteriormente, en un plazo máximo de veinte días, fuese ratificado por esta misma mayoría del Senado.»«Cinco. Caso de no alcanzarse las mencionadas mayorías, se procederá en nueva sesión de la Comisión, y en el plazo máximo de un mes, a formular sucesivas propuestas. En tales casos, una vez conseguida la mayoría de los tres quintos en el Congreso, la designación quedará realizada al alcanzarse la mayoría absoluta del Senado.»", "fuente": "Artículo segundo, apartados Cuatro y Cinco · LO 3/1981"}]}, {"id": "ce-142", "origen": "otras", "test": "Test exámenes", "n": 98, "enunciado": "Según el artículo 10 de la Ley Orgánica 3/1981, pueden dirigirse al Defensor del Pueblo:", "opciones": ["Las personas naturales si son mayores de edad, pero no las personas jurídicas.", "Las personas naturales si son mayores de edad y tienen nacionalidad española, pero no las personas jurídicas.", "Las personas naturales en cualquier caso, y las jurídicas si tienen nacionalidad española.", "Las personas naturales o jurídicas, independientemente de su nacionalidad o edad."], "bloque": "t1-defensor", "precepto": "Artículo diez, apartado Uno · LO 3/1981", "correcta": 3, "justificaciones": ["No. Las personas jurídicas sí pueden, y la minoría de edad no es impedimento.", "No. Añade dos límites que la ley niega de forma expresa: la nacionalidad y la exclusión de las personas jurídicas.", "No. La ley no exige nacionalidad española a las personas jurídicas.", "Es esta. El artículo diez, apartado Uno, dice «toda persona natural o jurídica que invoque un interés legítimo, sin restricción alguna», y niega expresamente que la nacionalidad o la minoría de edad sean impedimento."], "arts": [], "citas": [{"texto": "«Podrá dirigirse al Defensor del Pueblo toda persona natural o jurídica que invoque un interés legítimo, sin restricción alguna. No podrán constituir impedimento para ello la nacionalidad, residencia, sexo, minoría de edad, la incapacidad legal del sujeto, el internamiento en un centro penitenciario o de reclusión o, en general, cualquier relación especial de sujeción o dependencia de una Administración o Poder público.»", "fuente": "Artículo diez, apartado Uno · LO 3/1981"}], "truco": "El artículo diez enumera lo que NO es impedimento: nacionalidad, residencia, sexo, minoría de edad, incapacidad legal, internamiento en un centro penitenciario o cualquier relación de sujeción. La puerta está abierta del todo."}, {"id": "ce-143", "origen": "otras", "test": "Test exámenes", "n": 104, "enunciado": "De conformidad con la Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo, toda queja al Defensor del Pueblo se presentará en el plazo máximo de:", "opciones": ["Tres meses, contados a partir del momento en que tuviera conocimiento de los hechos objeto de la misma.", "Seis meses, contados a partir del momento en que tuviera conocimiento de los hechos objeto de la misma.", "Un año, contado a partir del momento en que tuviera conocimiento de los hechos objeto de la misma.", "Dos años, contados a partir del momento en que tuviera conocimiento de los hechos objeto de la misma."], "bloque": "t1-defensor", "precepto": "Artículo quince, apartado Uno · LO 3/1981", "correcta": 2, "justificaciones": ["No. Tres meses es el plazo del recurso de inconstitucionalidad (art. 33.1 LOTC), no de la queja.", "No. Seis meses no aparece en la ley.", "Es esta. Un año contado desde el momento en que el interesado tuvo conocimiento de los hechos.", "No. Dos años tampoco."], "arts": [], "citas": [{"texto": "«Toda queja se presentará firmada por el interesado, con indicación de su nombre, apellidos y domicilio, en escrito razonado en papel común y en el plazo máximo de un año, contado a partir del momento en que tuviera conocimiento de los hechos objeto de la misma.»", "fuente": "Artículo quince, apartado Uno · LO 3/1981"}]}, {"id": "ce-144", "origen": "otras", "test": "Examen", "n": 16, "enunciado": "Según la Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo, podrá dirigirse al Defensor del Pueblo:", "opciones": ["Toda persona natural o jurídica que invoque un interés legítimo, sin restricción alguna.", "Toda persona natural o jurídica que invoque un interés legítimo, siempre que sean nacionales españoles o residentes en España.", "Toda persona natural que invoque un interés legítimo, pero no las personas jurídicas.", "Toda persona natural que invoque un interés legítimo, excepto las personas menores de edad."], "bloque": "t1-defensor", "precepto": "Artículo diez, apartado Uno · LO 3/1981", "correcta": 0, "justificaciones": ["Es esta. Reproduce el artículo diez, apartado Uno, palabra por palabra, incluido el «sin restricción alguna».", "No. El precepto niega expresamente que la nacionalidad y la residencia sean impedimento.", "No. Las personas jurídicas sí pueden dirigirse al Defensor del Pueblo.", "No. La minoría de edad no es impedimento: el artículo la menciona para excluirla como obstáculo."], "arts": [], "citas": [{"texto": "«Podrá dirigirse al Defensor del Pueblo toda persona natural o jurídica que invoque un interés legítimo, sin restricción alguna. No podrán constituir impedimento para ello la nacionalidad, residencia, sexo, minoría de edad, la incapacidad legal del sujeto, el internamiento en un centro penitenciario o de reclusión o, en general, cualquier relación especial de sujeción o dependencia de una Administración o Poder público.»", "fuente": "Artículo diez, apartado Uno · LO 3/1981"}]}, {"id": "ce-145", "origen": "otras", "test": "Examen", "n": 20, "enunciado": "Señale la afirmación INCORRECTA en relación con la figura del Defensor del Pueblo:", "opciones": ["Las Cámaras nombrarán a los Adjuntos primero y segundo del Defensor del Pueblo, a propuesta de este.", "De las relaciones con el Defensor del Pueblo se encargará una Comisión Mixta Congreso-Senado cuyos acuerdos se adoptarán por mayoría simple.", "El Defensor del Pueblo cesará entre otras causas por actuar con notoria negligencia en el cumplimiento de las obligaciones y deberes del cargo.", "Corresponde la decisión sobre la inculpación, prisión, procesamiento y juicio de los Adjuntos del Defensor del Pueblo exclusivamente a la Sala de lo Penal del Tribunal Supremo."], "bloque": "t1-defensor", "precepto": "Artículo octavo · LO 3/1981; Artículo quinto, apartado Uno · LO 3/1981", "correcta": 0, "justificaciones": ["Es esta. Es la afirmación incorrecta, y por eso la que hay que marcar: el artículo octavo, Dos, dice lo contrario (los nombra y separa el propio Defensor del Pueblo, previa conformidad de las Cámaras), no las Cámaras a propuesta suya.", "No. Es correcta: la Comisión Mixta Congreso-Senado adopta sus acuerdos por mayoría simple (art. 2, Tres).", "No. Es correcta: la notoria negligencia es una de las cinco causas de cese del artículo quinto, Uno.", "No. Es correcta: el aforamiento ante la Sala de lo Penal del Tribunal Supremo alcanza también a los Adjuntos (art. 6, Tres y Cuatro)."], "arts": [], "citas": [{"texto": "«Uno. El Defensor del Pueblo estará auxiliado por un Adjunto Primero y un Adjunto Segundo, en los que podrá delegar sus funciones y que le sustituirán por su orden, en el ejercicio de las mismas, en los supuestos de imposibilidad temporal y en los de cese.»«Dos. El Defensor del Pueblo nombrará y separará a sus Adjuntos previa conformidad de las Cámaras en la forma que determinen sus Reglamentos.» · «Tres. El nombramiento de los Adjuntos será publicado en el «Boletín Oficial del Estado».»", "fuente": "Artículo octavo · LO 3/1981"}, {"texto": "«El Defensor del Pueblo cesará por alguna de las siguientes causas: Uno) Por renuncia. Dos) Por expiración del plazo de su nombramiento. Tres) Por muerte o por incapacidad sobrevenida. Cuatro) Por actuar con notoria negligencia en el cumplimiento de las obligaciones y deberes del cargo. Cinco) Por haber sido condenado, mediante sentencia firme, por delito doloso.»", "fuente": "Artículo quinto, apartado Uno · LO 3/1981"}], "truco": "Quién nombra a quién: las Cortes eligen al Defensor; el Defensor nombra a sus Adjuntos con la conformidad de las Cámaras. La iniciativa la tiene siempre el de arriba en su propia casa."}, {"id": "ce-146", "origen": "otras", "test": "Test 1", "n": 3, "enunciado": "El Defensor del Pueblo no puede intervenir:", "opciones": ["Cuando no haya existido intervención de las Administraciones públicas.", "Cuando se trate de conflictos entre particulares.", "Cuando haya transcurrido más de un año desde el momento en que el ciudadano haya tenido conocimiento de los hechos objeto de su queja.", "Todo lo anterior es correcto."], "bloque": "t1-defensor", "precepto": "Artículo noveno, apartado Uno · LO 3/1981; Artículo quince, apartado Uno · LO 3/1981", "correcta": 3, "justificaciones": ["No. Es cierta: sin intervención de una Administración pública no hay materia que investigar.", "No. Es cierta: los conflictos entre particulares quedan fuera de su competencia.", "No. Es cierta: transcurrido el año del artículo quince, Uno, la queja es extemporánea.", "Es esta. Las tres circunstancias se lo impiden: su ámbito son los actos de la Administración pública y sus agentes (art. 9, Uno) y la queja ha de presentarse dentro del año siguiente al conocimiento de los hechos (art. 15, Uno)."], "arts": [], "citas": [{"texto": "«El Defensor del Pueblo podrá iniciar y proseguir de oficio o a petición de parte, cualquier investigación conducente al esclarecimiento de los actos y resoluciones de la Administración pública y sus agentes, en relación con los ciudadanos, a la luz de lo dispuesto en el artículo ciento tres, uno, de la Constitución, y el respeto debido a los Derechos proclamados en su Título primero.»", "fuente": "Artículo noveno, apartado Uno · LO 3/1981"}, {"texto": "«Toda queja se presentará firmada por el interesado, con indicación de su nombre, apellidos y domicilio, en escrito razonado en papel común y en el plazo máximo de un año, contado a partir del momento en que tuviera conocimiento de los hechos objeto de la misma.»", "fuente": "Artículo quince, apartado Uno · LO 3/1981"}], "truco": "El Defensor del Pueblo necesita siempre una Administración enfrente. Sin acto o resolución administrativa de por medio, no hay queja que pueda tramitar."}, {"id": "ce-147", "origen": "otras", "test": "Test 1", "n": 13, "enunciado": "La competencia del Defensor del Pueblo se extiende a:", "opciones": ["La totalidad de órganos y autoridades de la Administración General del Estado, de las Administraciones de las Comunidades Autónomas y a las de las Administraciones Locales.", "La totalidad de órganos y autoridades de la Administración General del Estado y de las Administraciones de las Comunidades Autónomas.", "La totalidad de órganos y autoridades de la Administración General del Estado.", "Ninguna respuesta es correcta."], "bloque": "t1-defensor", "precepto": "Artículo noveno, apartado Uno · LO 3/1981; Artículo doce, apartado Uno · LO 3/1981", "correcta": 0, "justificaciones": ["Es esta. El artículo noveno le encomienda los actos y resoluciones de «la Administración pública y sus agentes» en general, el artículo doce le permite supervisar por sí mismo la actividad de las Comunidades Autónomas, y el artículo veintiséis se refiere a autoridades y funcionarios «incluso local».", "No. Se olvida de las Administraciones Locales, que también están sometidas a su supervisión.", "No. Se queda solo en la Administración General del Estado.", "No. Sí hay respuesta correcta: la que incluye también a las Administraciones Locales."], "arts": [], "citas": [{"texto": "«El Defensor del Pueblo podrá iniciar y proseguir de oficio o a petición de parte, cualquier investigación conducente al esclarecimiento de los actos y resoluciones de la Administración pública y sus agentes, en relación con los ciudadanos, a la luz de lo dispuesto en el artículo ciento tres, uno, de la Constitución, y el respeto debido a los Derechos proclamados en su Título primero.»", "fuente": "Artículo noveno, apartado Uno · LO 3/1981"}, {"texto": "«El Defensor del Pueblo podrá, en todo caso, de oficio o a instancia de parte, supervisar por sí mismo la actividad de la Comunidad Autónoma en el ámbito de competencias definido por esta Ley.»", "fuente": "Artículo doce, apartado Uno · LO 3/1981"}], "truco": "Las tres Administraciones: Estado, Comunidades Autónomas y entes locales. En las Comunidades con comisionado propio (Ararteko, Síndic de Greuges, Valedor do Pobo…) coordinan funciones, pero el Defensor del Pueblo no pierde competencia."}, {"id": "ce-168", "origen": "oficiales", "test": "INAP sept 2025", "n": 1, "enunciado": "Según el artículo 2 de la Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo, ¿qué Comisión se designará en las Cortes Generales para relacionarse con el Defensor del Pueblo e informar a los respectivos Plenos en cuantas ocasiones sea necesario?", "opciones": ["Una Comisión Mixta Congreso-Senado.", "Una Comisión Mixta de Control Parlamentario.", "Una Comisión Permanente Congreso-Senado.", "Una Comisión de Investigación."], "bloque": "t1-defensor", "precepto": "Artículo segundo, apartado dos, LO 3/1981", "correcta": 0, "justificaciones": ["Es esta. Una sola Comisión, y mixta: Congreso y Senado juntos.", "No. No se llama «de Control Parlamentario»; el nombre legal es Comisión Mixta Congreso-Senado.", "No. No es una Comisión Permanente: es mixta, y se reúne cuando lo acuerdan los Presidentes de ambas Cámaras y siempre para proponer candidato.", "No. Las Comisiones de investigación son otra cosa (76 CE) y no tienen relación con el Defensor del Pueblo."], "arts": [], "citas": [{"texto": "«Se designará en las Cortes Generales una Comisión Mixta Congreso-Senado encargada de relacionarse con el Defensor del Pueblo e informar a los respectivos Plenos en cuantas ocasiones sea necesario.»", "fuente": "Artículo segundo, apartado dos, LO 3/1981"}], "truco": "Esa misma Comisión Mixta es la que propone al candidato, y sus acuerdos se toman por mayoría simple. Luego el Pleno del Congreso lo elige por tres quintos."}]});
